# 检查是否已安装 ILSpy
$ilspyPath = "C:\Program Files\ILSpy\ilspycmd.exe"
if (Test-Path $ilspyPath) {
    Write-Host "ILSpy 已安装"
    & $ilspyPath --version
} else {
    Write-Host "ILSpy 未安装，开始安装..."
    winget install icsharpcode.ilspy --accept-source-urls --accept-package-agreements
}

# 直接使用 dotnet tool 路径
$toolPath = "$env:USERPROFILE\.dotnet\tools\.store\ilspycmd\10.1.0.8386\ilspycmd\10.1.0.8386\tools\net8.0\any\ilspycmd.exe"
if (Test-Path $toolPath) {
    Write-Host "找到: $toolPath"
    & $toolPath --version
} else {
    # 搜索实际位置
    Get-ChildItem -Path "$env:USERPROFILE\.dotnet" -Filter "ilspycmd.exe" -Recurse -File -ErrorAction SilentlyContinue | Select-Object -First 1 -ExpandProperty FullName
}

$srcDir = "D:\GitHub\H3\H3Trainer\src"

# 批量修复所有类库项目的语言版本
Get-ChildItem "$srcDir" -Filter "*.csproj" | ForEach-Object {
    $content = Get-Content $_.FullName -Raw
    if ($content -match 'LangVersion.*15\.0') {
        Write-Host "修复: $($_.Name)"
        $content = $content -replace '<LangVersion>15\.0</LangVersion>', '<LangVersion>latest</LangVersion>'
        Set-Content $_.FullName $content -NoNewline
    }
}

# 重新编译 WinAPI
Write-Host "`n=== 重新编译 WinAPI ==="
dotnet build "$srcDir\WinAPI\WinAPI.csproj" --verbosity quiet

