using System.Runtime.InteropServices;

namespace WinAPI.Win32;

public static class Kernel32
{
    [DllImport("kernel32.dll", EntryPoint = "OpenProcess")]
    public static extern nint OpenProcess(nint dwDesiredAccess, bool bInheritHandle, nint dwProcessId);

    [DllImport("kernel32.dll", EntryPoint = "CloseHandle")]
    public static extern bool CloseHandle(nint hObject);

    [DllImport("kernel32.dll", EntryPoint = "VirtualQueryEx", SetLastError = false)]
    public static extern long VirtualQueryEx(nint hProcess, nint lpAddress, out MemoryBasicInformation32 lpBuffer, nint dwLength);

    [DllImport("kernel32.dll", EntryPoint = "VirtualQueryEx", SetLastError = false)]
    public static extern long VirtualQueryEx(nint hProcess, nint lpAddress, out MemoryBasicInformation64 lpBuffer, nint dwLength);

    [DllImport("kernel32.dll", EntryPoint = "VirtualAllocEx", SetLastError = true)]
    public static extern nint VirtualAllocEx(nint hProcess, nint lpAddress, nint dwSize, nint flAllocationType, nint flProtect);

    [DllImport("kernel32.dll", EntryPoint = "VirtualProtectEx", SetLastError = true)]
    public static extern bool VirtualProtectEx(nint hProcess, nint lpAddress, nint dwSize, nint flNewProtect, out nint lpflOldProtect);

    [DllImport("kernel32.dll", EntryPoint = "ReadProcessMemory", SetLastError = true)]
    public static extern bool ReadProcessMemory(nint hProcess, nint lpBaseAddress, [Out] byte[] lpBuffer, nint nSize, out nint lpNumberOfBytesRead);

    [DllImport("kernel32.dll", EntryPoint = "WriteProcessMemory", SetLastError = true)]
    public static extern bool WriteProcessMemory(nint hProcess, nint lpBaseAddress, [In] byte[] lpBuffer, nint nSize, out nint lpNumberOfBytesWritten);

    [DllImport("kernel32.dll", EntryPoint = "CreateRemoteThread", SetLastError = true)]
    public static extern nint CreateRemoteThread(nint hProcess, nint lpThreadAttributes, uint dwStackSize, nint lpStartAddress, nint lpParameter, nint dwCreationFlags, out uint lpThreadId);

    [DllImport("kernel32.dll", EntryPoint = "CreateRemoteThreadEx", SetLastError = true)]
    public static extern nint CreateRemoteThreadEx(nint hProcess, nint lpThreadAttributes, uint dwStackSize, nint lpStartAddress, nint lpParameter, nint lpAttributeList, nint dwCreationFlags, out uint lpThreadId);

    [DllImport("kernel32.dll", EntryPoint = "WaitForSingleObjectEx", SetLastError = true)]
    public static extern uint WaitForSingleObjectEx(nint hHandle, uint dwMilliseconds, bool bAlertable);
}

