$srcDir = "D:\GitHub\H3\H3Trainer\src"

# 批量修复所有 csproj 的 LangVersion
Get-ChildItem "$srcDir" -Filter "*.csproj" -Recurse | ForEach-Object {
    $content = Get-Content $_.FullName -Raw
    if ($content -match '<LangVersion>15\.0</LangVersion>') {
        Write-Host "修复: $($_.Name)"
        $content = $content -replace '<LangVersion>15\.0</LangVersion>', '<LangVersion>latest</LangVersion>'
        Set-Content $_.FullName $content -NoNewline
    }
}

Write-Host "`n=== 重新编译所有类库 ==="
foreach ($proj in @("WinAPI", "HandyKits", "HoMM3", "HandyWpf", "HandyMvvm", "Training", "HandyWpfControl")) {
    Write-Host "编译 $proj..."
    dotnet build "$srcDir\$proj\$proj.csproj" --verbosity quiet 2>&1 | Select-String -Pattern "error|成功" | Select-Object -First 2
}

$srcDir = "D:\GitHub\H3\H3Trainer\src"

# 批量修复所有 csproj 文件
Get-ChildItem "$srcDir" -Filter "*.csproj" -Recurse | ForEach-Object {
    $content = Get-Content $_.FullName -Raw
    $changed = $false

    # 修复 LangVersion
    if ($content -match '<LangVersion>15\.0</LangVersion>') {
        $content = $content -replace '<LangVersion>15\.0</LangVersion>', '<LangVersion>latest</LangVersion>'
        $changed = $true
    }

    # 修复末尾的垃圾字符 (t></Project>)
    if ($content -match 't></Project>') {
        $content = $content -replace 't></Project>', '</Project>'
        $changed = $true
    }

    if ($changed) {
        Write-Host "修复: $($_.Name)"
        Set-Content $_.FullName $content -NoNewline
    }
}

# 编译 HandyKits
dotnet build "$srcDir\HandyKits\HandyKits.csproj" --verbosity quiet 2>&1 | Select-String -Pattern "error|成功"

Get-ChildItem "D:\GitHub\H3\H3Trainer\src\HandyWpf" -Filter "*.cs" -Recurse | ForEach-Object {
    Write-Host "=== $($_.Name) ==="
    Get-Content $_.FullName | Select-Object -First 20
}

