using System.Windows;

namespace HandyWpf.Extension;

public static class WindowExtension
{
	public static void SetToCenter(FrameworkElement parent, Window target)
	{
		//IL_0009: Unknown result type (might be due to invalid IL or missing references)
		//IL_000e: Unknown result type (might be due to invalid IL or missing references)
		//IL_0035: Unknown result type (might be due to invalid IL or missing references)
		//IL_003a: Unknown result type (might be due to invalid IL or missing references)
		Window window = Window.GetWindow((DependencyObject)(object)parent);
		Rect restoreBounds = window.RestoreBounds;
		target.Left = ((Rect)(ref restoreBounds)).X + (window.Width - target.Width) / 2.0;
		restoreBounds = window.RestoreBounds;
		target.Top = ((Rect)(ref restoreBounds)).Y + (window.Height - target.Height) / 2.0;
	}
}
