using System.Windows;

namespace HandyWpf.Extension;

public static class WindowExtension
{
    public static void SetToCenter(FrameworkElement parent, Window target)
    {
        Window window = Window.GetWindow(parent);
        Rect restoreBounds = window.RestoreBounds;
        target.Left = restoreBounds.X + (window.Width - target.Width) / 2.0;
        restoreBounds = window.RestoreBounds;
        target.Top = restoreBounds.Y + (window.Height - target.Height) / 2.0;
    }
}

