using System;
using System.ComponentModel;
using System.Runtime.CompilerServices;
using System.Windows;
using System.Windows.Controls;
using CommunityToolkit.Mvvm.Messaging;
using CommunityToolkit.Mvvm.Messaging.Messages;
using HandyMvvm.Messenger;
using HandyMvvm.Model.Computation;
using HandyWpfControl.Animation;

namespace HandyWpfControl.Progress;

public class TaskProgress : Control, INotifyPropertyChanged, IDisposable, IRecipient<ValueChangedMessage<TaskState>>, IRecipient<ValueChangedMessage<string>>
{
	public static readonly DependencyProperty TipsProperty;

	public static readonly DependencyProperty MessengerOnProperty;

	private string StartTip { get; set; } = "任务启动，请稍后...";

	private string PreparingTip { get; set; } = "准备中，请稍后...";

	private string ExecutingTip { get; set; } = "执行中，请稍后...";

	private string CompletedTip { get; set; } = "任务：已完成";

	private string CancellingTip { get; set; } = "任务：取消中...";

	private string CancelledTip { get; set; } = "任务：已取消";

	private string ErrorTip { get; set; } = "任务：出现错误";

	public bool MessengerOn
	{
		get
		{
			return (bool)((DependencyObject)this).GetValue(MessengerOnProperty);
		}
		set
		{
			((DependencyObject)this).SetValue(MessengerOnProperty, (object)value);
		}
	}

	public string Tips
	{
		get
		{
			return (string)((DependencyObject)this).GetValue(TipsProperty);
		}
		private set
		{
			((DependencyObject)this).SetValue(TipsProperty, (object)value);
			NotifyPropertyChanged("Tips");
		}
	}

	public event PropertyChangedEventHandler? PropertyChanged;

	public static void Send(string message)
	{
		MessengerCenter.Send<ValueChangedMessage<string>, string>(new ValueChangedMessage<string>(message));
	}

	private static void Register<TRecipient>(TRecipient recipient) where TRecipient : class, IRecipient<ValueChangedMessage<string>>
	{
		MessengerCenter.Register<TRecipient, ValueChangedMessage<string>>(recipient);
	}

	private static void Unregister<TRecipient>(TRecipient recipient) where TRecipient : class, IRecipient<ValueChangedMessage<string>>
	{
		MessengerCenter.Unregister<TRecipient, ValueChangedMessage<string>>(recipient);
	}

	private void NotifyPropertyChanged([CallerMemberName] string propertyName = "")
	{
		this.PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
	}

	private static void MessengerOnPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
	{
		if (d is TaskProgress taskProgress)
		{
			if ((bool)e.NewValue)
			{
				taskProgress.RegisterMessenger();
			}
			else
			{
				taskProgress.UnregisterMessenger();
			}
		}
	}

	static TaskProgress()
	{
		TipsProperty = DependencyProperty.Register("Tips", typeof(string), typeof(TaskProgress), new PropertyMetadata((object)"这里显示信息"));
		MessengerOnProperty = DependencyProperty.Register("MessengerOn", typeof(bool), typeof(TaskProgress), new PropertyMetadata((object)true, new PropertyChangedCallback(MessengerOnPropertyChanged)));
		FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(TaskProgress), (PropertyMetadata)(object)new FrameworkPropertyMetadata((object)typeof(TaskProgress)));
	}

	public TaskProgress()
	{
		base.Loaded += TaskProgress_Loaded;
		base.IsVisibleChanged += new DependencyPropertyChangedEventHandler(TaskProgress_IsVisibleChanged);
		if (MessengerOn)
		{
			RegisterMessenger();
		}
	}

	private void TaskProgress_Loaded(object sender, RoutedEventArgs e)
	{
		base.Visibility = Visibility.Collapsed;
	}

	private void TaskProgress_IsVisibleChanged(object sender, DependencyPropertyChangedEventArgs e)
	{
		if (sender is TaskProgress taskProgress)
		{
			if (taskProgress.Visibility == Visibility.Visible)
			{
				Sprite.Send(new ValueChangedMessage<bool>(value: true));
			}
			else
			{
				Sprite.Send(new ValueChangedMessage<bool>(value: false));
			}
		}
	}

	~TaskProgress()
	{
		Dispose();
	}

	public void Dispose()
	{
		UnregisterMessenger();
		GC.SuppressFinalize(this);
	}

	private void RegisterMessenger()
	{
		TaskStateMachine.Register(this);
		Register(this);
	}

	private void UnregisterMessenger()
	{
		TaskStateMachine.Unregister(this);
		Unregister(this);
	}

	public void Receive(ValueChangedMessage<TaskState> message)
	{
		if (message.Value == TaskState.Start)
		{
			base.Visibility = Visibility.Visible;
			Tips = StartTip;
		}
		else if (message.Value == TaskState.Preparing || message.Value == TaskState.Executing)
		{
			Tips = message.Value switch
			{
				TaskState.Preparing => PreparingTip, 
				TaskState.Executing => ExecutingTip, 
				_ => "=_=，这段字不应该出现", 
			};
		}
		else if (message.Value == TaskState.Completed || message.Value == TaskState.Idle)
		{
			base.Visibility = Visibility.Collapsed;
		}
		else if (message.Value != TaskState.Idle)
		{
			Tips = message.Value switch
			{
				TaskState.Cancelling => CancellingTip, 
				TaskState.Cancelled => CancelledTip, 
				TaskState.Error => ErrorTip, 
				_ => "=_=，这段字不应该出现", 
			};
		}
	}

	public void Receive(ValueChangedMessage<string> m)
	{
		Tips = m.Value;
	}
}

