using System;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Threading;

namespace HoMMsTrainer;

public partial class App : Application
{
	protected override void OnStartup(StartupEventArgs e)
	{
		base.OnStartup(e);
		Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);
		base.DispatcherUnhandledException += App_DispatcherUnhandledException;
		TaskScheduler.UnobservedTaskException += delegate(object? sender, UnobservedTaskExceptionEventArgs e2)
		{
			LogExceptionToFile(e2.Exception);
			e2.SetObserved();
		};

		try
		{
			MainWindow = new TrainerWindow();
			MainWindow.Show();
		}
		catch (Exception ex)
		{
			LogExceptionToFile(ex);
			MessageBox.Show("启动窗口失败: " + ex.Message + "\n\n" + ex.StackTrace, "错误", MessageBoxButton.OK, MessageBoxImage.Error);
			Shutdown(1);
		}
	}

	private void App_DispatcherUnhandledException(object sender, DispatcherUnhandledExceptionEventArgs e)
	{
		LogExceptionToFile(e.Exception);
		MessageBox.Show("发生了一个非预期的错误，程序将关闭，详细错误信息请查阅Error日志。", "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
		e.Handled = true;
		Shutdown();
	}

	private static void LogExceptionToFile(Exception ex)
	{
		try
		{
			string text = Path.Combine(Environment.CurrentDirectory, "Error");
			if (!Directory.Exists(text))
			{
				Directory.CreateDirectory(text);
			}
			using StreamWriter streamWriter = new StreamWriter(Path.Combine(text, $"Error_{DateTime.Now:yyyyMMdd_HHmmss}.log"), append: true);
			streamWriter.WriteLine($"Time: {DateTime.Now}");
			streamWriter.WriteLine("Message: " + ex.Message);
			streamWriter.WriteLine("StackTrace: " + ex.StackTrace);
			if (ex.InnerException != null)
			{
				streamWriter.WriteLine("Inner Exception:");
				LogExceptionToFile(ex.InnerException);
			}
		}
		catch (Exception ex2)
		{
			Console.WriteLine("Failed to log exception: " + ex2.Message);
		}
	}
}

