using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.Linq;
using System.Text;
using HandyKits.Extensions;
using HoMM3.BaseObj;
using HoMM3.Setting;
using MintPlayer.ObservableCollection;
using Training.Framework;
using Training.Game;

namespace HoMM3.Standard;

internal class TownService(ProcessIO process, ICollection<TownModel> models, ExeVersion version, MapVersion mapVersion) : Service<TownProperty, TownModel>(process, models)
{
	private int _blockAddressEnd;

	private int _townCount;

	internal void LockBuiltOn(TownModel town)
	{
		if (_addresses.TryGetValue(TownProperty.Built, out (int, int) value))
		{
			int memoryAddress = town.Address + value.Item1;
			_process.WriteProcessMemoryOn(memoryAddress, BitConverter.GetBytes(town.Built));
			town.Locking = true;
		}
	}

	internal void LockBuiltOff(TownModel town)
	{
		if (_addresses.TryGetValue(TownProperty.Built, out (int, int) value))
		{
			int memoryAddress = town.Address + value.Item1;
			_process.WriteProcessMemoryOff(memoryAddress);
			town.Locking = false;
		}
	}

	public override void LoadSettings()
	{
		_addresses.AddRange<TownProperty, (int, int)>(SetRoe.TownAddress);
		if (mapVersion == MapVersion.HoTA && version >= ExeVersion.HoTA16)
		{
			_addresses.AddRange<TownProperty, (int, int)>(SetHota.TownAddress);
			return;
		}
		foreach (KeyValuePair<TownProperty, (int, int)> item in SetHota.TownAddress)
		{
			if (!_addresses.Remove(item.Key))
			{
				break;
			}
		}
	}

	public override bool LoadData(int index)
	{
		if (index == _townCount)
		{
			return false;
		}
		if (_blockAddress > 0)
		{
			byte[] array = new byte[_blockSize];
			int num = _blockAddress + index * _blockSize;
			if (_process.ReadProcessMemory(num, array))
			{
				TownModel model = GetModel(index);
				model.RecordingDirtyData = false;
				model.Address = num;
				byte num2 = ReadToByte(TownProperty.NameAddressLength, array);
				int num3 = ReadToInt32(TownProperty.NameAddress, array);
				byte[] array2 = new byte[num2];
				if (_process.ReadProcessMemory(num3, array2))
				{
					model.Name = Encoding.GetEncoding("gb2312").GetString(array2);
				}
				model.ID = ReadToByte(TownProperty.ID, array);
				model.Flag = (PlayerFlag)ReadToByte(TownProperty.Flag, array);
				model.Built = ReadToByte(TownProperty.Built, array) == 1;
				model.GuildLv = ReadToByte(TownProperty.GuildLv, array);
				model.Faction = (Faction)ReadToByte(TownProperty.Faction, array);
				model.LocationX = ReadToByte(TownProperty.LocationX, array);
				model.LocationY = ReadToByte(TownProperty.LocationY, array);
				model.LocationZ = ReadToByte(TownProperty.LocationZ, array);
				model.HeroGuard = ReadToInt32(TownProperty.HeroGuard, array);
				model.HeroVisit = ReadToInt32(TownProperty.HeroVisit, array);
				model.GuildOpen1 = ReadToByte(TownProperty.GuildOpen1, array);
				model.GuildOpen2 = ReadToByte(TownProperty.GuildOpen2, array);
				model.GuildOpen3 = ReadToByte(TownProperty.GuildOpen3, array);
				model.GuildOpen4 = ReadToByte(TownProperty.GuildOpen4, array);
				model.GuildOpen5 = ReadToByte(TownProperty.GuildOpen5, array);
				model.MagicGuild11 = ReadToInt32(TownProperty.MagicGuild11, array);
				model.MagicGuild12 = ReadToInt32(TownProperty.MagicGuild12, array);
				model.MagicGuild13 = ReadToInt32(TownProperty.MagicGuild13, array);
				model.MagicGuild14 = ReadToInt32(TownProperty.MagicGuild14, array);
				model.MagicGuild15 = ReadToInt32(TownProperty.MagicGuild15, array);
				model.MagicGuild16 = ReadToInt32(TownProperty.MagicGuild16, array);
				if (!SetRoe.Spells.Any((Spell item) => item.Grade == 1 && item.ID == model.MagicGuild16))
				{
					model.MagicGuild16 = CheckSpell(1, model.MagicGuild16, model.MagicGuild11, model.MagicGuild12, model.MagicGuild13, model.MagicGuild14, model.MagicGuild15);
					AddToWritingData(TownProperty.MagicGuild16, model, model.MagicGuild16);
				}
				model.MagicGuild21 = ReadToInt32(TownProperty.MagicGuild21, array);
				model.MagicGuild22 = ReadToInt32(TownProperty.MagicGuild22, array);
				model.MagicGuild23 = ReadToInt32(TownProperty.MagicGuild23, array);
				model.MagicGuild24 = ReadToInt32(TownProperty.MagicGuild24, array);
				model.MagicGuild25 = ReadToInt32(TownProperty.MagicGuild25, array);
				if (!SetRoe.Spells.Any((Spell item) => item.Grade == 2 && item.ID == model.MagicGuild25))
				{
					model.MagicGuild25 = CheckSpell(2, model.MagicGuild25, model.MagicGuild21, model.MagicGuild22, model.MagicGuild23, model.MagicGuild24);
					AddToWritingData(TownProperty.MagicGuild25, model, model.MagicGuild25);
				}
				model.MagicGuild31 = ReadToInt32(TownProperty.MagicGuild31, array);
				model.MagicGuild32 = ReadToInt32(TownProperty.MagicGuild32, array);
				model.MagicGuild33 = ReadToInt32(TownProperty.MagicGuild33, array);
				model.MagicGuild34 = ReadToInt32(TownProperty.MagicGuild34, array);
				if (!SetRoe.Spells.Any((Spell item) => item.Grade == 3 && item.ID == model.MagicGuild34))
				{
					model.MagicGuild34 = CheckSpell(3, model.MagicGuild34, model.MagicGuild31, model.MagicGuild32, model.MagicGuild33);
					AddToWritingData(TownProperty.MagicGuild34, model, model.MagicGuild34);
				}
				model.MagicGuild41 = ReadToInt32(TownProperty.MagicGuild41, array);
				model.MagicGuild42 = ReadToInt32(TownProperty.MagicGuild42, array);
				model.MagicGuild43 = ReadToInt32(TownProperty.MagicGuild43, array);
				if (!SetRoe.Spells.Any((Spell item) => item.Grade == 4 && item.ID == model.MagicGuild43))
				{
