	private static void CreateTownBuildings(MintPlayer.ObservableCollection.ObservableCollection<TownBuildingModel> buildings, ReadOnlyCollection<Town> collection, ReadOnlyDictionary<TownBuilding, string> dictionary, TownBuilding built, TownBuilding tree, TownBuilding opened)
	{
		if (buildings.Count > collection.Count)
		{
			for (int i = collection.Count; i < buildings.Count; i++)
			{
				buildings.RemoveAt(i);
			}
		}
		for (int j = 0; j < collection.Count; j++)
		{
			TownBuildingModel townBuildingModel = buildings.ElementAtOrDefault(j);
			if (townBuildingModel == null)
			{
				townBuildingModel = new TownBuildingModel
				{
					Index = j
				};
				buildings.Add(townBuildingModel);
			}
			Town town = collection.ElementAt(j);
			townBuildingModel.RecordingDirtyData = false;
			townBuildingModel.BuildingBuilt = (built & town.Building) == town.Building;
			townBuildingModel.BuildingTree = (tree & town.Building) == town.Building;
			townBuildingModel.BuildingOpened = (opened & town.Building) == town.Building;
			townBuildingModel.BuildingFaction = town.Faction;
			townBuildingModel.BuildingBuilding = town.Building;
			townBuildingModel.BuildingName = dictionary[town.Building];
			townBuildingModel.BuildingSlot = town.BuildingSlot;
			townBuildingModel.RecordingDirtyData = true;
		}
		if (buildings.Any((TownBuildingModel item) => item.BuildingBuilding == TownBuilding.ResourceSilo && item.BuildingBuilt))
		{
			buildings.First((TownBuildingModel item) => item.BuildingBuilding == TownBuilding.Marketplace).BuildingBuilt = false;
		}
		if (buildings.Any((TownBuildingModel item) => item.BuildingFaction == Faction.Fortress && item.BuildingBuilding == TownBuilding.Unique3 && item.BuildingBuilt))
		{
			buildings.First((TownBuildingModel item) => item.BuildingBuilding == TownBuilding.Unique2).BuildingBuilt = false;
		}
		foreach (TownBuildingModel item in buildings.Where((TownBuildingModel item) => (item.BuildingBuilding == TownBuilding.Horde1 || item.BuildingBuilding == TownBuilding.UpgHorde1 || item.BuildingBuilding == TownBuilding.Horde2 || item.BuildingBuilding == TownBuilding.UpgHorde2) && item.BuildingBuilt))
		{
			if (SetRoe.HordeGenerator.TryGetValue((item.BuildingFaction, item.BuildingBuilding), out var slot))
			{
				TownBuilding gen = ((item.BuildingBuilding == TownBuilding.UpgHorde1 || item.BuildingBuilding == TownBuilding.UpgHorde2) ? TownBuilding.UpgGenerator1 : TownBuilding.Generator1);
				TownBuildingModel townBuildingModel2 = buildings.FirstOrDefault((TownBuildingModel item) => item.BuildingSlot == slot && item.BuildingBuilding >= gen);
				if (townBuildingModel2 != null)
				{
					townBuildingModel2.RecordingDirtyData = false;
					townBuildingModel2.BuildingBuilt = true;
					townBuildingModel2.RecordingDirtyData = true;
				}
			}
		}
	}

