#!/usr/bin/env python3
"""Replace foreach(Type var in ...) with foreach(var var in ...)"""
import re, os, glob

SRC = r'D:\GitHub\H3\H3Trainer\src'

BASIC_TYPES = {'string','object','int','bool','byte','char','double','float','long','short','void',
               'sbyte','ushort','uint','ulong','nint','nuint'}

def is_real_type(t):
    t = t.strip()
    if not t or t in ('var',) or ' var ' in t or t.startswith('var ') or t.endswith(' var'):
        return False
    if t in BASIC_TYPES:
        return True
    if t[0].isupper():
        return True
    if any(c in t for c in '<>[]'):
        return True
    return False

# Pattern: foreach ( Type var in ... ) where Type is not "var"
# Group 1: "foreach(" or "foreach (" (no space inside paren after opening)
# Group 2: whitespace after opening paren
# Group 3: type name
# Group 4: var name
PATTERN = re.compile(r'(foreach\s*)\(([ \t]*)([a-zA-Z_][a-zA-Z0-9_<>,\[\] ]*?)([a-zA-Z_][a-zA-Z0-9_]*?)\s+in\b')

def process_file(fpath):
    with open(fpath, 'rb') as f:
        data = f.read()
    if data.startswith(b'\xef\xbb\xbf'):
        text = data[3:].decode('utf-8-sig', errors='replace')
    else:
        text = data.decode('utf-8-sig', errors='replace')

    changes = []

    def replace(m):
        keyword = m.group(1)  # "foreach(" or "foreach ("
        ws = m.group(2)       # whitespace inside "("
        t = m.group(3).strip()
        v = m.group(4)
        if not is_real_type(t):
            return m.group(0)
        changes.append(f'L?: {t} {v} -> var {v}')
        return f'{keyword}({ws}var {v} in'

    new_text = PATTERN.sub(replace, text)

    if changes:
        rel = os.path.relpath(fpath, SRC)
        print(f'File: {rel} ({len(changes)} changes)')
        for c in changes[:20]:
            print(f'  {c}')
        if len(changes) > 20:
            print(f'  ... and {len(changes)-20} more')
        with open(fpath, 'wb') as f:
            f.write(new_text.encode('utf-8-sig'))

    return len(changes)

def main():
    cs_files = glob.glob(os.path.join(SRC, '**', '*.cs'), recursive=True)
    cs_files = [f for f in cs_files
                if '_decompiled' not in f and '_baml' not in f]
    total = 0
    for fpath in sorted(cs_files):
        n = process_file(fpath)
        total += n
    print(f'\nTotal: {total} foreach loops changed')

if __name__ == '__main__':
    main()

