using System.Runtime.InteropServices;

namespace WinAPI.Win32;

/// <summary>
/// 提供针对 Windows kernel32.dll 的 P/Invoke 封装，供外部进程内存读写与线程管理使用。
/// </summary>
public static class Kernel32
{
    /// <summary>
    /// 打开指定进程的句柄，获取 PROCESS_ALL_ACCESS 权限后可进行内存读写、远程线程创建等操作。
    /// </summary>
    /// <param name="dwDesiredAccess">进程访问权限标志，如 PROCESS_VM_READ | PROCESS_VM_WRITE 等</param>
    /// <param name="bInheritHandle">若为 true，生成的子进程将继承此句柄</param>
    /// <param name="dwProcessId">目标进程的 PID</param>
    /// <returns>进程句柄，失败返回 -1</returns>
    [DllImport("kernel32.dll", EntryPoint = "OpenProcess")]
    public static extern nint OpenProcess(nint dwDesiredAccess, bool bInheritHandle, nint dwProcessId);

    /// <summary>
    /// 关闭由 OpenProcess 或 CreateRemoteThread 等 API 返回的内核句柄，释放资源。
    /// </summary>
    /// <param name="hObject">待关闭的句柄</param>
    /// <returns>成功返回 true</returns>
    [DllImport("kernel32.dll", EntryPoint = "CloseHandle")]
    public static extern bool CloseHandle(nint hObject);

    /// <summary>
    /// 查询目标进程虚拟地址空间中从指定地址开始的内存区域基本信息（32位格式）。
    /// </summary>
    /// <param name="hProcess">目标进程句柄</param>
    /// <param name="lpAddress">查询的起始虚拟地址</param>
    /// <param name="lpBuffer">输出参数，接收 MemoryBasicInformation32 结构</param>
    /// <param name="dwLength">lpBuffer 的字节大小（固定为 sizeof(MemoryBasicInformation32)）</param>
    /// <returns>实际写入 lpBuffer 的字节数，失败返回 0</returns>
    [DllImport("kernel32.dll", EntryPoint = "VirtualQueryEx", SetLastError = false)]
    public static extern long VirtualQueryEx(nint hProcess, nint lpAddress, out MemoryBasicInformation32 lpBuffer, nint dwLength);

    /// <summary>
    /// 查询目标进程虚拟地址空间中从指定地址开始的内存区域基本信息（64位格式）。
    /// </summary>
    /// <param name="hProcess">目标进程句柄</param>
    /// <param name="lpAddress">查询的起始虚拟地址（64位地址）</param>
    /// <param name="lpBuffer">输出参数，接收 MemoryBasicInformation64 结构</param>
    /// <param name="dwLength">lpBuffer 的字节大小（固定为 sizeof(MemoryBasicInformation64)）</param>
    /// <returns>实际写入 lpBuffer 的字节数，失败返回 0</returns>
    [DllImport("kernel32.dll", EntryPoint = "VirtualQueryEx", SetLastError = false)]
    public static extern long VirtualQueryEx(nint hProcess, nint lpAddress, out MemoryBasicInformation64 lpBuffer, nint dwLength);

    /// <summary>
    /// 在目标进程的虚拟地址空间中分配新内存区域。
    /// </summary>
    /// <param name="hProcess">目标进程句柄</param>
    /// <param name="lpAddress">期望的分配起始地址，传 0 由系统决定</param>
    /// <param name="dwSize">要分配的字节数</param>
    /// <param name="flAllocationType">分配类型，如 MEM_COMMIT | MEM_RESERVE</param>
    /// <param name="flProtect">页面保护属性，如 PAGE_READWRITE</param>
    /// <returns>成功返回分配区域的起始地址，失败返回 0</returns>
    [DllImport("kernel32.dll", EntryPoint = "VirtualAllocEx", SetLastError = true)]
    public static extern nint VirtualAllocEx(nint hProcess, nint lpAddress, nint dwSize, nint flAllocationType, nint flProtect);

    /// <summary>
    /// 修改目标进程已分配内存区域的页面保护属性。
    /// </summary>
    /// <param name="hProcess">目标进程句柄</param>
    /// <param name="lpAddress">待修改区域的起始地址</param>
    /// <param name="dwSize">区域大小（字节）</param>
    /// <param name="flNewProtect">新的页面保护属性，如 PAGE_READWRITE</param>
    /// <param name="lpflOldProtect">输出参数，接收修改前的保护属性</param>
    /// <returns>成功返回 true</returns>
    [DllImport("kernel32.dll", EntryPoint = "VirtualProtectEx", SetLastError = true)]
    public static extern bool VirtualProtectEx(nint hProcess, nint lpAddress, nint dwSize, nint flNewProtect, out nint lpflOldProtect);

    /// <summary>
    /// 从目标进程的指定地址读取原始字节数组。
    /// </summary>
    /// <param name="hProcess">目标进程句柄</param>
    /// <param name="lpBaseAddress">读取起始地址</param>
    /// <param name="lpBuffer">输出数组，接收读取的字节</param>
    /// <param name="nSize">要读取的字节数</param>
    /// <param name="lpNumberOfBytesRead">输出参数，实际读取的字节数</param>
    /// <returns>成功返回 true</returns>
    [DllImport("kernel32.dll", EntryPoint = "ReadProcessMemory", SetLastError = true)]
    public static extern bool ReadProcessMemory(nint hProcess, nint lpBaseAddress, [Out] byte[] lpBuffer, nint nSize, out nint lpNumberOfBytesRead);

    /// <summary>
    /// 将原始字节数组写入目标进程的指定地址。
    /// </summary>
    /// <param name="hProcess">目标进程句柄</param>
    /// <param name="lpBaseAddress">写入起始地址</param>
    /// <param name="lpBuffer">输入字节数组</param>
    /// <param name="nSize">写入的字节数</param>
    ///param name="lpNumberOfBytesWritten">输出参数，实际写入的字节数</param>
    /// <returns>成功返回 true</returns>
    [DllImport("kernel32.dll", EntryPoint = "WriteProcessMemory", SetLastError = true)]
    public static extern bool WriteProcessMemory(nint hProcess, nint lpBaseAddress, [In] byte[] lpBuffer, nint nSize, out nint lpNumberOfBytesWritten);

    /// <summary>
    /// 在目标进程地址空间中创建一个远程线程，执行指定函数。
    /// 常用于 DLL 注入：将 LoadLibrary 地址作为线程函数地址，DLL 路径作为参数传入。
    /// </summary>
    /// <param name="hProcess">目标进程句柄</param>
    /// <param name="lpThreadAttributes">线程安全描述符，传 null 使用默认</param>
    /// <param name="dwStackSize">初始栈大小，0 表示使用默认值</param>
    /// <param name="lpStartAddress">线程入口函数地址（目标进程内）</param>
    /// <param name="lpParameter">传入线程函数的参数</param>
    /// <param name="dwCreationFlags">创建标志，如 CREATE_SUSPENDED</param>
    /// <param name="lpThreadId">输出参数，返回新线程 ID</param>
    /// <returns>成功返回线程句柄，失败返回 0</returns>
    [DllImport("kernel32.dll", EntryPoint = "CreateRemoteThread", SetLastError = true)]
    public static extern nint CreateRemoteThread(nint hProcess, nint lpThreadAttributes, uint dwStackSize, nint lpStartAddress, nint lpParameter, nint dwCreationFlags, out uint lpThreadId);

    /// <summary>
    /// CreateRemoteThread 的扩展版本，支持更多属性（如句柄继承列表）。
    /// </summary>
    /// <param name="lpAttributeList">扩展属性列表，传 0 表示无扩展属性</param>
    [DllImport("kernel32.dll", EntryPoint = "CreateRemoteThreadEx", SetLastError = true)]
    public static extern nint CreateRemoteThreadEx(nint hProcess, nint lpThreadAttributes, uint dwStackSize, nint lpStartAddress, nint lpParameter, nint lpAttributeList, nint dwCreationFlags, out uint lpThreadId);

    /// <summary>
    /// 等待指定内核对象变为有信号状态。可用于等待远程线程执行完成（传线程句柄）。
    /// </summary>
    /// <param name="hHandle">待等待的内核对象句柄（如线程句柄）</param>
    /// <param name="dwMilliseconds">超时时间（毫秒），0xFFFFFFFF 表示无限等待</param>
    /// <param name="bAlertable">为 true 时可在等待期间处理 APC 队列</param>
    /// <returns>返回值：WAIT_OBJECT_0(0) 表示对象有信号，WAIT_TIMEOUT(258) 表示超时</returns>
    [DllImport("kernel32.dll", EntryPoint = "WaitForSingleObjectEx", SetLastError = true)]
