using System.Windows;

namespace HandyWpf.Extension;

/// <summary>
/// WPF Window 的扩展方法集合，提供窗口布局相关的辅助功能。
/// </summary>
public static class WindowExtension
{
    /// <summary>
    /// 将 target 窗口相对于 parent 所在的主窗口居中显示。
    /// 计算基于主窗口的 RestoreBounds（还原后的窗口位置和尺寸），
    /// 确保在窗口最大化/最小化后恢复时仍能正确居中。
    /// </summary>
    /// <param name="parent">任意 WPF 子元素，从中获取所在窗口</param>
    /// <param name="target">待居中的窗口实例</param>
    public static void SetToCenter(FrameworkElement parent, Window target)
    {
        // 获取 parent 所在的 Window（如果 parent 本身是 Window 则直接返回）
        Window window = Window.GetWindow(parent);

        // 读取主窗口还原后的几何信息（而非 CurrentBounds，避免窗口被拖出屏幕时计算错误）
        Rect restoreBounds = window.RestoreBounds;

        // 水平居中：主窗口左上角 X + (主窗口宽 - 目标窗口宽) / 2
        target.Left = restoreBounds.X + (window.Width - target.Width) / 2.0;

        // 重新读取 RestoreBounds（水平计算可能影响窗口状态，重新取值更安全）
        restoreBounds = window.RestoreBounds;

        // 垂直居中：主窗口左上角 Y + (主窗口高 - 目标窗口高) / 2
        target.Top = restoreBounds.Y + (window.Height - target.Height) / 2.0;
    }
}

