namespace HandyKits.Algorithm;

public static class Fundamental
{
	public static int Sunday(byte[] text, byte[] pattern)
	{
		int num = text.Length;
		int num2 = pattern.Length;
		int[] oCC = GetOCC(pattern);
		int num3;
		for (int i = 0; i <= num - num2; i += num3)
		{
			int j;
			for (j = 0; j < num2 && text[i + j] == pattern[j]; j++)
			{
			}
			if (j == num2)
			{
				return i;
			}
			num3 = ((i + num2 >= num) ? 1 : (num2 - oCC[text[i + num2]]));
		}
		return -1;
	}

	private static int[] GetOCC(byte[] pattern)
	{
		int[] array = new int[256];
		for (int i = 0; i < array.Length; i++)
		{
			array[i] = -1;
		}
		for (int j = 0; j < pattern.Length; j++)
		{
			array[pattern[j]] = j;
		}
		return array;
	}
}

