using System;
using System.Collections.Generic;
using System.IO;

namespace HandyKits.Tool;

public class IniParser
{
	private readonly Dictionary<string, Dictionary<string, string>> _data = new Dictionary<string, Dictionary<string, string>>();

	public void Load(string filePath)
	{
		_data.Clear();
		string key = "";
		string[] array = File.ReadAllLines(filePath);
		for (int i = 0; i < array.Length; i++)
		{
			string text = array[i].Trim();
			if (string.IsNullOrEmpty(text) || text.StartsWith(';'))
			{
				continue;
			}
			if (text.StartsWith('[') && text.EndsWith(']'))
			{
				string text2 = text;
				key = text2.Substring(1, text2.Length - 1 - 1);
				if (!_data.ContainsKey(key))
				{
					_data[key] = new Dictionary<string, string>();
				}
			}
			else
			{
				string[] array2 = text.Split(new char[1] { '=' }, 2, StringSplitOptions.RemoveEmptyEntries);
				if (array2.Length == 2)
				{
					_data[key][array2[0]] = array2[1];
				}
			}
		}
	}

	public void Save(string filePath)
	{
		using StreamWriter streamWriter = new StreamWriter(filePath);
		foreach (KeyValuePair<string, Dictionary<string, string>> datum in _data)
		{
			streamWriter.WriteLine("[" + datum.Key + "]");
			foreach (KeyValuePair<string, string> item in datum.Value)
			{
				streamWriter.WriteLine(item.Key + "=" + item.Value);
			}
			streamWriter.WriteLine();
		}
	}

	public string? GetValue(string section, string key, string? defaultValue = null)
	{
		if (!_data.TryGetValue(section, out Dictionary<string, string>? value) || !value.TryGetValue(key, out var value2))
		{
			return defaultValue;
		}
		return value2;
	}

	public void SetValue(string section, string key, string value)
	{
		if (!_data.ContainsKey(section))
		{
			_data[section] = new Dictionary<string, string>();
		}
		_data[section][key] = value;
	}
}

