namespace HandyKits.Algorithm;

/// <summary>
/// 基础字符串/字节数组搜索算法实现。
/// </summary>
public static class Fundamental
{
    /// <summary>
    /// 使用 Sunday 快速匹配算法在 text 中查找 pattern 首次出现的位置。
    /// Sunday 算法的平均时间复杂度为 O(n)，在模式较短时性能优于 KMP。
    /// </summary>
    /// <param name="text">待搜索的字节数组（文本）</param>
    /// <param name="pattern">要查找的字节模式</param>
    /// <returns>匹配成功返回 text 中的起始下标，失败返回 -1</returns>
    public static int Sunday(byte[] text, byte[] pattern)
    {
        int textLen = text.Length;
        int patternLen = pattern.Length;

        // 构建"出现位置表"（Occurrence Table）：
        // 对于模式中每个字节值，记录其最右出现位置（从右向左，从 0 开始计数）
        // 模式中未出现的字节默认为 -1
        int[] occ = GetOCC(pattern);

        int i = 0;
        while (i <= textLen - patternLen)
        {
            // 从左向右逐字节比较
            int j = 0;
            while (j < patternLen && text[i + j] == pattern[j])
            {
                j++;
            }

            // j == patternLen 表示全部匹配
            if (j == patternLen)
            {
                return i;
            }

            // Sunday 跳转规则：
            // 考察 text 中"模式串尾部之后"的第一个字节（i + patternLen 位置）
            // 若该字节在 occ 表中有记录，跳转 (patternLen - occ[该字节]) 步
            // 若该字节不在模式中，跳转 patternLen + 1 步（最大跳转）
            if (i + patternLen >= textLen)
            {
                i += 1; // 已接近文本尾部，仅右移一步
            }
            else
            {
                i += (patternLen - occ[text[i + patternLen]]);
            }
        }

        return -1; // 未找到
    }

    /// <summary>
    /// 构建 Sunday 算法的 Occurrence 表（O = 256，即字节值的全范围）。
    /// 表中记录每个字节值在模式串中最右侧出现的位置（从 0 开始）。
    /// 模式中未出现的字节值为 -1。
    /// </summary>
    /// <param name="pattern">目标模式串</param>
    /// <returns>256 长度的 int 数组</returns>
    private static int[] GetOCC(byte[] pattern)
    {
        // 初始化：所有字节默认未出现（-1）
        int[] occ = new int[256];
        for (int i = 0; i < occ.Length; i++)
        {
            occ[i] = -1;
        }

        // 记录每个字节在模式中最右出现的位置（从左向右遍历）
        for (int j = 0; j < pattern.Length; j++)
        {
            occ[pattern[j]] = j;
        }

        return occ;
    }
}

using System.Collections.Generic;

namespace HandyKits.Extensions;

/// <summary>
/// Dictionary 的扩展方法，提供批量合并键值对的功能。
/// </summary>
public static class DictionaryExtensions
{
    /// <summary>
    /// 将键值对序列批量添加到字典中。
    /// 若 Key 已存在，则覆盖其值（而非抛出异常）。
    /// </summary>
    /// <typeparam name="TKey">键类型（约束为 notnull）</typeparam>
    /// <typeparam name="TValue">值类型</typeparam>
    /// <param name="dictionary">目标字典（this）</param>
    /// <param name="keyValuePairs">待添加的键值对序列</param>
    public static void AddRange<TKey, TValue>(this Dictionary<TKey, TValue> dictionary, IEnumerable<KeyValuePair<TKey, TValue>> keyValuePairs) where TKey : notnull
    {
        foreach (KeyValuePair<TKey, TValue> kv in keyValuePairs)
        {
            // TryAdd 在 Key 已存在时跳过；随后强制赋值确保覆盖
            if (!dictionary.TryAdd(kv.Key, kv.Value))
            {
                dictionary[kv.Key] = kv.Value;
            }
        }
    }
}

using System;
using System.Text;

namespace HandyKits.Tool;

/// <summary>
/// 字节编码转换工具，提供定长字节数组与字符串之间的互转。
/// 编码采用 GB2312（简体中文 Windows 默认 ANSI 编码），用于读写INI等老式文件格式。
/// </summary>
public static class Converter
{
    /// <summary>
    /// 将字符串转换为固定长度的 GB2312 字节数组。
    /// 若字符串长度不足 length，则在尾部补零（\0）；若超出则截断。
    /// </summary>
    /// <param name="source">源字符串</param>
    /// <param name="length">目标字节数组的固定长度</param>
    /// <returns>定长字节数组，总长度为 length</returns>
    public static byte[] CharacterToBytes(string source, int length)
    {
        // 用 StringBuilder 构建目标长度字符串，不足部分补 '\0'
        StringBuilder sb = new StringBuilder(source);
        for (int i = source.Length; i < length; i++)
        {
            sb.Append('\0');
        }

        // GB2312 编码
        string s = sb.ToString();
        byte[] gb2312Bytes = Encoding.GetEncoding("gb2312").GetBytes(s);

        // 复制到定长数组（截断超出部分）
        byte[] result = new byte[length];
        Array.Copy(gb2312Bytes, result, length);
        return result;
    }
}

using System;
using System.IO;

namespace HandyKits.Tool;

/// <summary>
/// 文件系统辅助工具，提供目录创建等 IO 操作。
/// </summary>
public static class IO
{
    /// <summary>
    /// 在应用程序当前工作目录下创建多层子目录（若不存在）。
    /// 本质是对 Directory.CreateDirectory 的便捷封装，自动处理路径拼接。
    /// </summary>
    /// <param name="path">可变参数，表示子目录层级（如 "config", "data"），
    /// 将依次拼接在 Environment.CurrentDirectory 之后</param>
    public static void CreatePath(params string[] path)
    {
        string fullPath = Path.Combine(Environment.CurrentDirectory, Path.Combine(path));
        if (!Directory.Exists(fullPath))
        {
            Directory.CreateDirectory(fullPath);
        }
    }
}

namespace HandyKits.Tool;

/// <summary>
/// 序列化模型的接口契约。任何需要持久化的数据模型可实现此接口，
/// 由 Serializer 负责调用 Write / Read 完成 XML 序列化。
/// </summary>
/// <typeparam name="T">实现类类型，本身约束为引用类型</typeparam>
public interface ISerializeModel<T> where T : class
{
    /// <summary>将模型数据写入存储介质（由实现类决定格式）</summary>
    void Write(T model);

    /// <summary>从存储介质读取数据填充模型（由实现类决定格式）</summary>
    void Read(T model);
}

using System;
using System.IO;
using System.Runtime.Serialization;

namespace HandyKits.Tool;

/// <summary>
/// 基于 DataContractSerializer 的 XML 序列化/反序列化工具。
/// 支持将任意对象写入 XML 文件，以及从 XML 文件恢复对象实例。
/// </summary>
public static class Serializer
{
    /// <summary>
    /// 在应用程序当前工作目录下创建多层子目录（若不存在）。
    /// </summary>
    /// <param name="path">可变参数子目录层级</param>
    public static void CreatePath(params string[] path)
    {
        string fullPath = Path.Combine(Environment.CurrentDirectory, Path.Combine(path));
        if (!Directory.Exists(fullPath))
        {
            Directory.CreateDirectory(fullPath);
        }
    }

    /// <summary>
    /// 将对象序列化为 XML 文件（覆盖写入）。
    /// </summary>
    /// <typeparam name="T">对象类型，约束为引用类型</typeparam>
    /// <param name="obj">待序列化对象</param>
    /// <param name="dir">目标目录（相对工作目录）</param>
    /// <param name="fileName">文件名（含扩展名）</param>
    public static void SaveObjectToXml<T>(T obj, string dir, string fileName) where T : class
    {
        string fullPath = Path.Combine(dir, fileName);

        // FileShare.None：序列化期间禁止其他进程读写文件
        using FileStream stream = new FileStream(fullPath, FileMode.Create, FileAccess.Write, FileShare.None);

        // DataContractSerializer 要求类型有默认构造函数，且成员 public 或用 DataMember 标记
        new DataContractSerializer(typeof(T)).WriteObject((Stream)stream, (object?)obj);
    }

    /// <summary>
    /// 从 XML 文件反序列化为对象实例。
    /// </summary>
    /// <typeparam name="T">对象类型，约束为引用类型</typeparam>
    /// <param name="dir">文件所在目录</param>
    /// <param name="fileName">文件名</param>
    /// <returns>反序列化后的对象，若文件不存在或读取失败返回 null</returns>
    public static T? LoadObjectFromXml<T>(string dir, string fileName) where T : class
    {
        string fullPath = Path.Combine(dir, fileName);

        using FileStream stream = new FileStream(fullPath, FileMode.Open, FileAccess.Read, FileShare.Read);

        // ReadObject 返回 object，as T 尝试转换，失败返回 null
        return new DataContractSerializer(typeof(T)).ReadObject((Stream)stream) as T;
    }
}

using System;
using System.Collections.Generic;
using System.IO;

namespace HandyKits.Tool;

/// <summary>
/// INI 配置文件读写器。
/// 支持标准的 [Section] / Key=Value 格式，以分号（;）开头的行为注释。
/// </summary>
public class IniParser
{
    // 内部结构：外层字典的 Key = Section 名，内层字典的 Key = 配置项名
    private readonly Dictionary<string, Dictionary<string, string>> _data = new Dictionary<string, Dictionary<string, string>>();

    /// <summary>
    /// 从指定路径加载 INI 文件内容到内存。
    /// 加载前会先 Clear 现有数据。
    /// </summary>
    /// <param name="filePath">INI 文件的完整路径</param>
    public void Load(string filePath)
    {
        _data.Clear();

        string currentSection = ""; // 初始节名为空（全局节）
        string[] lines = File.ReadAllLines(filePath);

        for (int i = 0; i < lines.Length; i++)
        {
            string line = lines[i].Trim();

            // 跳过空行和注释行（以分号开头）
            if (string.IsNullOrEmpty(line) || line.StartsWith(';'))
            {
                continue;
            }

            // 节头：[SectionName]
            if (line.StartsWith('[') && line.EndsWith(']'))
            {
                currentSection = line.Substring(1, line.Length - 2);
                if (!_data.ContainsKey(currentSection))
                {
                    _data[currentSection] = new Dictionary<string, string>();
                }
            }
            // 键值对：Key=Value（Split 限制为最多分割 2 段，防止 Value 中含 =）
            else
            {
                string[] parts = line.Split(new char[1] { '=' }, 2, StringSplitOptions.RemoveEmptyEntries);
                if (parts.Length == 2)
                {
                    _data[currentSection][parts[0]] = parts[1];
                }
            }
        }
    }

    /// <summary>
    /// 将内存中的配置数据写回 INI 文件（覆盖）。
    /// </summary>
    /// <param name="filePath">目标文件路径</param>
    public void Save(string filePath)
    {
        using StreamWriter sw = new StreamWriter(filePath);

        foreach (KeyValuePair<string, Dictionary<string, string>> section in _data)
        {
            sw.WriteLine("[" + section.Key + "]");
            foreach (KeyValuePair<string, string> kv in section.Value)
            {
                sw.WriteLine(kv.Key + "=" + kv.Value);
            }
            sw.WriteLine(); // 节之间加空行
        }
    }

    /// <summary>
    /// 读取指定节和键对应的值。
    /// </summary>
    /// <param name="section">节名</param>
    /// <param name="key">键名</param>
    /// <param name="defaultValue">键不存在时返回的默认值（可为 null）</param>
    /// <returns>配置值，不存在时返回 defaultValue</returns>
    public string? GetValue(string section, string key, string? defaultValue = null)
    {
        if (!_data.TryGetValue(section, out Dictionary<string, string>? sectionDict)
            || !sectionDict.TryGetValue(key, out var value))
        {
            return defaultValue;
        }
        return value;
    }

    /// <summary>
    /// 写入或更新指定节和键的值。
    /// 若节不存在，会自动创建；若键已存在则覆盖。
    /// </summary>
    /// <param name="section">节名</param>
    /// <param name="key">键名</param>
    /// <param name="value">配置值</param>
    public void SetValue(string section, string key, string value)
    {
        if (!_data.ContainsKey(section))
        {
            _data[section] = new Dictionary<string, string>();
        }
        _data[section][key] = value;
    }
}

