using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using CommunityToolkit.Mvvm.Messaging;
using CommunityToolkit.Mvvm.Messaging.Messages;

namespace HandyMvvm.Messenger;

public static class MessengerCenter
{
	private static readonly Dictionary<string, int> channel = new Dictionary<string, int>();

	public static void RegisterChannel(string name)
	{
		if (!channel.ContainsKey(name))
		{
			int num = ((channel.Count > 0) ? channel.Max<KeyValuePair<string, int>>((KeyValuePair<string, int> item) => item.Value) : 0);
			channel.Add(name, ++num);
		}
	}

	public static void UnregisterChannel(string name)
	{
		channel.Remove(name);
	}

	public static void Send<TMessage, TValue>(TMessage message) where TMessage : ValueChangedMessage<TValue>
	{
		Type typeFromHandle = typeof(TMessage);
		if (channel.TryGetValue(typeFromHandle.Name, out var value))
		{
			StrongReferenceMessenger.Default.Send(message, value);
		}
	}

	public static TResponse? Request<TMessage, TResponse>(TMessage message) where TMessage : RequestMessage<TResponse>
	{
		Type typeFromHandle = typeof(TMessage);
		if (channel.TryGetValue(typeFromHandle.Name, out var value))
		{
			return StrongReferenceMessenger.Default.Send(message, value).Response;
		}
		return default(TResponse);
	}

	public static async Task<TResponse?> AsyncRequest<TMessage, TResponse>(TMessage message) where TMessage : AsyncRequestMessage<TResponse>
	{
		Type typeFromHandle = typeof(TMessage);
		if (channel.TryGetValue(typeFromHandle.Name, out var value))
		{
			return await StrongReferenceMessenger.Default.Send(message, value).Response;
		}
		return default(TResponse);
	}

	public static void Register<TRecipient, TMessage>(TRecipient recipient) where TRecipient : class, IRecipient<TMessage> where TMessage : class
	{
		Type typeFromHandle = typeof(TMessage);
		RegisterChannel(typeFromHandle.Name);
		if (channel.TryGetValue(typeFromHandle.Name, out var value) && !StrongReferenceMessenger.Default.IsRegistered<TRecipient, int>(recipient, value))
		{
			StrongReferenceMessenger.Default.Register(recipient, value, delegate(TRecipient r, TMessage m)
			{
				r.Receive(m);
			});
		}
	}

	public static void Unregister<TRecipient, TMessage>(TRecipient recipient) where TRecipient : class, IRecipient<TMessage> where TMessage : class
	{
		Type typeFromHandle = typeof(TMessage);
		if (channel.TryGetValue(typeFromHandle.Name, out var value))
		{
			StrongReferenceMessenger.Default.Unregister<TRecipient, int>(recipient, value);
		}
	}

	public static void Reset()
	{
		StrongReferenceMessenger.Default.Reset();
	}
}

