using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using CommunityToolkit.Mvvm.Messaging;
using CommunityToolkit.Mvvm.Messaging.Messages;

namespace HandyMvvm.Messenger;

/// <summary>
/// 基于 CommunityToolkit.Mvvm 的 StrongReferenceMessenger 的封装类，
/// 提供通道（Channel）概念的消息收发机制。
///
/// 使用方式：
/// 1. 调用 Register 注册消息接收者
/// 2. 调用 Send / Request / AsyncRequest 发送消息
///
/// Channel 概念：每种消息类型自动分配一个整数 ID，接收者与发送者通过消息类型名对齐。
/// </summary>
public static class MessengerCenter
{
    // 通道表：Key = 消息类型名，Value = 该类型的唯一整数通道 ID
    private static readonly Dictionary<string, int> channel = new Dictionary<string, int>();

    /// <summary>
    /// 注册一个消息类型的通道（若尚未注册则分配新 ID）。
    /// 同一消息类型多次调用无副作用。
    /// </summary>
    /// <param name="name">消息类型名称（通常传 typeof(TMessage).Name）</param>
    public static void RegisterChannel(string name)
    {
        if (!channel.ContainsKey(name))
        {
            // 若已有通道，取最大 ID + 1；否则从 1 开始
            int nextId = (channel.Count > 0)
                ? channel.Max(kv => kv.Value) + 1
                : 0;
            channel.Add(name, nextId);
        }
    }

    /// <summary>
    /// 注销指定消息类型的通道。
    /// </summary>
    /// <param name="name">消息类型名</param>
    public static void UnregisterChannel(string name)
    {
        channel.Remove(name);
    }

    /// <summary>
    /// 单向广播消息（fire-and-forget），发送给已注册该类型的全部接收者。
    /// 发送后不等待任何响应。
    /// </summary>
    /// <typeparam name="TMessage">ValueChangedMessage 子类，表示消息类型</typeparam>
    /// <typeparam name="TValue">消息携带的数据类型</typeparam>
    /// <param name="message">消息实例</param>
    public static void Send<TMessage, TValue>(TMessage message) where TMessage : ValueChangedMessage<TValue>
    {
        Type msgType = typeof(TMessage);
        if (channel.TryGetValue(msgType.Name, out var channelId))
        {
            StrongReferenceMessenger.Default.Send(message, channelId);
        }
    }

    /// <summary>
    /// 同步请求-响应模式（单播）：向已注册该类型的接收者发送消息并等待返回值。
    /// 若无接收者或通道未注册，返回 default(TResponse)。
    /// 注意：应确保只有一个接收者，否则行为不确定。
    /// </summary>
    /// <typeparam name="TMessage">RequestMessage 子类</typeparam>
    /// <typeparam name="TResponse">响应数据类型</typeparam>
    /// <param name="message">请求消息实例</param>
    /// <returns>接收者返回的值，无接收者时返回 default</returns>
    public static TResponse? Request<TMessage, TResponse>(TMessage message) where TMessage : RequestMessage<TResponse>
    {
        Type msgType = typeof(TMessage);
        if (channel.TryGetValue(msgType.Name, out var channelId))
        {
            return StrongReferenceMessenger.Default.Send(message, channelId).Response;
        }
        return default(TResponse);
    }

    /// <summary>
    /// 异步请求-响应模式：发送消息并异步等待接收者返回。
    /// 用于跨线程或耗时操作的请求响应场景。
    /// </summary>
    /// <typeparam name="TMessage">AsyncRequestMessage 子类</typeparam>
    /// <typeparam name="TResponse">响应数据类型</typeparam>
    /// <param name="message">请求消息实例</param>
    /// <returns>包含响应值的 Task</returns>
    public static async Task<TResponse?> AsyncRequest<TMessage, TResponse>(TMessage message) where TMessage : AsyncRequestMessage<TResponse>
    {
        Type msgType = typeof(TMessage);
        if (channel.TryGetValue(msgType.Name, out var channelId))
        {
            return await StrongReferenceMessenger.Default.Send(message, channelId).Response;
        }
        return default(TResponse);
    }

    /// <summary>
    /// 注册消息接收者，使其能够响应指定类型的消息。
    /// 内部自动完成：注册通道 → 向 StrongReferenceMessenger 注册处理函数。
    /// 重复注册同一接收者无效（通过 IsRegistered 检查保护）。
    /// </summary>
    /// <typeparam name="TRecipient">接收者类型（须实现 IRecipient 接口）</typeparam>
    /// <typeparam name="TMessage">要接收的消息类型</typeparam>
    /// <param name="recipient">接收者实例</param>
    public static void Register<TRecipient, TMessage>(TRecipient recipient)
        where TRecipient : class, IRecipient<TMessage>
        where TMessage : class
    {
        Type msgType = typeof(TMessage);
        RegisterChannel(msgType.Name);

        if (channel.TryGetValue(msgType.Name, out var channelId)
            && !StrongReferenceMessenger.Default.IsRegistered<TRecipient, int>(recipient, channelId))
        {
            StrongReferenceMessenger.Default.Register(recipient, channelId,
                (TRecipient r, TMessage m) => r.Receive(m));
        }
    }

    /// <summary>
    /// 注销指定接收者对某消息类型的订阅。
    /// </summary>
    /// <typeparam name="TRecipient">接收者类型</typeparam>
    /// <typeparam name="TMessage">消息类型</typeparam>
    /// <param name="recipient">接收者实例</param>
    public static void Unregister<TRecipient, TMessage>(TRecipient recipient)
        where TRecipient : class, IRecipient<TMessage>
        where TMessage : class
    {
        Type msgType = typeof(TMessage);
        if (channel.TryGetValue(msgType.Name, out var channelId))
        {
            StrongReferenceMessenger.Default.Unregister<TRecipient, int>(recipient, channelId);
        }
    }

    /// <summary>
    /// 重置 MessengerCenter，清空所有通道并重置全局 StrongReferenceMessenger 状态。
    /// 通常在应用程序重启或退出时调用。
    /// </summary>
    public static void Reset()
    {
        StrongReferenceMessenger.Default.Reset();
    }
}

namespace HandyMvvm.Model.Computation;

/// <summary>
/// 任务生命周期状态枚举，描述一个异步任务的执行阶段。
///
/// 状态流转图：
/// Idle → (Start) → Preparing → Executing → Completing → Completed
///                      ↓               ↓
///                  Cancelling ←───── Cancelled
///                      ↓
///                   Error
/// </summary>
public enum TaskState
{
    /// <summary>初始/空闲状态，任务未启动或已完全结束</summary>
    Idle,

    /// <summary>任务已启动，正在初始化（短暂过渡状态）</summary>
    Start,

    /// <summary>准备阶段：执行任务执行前的准备工作</summary>
    Preparing,

    /// <summary>执行阶段：核心业务逻辑正在运行</summary>
    Executing,

    /// <summary>收尾阶段：执行完成回调</summary>
    Completing,

    /// <summary>正常完成（所有阶段均成功执行）</summary>
    Completed,

    /// <summary>正在取消（用户请求中断，Token 已触发）</summary>
    Cancelling,

    /// <summary>已取消（执行过程中被 CancellationToken 中断）</summary>
    Cancelled,

    /// <summary>执行出错（捕获了异常）</summary>
    Error
}

using System;
using System.ComponentModel;
using System.Threading;
using System.Threading.Tasks;
using CommunityToolkit.Mvvm.Messaging;
using CommunityToolkit.Mvvm.Messaging.Messages;
using HandyMvvm.Messenger;

namespace HandyMvvm.Model.Computation;

/// <summary>
/// 带超时控制和生命周期管理的异步任务状态机。
///
/// 特性：
/// - 支持超时自动取消（millisecondOverTime）
/// - 状态变更通过 MessengerCenter 广播，供 UI 层订阅更新
/// - 任务完成后自动等待 2 秒再回到 Completed 状态（供 UI 显示完成动画）
/// - 每个实例仅可执行一次 Start，Reset 后方可再次启动
/// </summary>
public class TaskStateMachine : INotifyPropertyChanged
{
    private TaskState _taskState;
    private CancellationTokenSource? taskCanceller;

    /// <summary>
    /// 当前任务状态。每次赋值均触发 PropertyChanged 事件和 Messenger 广播。
    /// </summary>
    public TaskState CurrentState
    {
        get => _taskState;
        set
        {
            _taskState = value;
            OnPropertyChanged("CurrentState");
        }
    }

    public event PropertyChangedEventHandler? PropertyChanged;

    /// <summary>
    /// 静态发送：直接广播 TaskState 变化消息（无需实例即可发送状态通知）。
    /// </summary>
    public static void Send(ValueChangedMessage<TaskState> message)
    {
        MessengerCenter.Send<ValueChangedMessage<TaskState>, TaskState>(message);
    }

    /// <summary>
    /// 静态注册：注册指定类型接收者订阅 TaskState 变化。
    /// </summary>
    public static void Register<TRecipient>(TRecipient recipient)
        where TRecipient : class, IRecipient<ValueChangedMessage<TaskState>>
    {
        MessengerCenter.Register<TRecipient, ValueChangedMessage<TaskState>>(recipient);
    }

    /// <summary>
    /// 静态注销：取消指定接收者对 TaskState 变化的订阅。
    /// </summary>
    public static void Unregister<TRecipient>(TRecipient recipient)
        where TRecipient : class, IRecipient<ValueChangedMessage<TaskState>>
    {
        MessengerCenter.Unregister<TRecipient, ValueChangedMessage<TaskState>>(recipient);
    }

    public TaskStateMachine()
    {
        // 订阅自身 PropertyChanged 事件用于一次性监听
        PropertyChanged += OneTimeTaskStateMachine_PropertyChanged;
    }

    /// <summary>
    /// 一次性监听回调，可被子类重写以响应状态变化（现为空实现，保留扩展点）。
    /// </summary>
    protected virtual void OneTimeTaskStateMachine_PropertyChanged(object? sender, PropertyChangedEventArgs e)
    {
    }

    /// <summary>
    /// 启动一个异步任务（无返回值版本）。
    ///
    /// 执行流程（依次）：Idle → Start(200ms) → Preparing → Executing → Completing → Completed
    /// 若超时/取消/异常：进入 Cancelling → Cancelled 或 Error
    /// 完成后等待 2 秒回到 Completed 状态。
    /// </summary>
    /// <param name="millisecondOverTime">超时时间（毫秒），超时自动触发 CancellationToken</param>
    /// <param name="execute">核心执行逻辑（Action）</param>
    /// <param name="complete">完成回调</param>
    /// <param name="cancelled">被取消时的回调</param>
    /// <param name="error">出错时的回调，参数为捕获的 Exception</param>
    /// <param name="prepare">准备阶段回调（可选）</param>
    public async Task Start(int millisecondOverTime, Action execute, Action complete,
        Action? cancelled = null, Action<Exception>? error = null, Action? prepare = null)
    {
        if (CurrentState != TaskState.Idle)
            return; // 仅 Idle 状态可启动

        CurrentState = TaskState.Start;
        await Wait(200); // Start 状态停留 200ms（供 UI 动画）

        try
        {
            using (taskCanceller = new CancellationTokenSource(millisecondOverTime))
            {
                if (prepare != null)
                    await Prepare(prepare, taskCanceller.Token);

                await Execute(execute, taskCanceller.Token);
                await Complete(complete, taskCanceller.Token);
            }
        }
        catch (OperationCanceledException)
        {
            CurrentState = TaskState.Cancelled;
            if (cancelled != null)
                await Task.Run(cancelled);
        }
        catch (Exception ex)
        {
            CurrentState = TaskState.Error;
            if (error != null)
                await Task.Run(() => error(ex));
        }

        await Wait(2000); // Completed 状态停留 2 秒
        CurrentState = TaskState.Completed;
    }

    /// <summary>
    /// 启动一个异步任务（有返回值版本）。
    /// 与无返回值版本的区别在于 execute 参数为 Func&lt;TResult&gt;，complete 回调接收执行结果。
    /// </summary>
    public async Task Start<TResult>(int millisecondOverTime, Func<TResult> execute, Action<TResult?> complete,
        Action? cancelled = null, Action<Exception>? error = null, Action? prepare = null)
    {
        if (CurrentState != TaskState.Idle)
            return;

        CurrentState = TaskState.Start;
        await Wait(200);

        try
        {
            using (taskCanceller = new CancellationTokenSource(millisecondOverTime))
            {
                if (prepare != null)
                    await Prepare(prepare, taskCanceller.Token);

                // Execute 执行并等待结果，随后调用 complete(result, token)
                await Complete(complete, await Execute(execute, taskCanceller.Token), taskCanceller.Token);
            }
        }
        catch (OperationCanceledException)
        {
            CurrentState = TaskState.Cancelled;
            if (cancelled != null)
                await Task.Run(cancelled);
        }
        catch (Exception ex)
        {
            CurrentState = TaskState.Error;
            if (error != null)
                await Task.Run(() => error(ex));
        }

        await Wait(2000);
        CurrentState = TaskState.Completed;
    }

    /// <summary>
    /// 请求取消当前正在执行的任务。
    /// 仅在 Preparing 或 Executing 阶段有效，调用后触发 CancellationToken。
    /// </summary>
    public void Cancel()
    {
        if (CurrentState == TaskState.Preparing || CurrentState == TaskState.Executing)
        {
            CurrentState = TaskState.Cancelling;
            taskCanceller?.Cancel();
        }
    }

    /// <summary>
    /// 重置状态机回 Idle，允许重新调用 Start。
    /// 在 Start / Preparing / Executing 阶段不可重置（返回 false）。
    /// </summary>
    /// <returns>重置成功返回 true，任务进行中无法重置返回 false</returns>
    public bool Reset()
    {
        if (CurrentState != TaskState.Start &&
            CurrentState != TaskState.Preparing &&
            CurrentState != TaskState.Executing)
        {
            CurrentState = TaskState.Idle;
            return true;
        }
        return false;
    }

    /// <summary>
    /// 属性变更通知：触发 PropertyChanged 事件并通过 Messenger 广播当前状态。
    /// </summary>
    protected virtual void OnPropertyChanged(string propertyName)
    {
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
        MessengerCenter.Send<ValueChangedMessage<TaskState>, TaskState>(new ValueChangedMessage<TaskState>(CurrentState));
    }

    // ---- 私有辅助方法 ----

    private async Task Prepare(Action prepare, CancellationToken token)
    {
        if (CurrentState == TaskState.Start)
        {
            CurrentState = TaskState.Preparing;
            await Task.Run(prepare, token);
        }
    }

    private async Task Execute(Action execute, CancellationToken token)
    {
        if (CurrentState == TaskState.Start || CurrentState == TaskState.Preparing)
        {
            CurrentState = TaskState.Executing;
            await Task.Run(execute, token);
        }
    }

    private async Task<TResult?> Execute<TResult>(Func<TResult> execute, CancellationToken token)
    {
        if (CurrentState == TaskState.Start || CurrentState == TaskState.Preparing)
        {
            CurrentState = TaskState.Executing;
            return await Task.Run(() => execute(), token);
        }
        return default(TResult);
    }

    private async Task Complete(Action execute, CancellationToken token)
    {
        if (CurrentState == TaskState.Executing)
        {
            CurrentState = TaskState.Completing;
            await Task.Run(execute, token);
        }
    }

    private async Task Complete<T>(Action<T?> execute, T? result, CancellationToken token)
    {
        if (CurrentState == TaskState.Executing)
        {
            CurrentState = TaskState.Completing;
            await Task.Run(() => execute(result), token);
        }
    }

    /// <summary>
    /// 静态等待：延时后继续，不占用线程池线程。
    /// ConfigureAwait(false) 避免不必要的上下文切换。
    /// </summary>
    private static async Task Wait(int millisecond)
    {
        await Task.Delay(millisecond).ConfigureAwait(false);
    }
}

