﻿using System;
using System.Collections.ObjectModel;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Threading;
using CommunityToolkit.Mvvm.Input;
using CommunityToolkit.Mvvm.Messaging;
using CommunityToolkit.Mvvm.Messaging.Messages;
using HandyMvvm.Messenger;

namespace HandyWpfControl.Animation;

public class Sprite : Image, IDisposable, IRecipient<ValueChangedMessage<bool>>
{
	public static readonly DependencyProperty SpriteFramesProperty;

	public static readonly DependencyProperty LoopTimeProperty;

	public static readonly DependencyProperty AutoRunProperty;

	public static readonly DependencyProperty FPSProperty;

	public ICommand StartAnimationCommand;

	public ICommand StopAnimationCommand;

	private int _index;

	private int _loopTime;

	private readonly DispatcherTimer _timer;

	public ObservableCollection<ImageSource> SpriteFrames
	{
		get
		{
			return (ObservableCollection<ImageSource>)((DependencyObject)this).GetValue(SpriteFramesProperty);
		}
		set
		{
			((DependencyObject)this).SetValue(SpriteFramesProperty, (object)value);
		}
	}

	public int LoopTime
	{
		get
		{
			return (int)((DependencyObject)this).GetValue(LoopTimeProperty);
		}
		set
		{
			((DependencyObject)this).SetValue(LoopTimeProperty, (object)value);
		}
	}

	public bool AutoRun
	{
		get
		{
			return (bool)((DependencyObject)this).GetValue(AutoRunProperty);
		}
		set
		{
			((DependencyObject)this).SetValue(AutoRunProperty, (object)value);
		}
	}

	public byte FPS
	{
		get
		{
			return (byte)((DependencyObject)this).GetValue(FPSProperty);
		}
		set
		{
			((DependencyObject)this).SetValue(FPSProperty, (object)value);
		}
	}

	public static void Send(ValueChangedMessage<bool> message)
	{
		MessengerCenter.Send<ValueChangedMessage<bool>, bool>(message);
	}

	private static void Register<TRecipient>(TRecipient recipient) where TRecipient : class, IRecipient<ValueChangedMessage<bool>>
	{
		MessengerCenter.Register<TRecipient, ValueChangedMessage<bool>>(recipient);
	}

	private static void Unregister<TRecipient>(TRecipient recipient) where TRecipient : class, IRecipient<ValueChangedMessage<bool>>
	{
		MessengerCenter.Unregister<TRecipient, ValueChangedMessage<bool>>(recipient);
	}

	private static void FPSPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
	{
		if (d is Sprite sprite && e.NewValue is byte b)
		{
			sprite._timer.Interval = TimeSpan.FromMilliseconds(1000.0 / (double)(int)b);
		}
	}

	static Sprite()
	{
		SpriteFramesProperty = DependencyProperty.Register("SpriteFrames", typeof(ObservableCollection<ImageSource>), typeof(Sprite), new PropertyMetadata((object)new ObservableCollection<ImageSource>()));
		LoopTimeProperty = DependencyProperty.Register("LoopTime", typeof(int), typeof(Sprite), new PropertyMetadata((object)0));
		AutoRunProperty = DependencyProperty.Register("AutoRun", typeof(bool), typeof(Sprite), new PropertyMetadata((object)true));
		FPSProperty = DependencyProperty.Register("FPS", typeof(byte), typeof(Sprite), new PropertyMetadata((object)(byte)24, new PropertyChangedCallback(FPSPropertyChanged)));
		FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(Sprite), (PropertyMetadata)(object)new FrameworkPropertyMetadata((object)typeof(Sprite)));
	}

	public Sprite()
	{
		StartAnimationCommand = new RelayCommand(StartAnimationCommandExecute);
		StopAnimationCommand = new RelayCommand(StopAnimationCommandExecute);
		Register(this);
		_timer = new DispatcherTimer
		{
			Interval = TimeSpan.FromMilliseconds(1000.0 / (double)(int)FPS)
		};
		_timer.Tick += Timer_Tick;
		base.Loaded += Sprite_Loaded;
	}

	private void Sprite_Loaded(object sender, RoutedEventArgs e)
	{
		if (SpriteFrames.Count == 0)
		{
			LoadDefaultSprite();
			base.Source = SpriteFrames[0];
		}
		if (AutoRun)
		{
			StartAnimationCommandExecute();
		}
	}

	~Sprite()
	{
		Dispose();
	}

	public void Dispose()
	{
		Unregister(this);
		_timer.Tick -= Timer_Tick;
		StopAnimationCommandExecute();
		GC.SuppressFinalize(this);
	}

	private void StartAnimationCommandExecute()
	{
		if (SpriteFrames.Count > 0)
		{
			base.Source = SpriteFrames[0];
			_loopTime = LoopTime;
			_timer.Start();
		}
	}

	private void StopAnimationCommandExecute()
	{
		_timer.Stop();
	}

	private void Timer_Tick(object? sender, EventArgs e)
	{
		_index = (_index + 1) % SpriteFrames.Count;
		if (_index == 0)
		{
			_loopTime--;
		}
		if (LoopTime > 0 && _loopTime == 0)
		{
			StopAnimationCommandExecute();
		}
		base.Source = SpriteFrames[_index];
	}

	private void LoadDefaultSprite()
	{
		if (SpriteFrames.Count > 0)
		{
			SpriteFrames.Clear();
		}
		for (int i = 0; i < int.MaxValue; i++)
		{
			if (!(TryFindResource("HourGla" + i) is ImageSource item))
			{
				break;
			}
			SpriteFrames.Add(item);
		}
	}

	public void Receive(ValueChangedMessage<bool> m)
	{
		if (m.Value)
		{
			StartAnimationCommand.Execute(null);
		}
		else
		{
			StopAnimationCommand.Execute(null);
		}
	}
}

