	static BasicItemsControl()
	{
		//IL_001f: Unknown result type (might be due to invalid IL or missing references)
		//IL_0029: Expected O, but got Unknown
		//IL_0054: Unknown result type (might be due to invalid IL or missing references)
		//IL_005e: Expected O, but got Unknown
		//IL_0059: Unknown result type (might be due to invalid IL or missing references)
		//IL_0063: Expected O, but got Unknown
		LayoutTypeProperty = DependencyProperty.Register("LayoutType", typeof(LayoutMode), typeof(BasicItemsControl), new PropertyMetadata((object)LayoutMode.Fill));
		ArrangeProperty = DependencyProperty.Register("ArrangeType", typeof(ArrangeMode), typeof(BasicItemsControl), new PropertyMetadata((object)ArrangeMode.StackH, new PropertyChangedCallback(ArrangePropertyChanged)));
		FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(BasicItemsControl), (PropertyMetadata)(object)new FrameworkPropertyMetadata((object)typeof(BasicItemsControl)));
