namespace HandyWpfControl.Converters;

public class NullToVisibilityConverter : IValueConverter
{
	public bool NullIsVisible { get; set; }

	public bool UseHidden { get; set; }

	public object? Convert(object? value, Type targetType, object? parameter, CultureInfo culture)
	{
		bool flag = value == null || (value is string value2 && string.IsNullOrEmpty(value2));
		return (!(NullIsVisible ? flag : (!flag))) ? (UseHidden ? Visibility.Hidden : Visibility.Collapsed) : Visibility.Visible;
	}

	public object? ConvertBack(object? value, Type targetType, object? parameter, CultureInfo culture)
	{
		throw new NotImplementedException();
	}
