using System;
using System.Globalization;
using System.Windows;
using System.Windows.Data;

namespace HandyWpfControl.Converters;

[ValueConversion(typeof(bool), typeof(Visibility))]
public class BooleanToVisibilityConverter : IValueConverter
{
	public bool Inverted { get; set; }

	public bool UseHidden { get; set; }

	public object? Convert(object? value, Type targetType, object? parameter, CultureInfo culture)
	{
		if (value is bool flag)
		{
			return (!(Inverted ? (!flag) : flag)) ? (UseHidden ? Visibility.Hidden : Visibility.Collapsed) : Visibility.Visible;
		}
		bool? flag2 = parameter as bool?;
		if (flag2.HasValue)
		{
			return (!(Inverted ? (!flag2.Value) : flag2.Value)) ? (UseHidden ? Visibility.Hidden : Visibility.Collapsed) : Visibility.Visible;
		}
		return UseHidden ? Visibility.Hidden : Visibility.Collapsed;
	}

	public object? ConvertBack(object? value, Type targetType, object? parameter, CultureInfo culture)
	{
		if (value is Visibility visibility)
		{
			bool flag = visibility == Visibility.Visible;
			return Inverted ? (!flag) : flag;
		}
		return Inverted;
	}
}

using System;
using System.Windows;
using System.Windows.Controls;

namespace HandyWpfControl.Panel;

public class BasicPanel : System.Windows.Controls.Panel
{
	public static readonly DependencyProperty LayoutModeProperty;

	public LayoutMode Layout
	{
		get
		{
			return (LayoutMode)((DependencyObject)this).GetValue(LayoutModeProperty);
		}
		set
		{
			((DependencyObject)this).SetValue(LayoutModeProperty, (object)value);
		}
	}

	private static void LayoutModePropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
	{
		if (d is BasicPanel basicPanel)
		{
			basicPanel.InvalidateMeasure();
			basicPanel.InvalidateArrange();
		}
	}

	static BasicPanel()
	{
		LayoutModeProperty = DependencyProperty.Register("Layout", typeof(LayoutMode), typeof(BasicPanel), new PropertyMetadata((object)LayoutMode.Fill, new PropertyChangedCallback(LayoutModePropertyChanged)));
		FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(BasicPanel), (PropertyMetadata)(object)new FrameworkPropertyMetadata((object)typeof(BasicPanel)));
	}

	protected override Size MeasureOverride(Size constraint)
	{
		if (Layout == LayoutMode.Fill)
		{
			return constraint;
		}
		Size result = default(Size);
		double num = 0.0;
		foreach (UIElement internalChild in base.InternalChildren)
		{
			if (internalChild != null)
			{
				Size desiredSize;
				if (Layout == LayoutMode.Stack)
				{
					internalChild.Measure(constraint);
					double width = result.Width;
					desiredSize = internalChild.DesiredSize;
					result.Width = Math.Max(width, desiredSize.Width);
					double height = result.Height;
					desiredSize = internalChild.DesiredSize;
					result.Height = Math.Max(height, desiredSize.Height);
				}
				else if (Layout == LayoutMode.Horizontal)
				{
					internalChild.Measure(new Size(constraint.Width - num, constraint.Height));
					double num2 = num;
					desiredSize = internalChild.DesiredSize;
					num = num2 + desiredSize.Width;
					result.Width = result.Width + num;
					double height2 = result.Height;
					desiredSize = internalChild.DesiredSize;
					result.Height = Math.Max(height2, desiredSize.Height);
				}
				else if (Layout == LayoutMode.Vertical)
				{
					internalChild.Measure(new Size(constraint.Width, constraint.Height - num));
					double num3 = num;
					desiredSize = internalChild.DesiredSize;
					num = num3 + desiredSize.Height;
					double width2 = result.Width;
					desiredSize = internalChild.DesiredSize;
					result.Width = Math.Max(width2, desiredSize.Width);
					result.Height = result.Height + num;
				}
			}
		}
		return result;
	}

	protected override Size ArrangeOverride(Size arrangeSize)
	{
		double num = 0.0;
		foreach (FrameworkElement internalChild in base.InternalChildren)
		{
			Size desiredSize;
			if (Layout == LayoutMode.Fill)
			{
				internalChild.Arrange(new Rect(arrangeSize));
			}
			else if (Layout == LayoutMode.Stack)
			{
				internalChild.Arrange(new Rect(arrangeSize));
			}
			else if (Layout == LayoutMode.Horizontal)
			{
				double num2;
				double num3;
				switch (internalChild.VerticalAlignment)
				{
				case VerticalAlignment.Bottom:
				{
					double height2 = arrangeSize.Height;
					desiredSize = internalChild.DesiredSize;
					num2 = (num3 = height2 - desiredSize.Height);
					break;
				}
				case VerticalAlignment.Center:
				{
					double height = arrangeSize.Height;
					desiredSize = internalChild.DesiredSize;
					num2 = (num3 = (height - desiredSize.Height) / 2.0);
					break;
				}
				default:
					num2 = 0.0;
					break;
				}
				num3 = num2;
				internalChild.Arrange(new Rect(new Point(num, num3), internalChild.DesiredSize));
				double num4 = num;
				desiredSize = internalChild.DesiredSize;
				num = num4 + desiredSize.Width;
			}
			else if (Layout == LayoutMode.Vertical)
			{
				double num2;
				double num5;
				switch (internalChild.VerticalAlignment)
				{
				case VerticalAlignment.Bottom:
				{
					double width2 = arrangeSize.Width;
					desiredSize = internalChild.DesiredSize;
					num2 = (num5 = width2 - desiredSize.Width);
					break;
				}
				case VerticalAlignment.Center:
				{
					double width = arrangeSize.Width;
					desiredSize = internalChild.DesiredSize;
					num2 = (num5 = (width - desiredSize.Width) / 2.0);
					break;
				}
				default:
					num2 = 0.0;
					break;
				}
				num5 = num2;
				internalChild.Arrange(new Rect(new Point(num5, num), internalChild.DesiredSize));
				double num6 = num;
				desiredSize = internalChild.DesiredSize;
				num = num6 + desiredSize.Height;
			}
		}
		return arrangeSize;
	}
}

