using System;
using System.Collections.ObjectModel;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Threading;
using CommunityToolkit.Mvvm.Input;
using CommunityToolkit.Mvvm.Messaging;
using CommunityToolkit.Mvvm.Messaging.Messages;
using HandyMvvm.Messenger;

namespace HandyWpfControl.Animation;

/// <summary>
/// 精灵动画控件，继承自 Image。通过定时切换 Source 显示多帧动画。
///
/// 特性：
/// - 支持自定义帧列表（SpriteFrames）
/// - 可配置帧率（FPS）和循环次数（LoopTime）
/// - 自动注册/注销 Messenger，通过消息控制播放/暂停
/// - 默认加载 HourGla0~N 系列资源作为动画帧
/// </summary>
public class Sprite : Image, IDisposable, IRecipient<ValueChangedMessage<bool>>
{
    public static readonly DependencyProperty SpriteFramesProperty;
    public static readonly DependencyProperty LoopTimeProperty;
    public static readonly DependencyProperty AutoRunProperty;
    public static readonly DependencyProperty FPSProperty;

    /// <summary>启动动画命令（可绑定到按钮等）</summary>
    public ICommand StartAnimationCommand;

    /// <summary>停止动画命令</summary>
    public ICommand StopAnimationCommand;

    private int _index;         // 当前显示的帧下标
    private int _loopTime;      // 剩余循环次数（每次播完一轮减 1）
    private readonly DispatcherTimer _timer;  // 帧切换定时器

    /// <summary>动画帧列表，每帧为一个 ImageSource</summary>
    public ObservableCollection<ImageSource> SpriteFrames
    {
        get => (ObservableCollection<ImageSource>)((DependencyObject)this).GetValue(SpriteFramesProperty);
        set => ((DependencyObject)this).SetValue(SpriteFramesProperty, (object)value);
    }

    /// <summary>循环播放次数，0 表示无限循环</summary>
    public int LoopTime
    {
        get => (int)((DependencyObject)this).GetValue(LoopTimeProperty);
        set => ((DependencyObject)this).SetValue(LoopTimeProperty, (object)value);
    }

    /// <summary>控件加载完成后是否自动开始播放</summary>
    public bool AutoRun
    {
        get => (bool)((DependencyObject)this).GetValue(AutoRunProperty);
        set => ((DependencyObject)this).SetValue(AutoRunProperty, (object)value);
    }

    /// <summary>每秒帧数（Frames Per Second），默认 24</summary>
    public byte FPS
    {
        get => (byte)((DependencyObject)this).GetValue(FPSProperty);
        set => ((DependencyObject)this).SetValue(FPSProperty, (object)value);
    }

    /// <summary>
    /// 静态发送：广播布尔值消息，控制所有 Sprite 实例的播放/停止。
    /// </summary>
    public static void Send(ValueChangedMessage<bool> message)
    {
        MessengerCenter.Send<ValueChangedMessage<bool>, bool>(message);
    }

    private static void Register<TRecipient>(TRecipient recipient)
        where TRecipient : class, IRecipient<ValueChangedMessage<bool>>
    {
        MessengerCenter.Register<TRecipient, ValueChangedMessage<bool>>(recipient);
    }

    private static void Unregister<TRecipient>(TRecipient recipient)
        where TRecipient : class, IRecipient<ValueChangedMessage<bool>>
    {
        MessengerCenter.Unregister<TRecipient, ValueChangedMessage<bool>>(recipient);
    }

    /// <summary>
    /// FPS 属性变更回调：实时更新定时器间隔。
    /// </summary>
    private static void FPSPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
    {
        if (d is Sprite sprite && e.NewValue is byte b)
        {
            sprite._timer.Interval = TimeSpan.FromMilliseconds(1000.0 / (double)(int)b);
        }
    }

    static Sprite()
    {
        SpriteFramesProperty = DependencyProperty.Register(
            "SpriteFrames", typeof(ObservableCollection<ImageSource>), typeof(Sprite),
            new PropertyMetadata(new ObservableCollection<ImageSource>()));

        LoopTimeProperty = DependencyProperty.Register(
            "LoopTime", typeof(int), typeof(Sprite),
            new PropertyMetadata(0));

        AutoRunProperty = DependencyProperty.Register(
            "AutoRun", typeof(bool), typeof(Sprite),
            new PropertyMetadata(true));

        FPSProperty = DependencyProperty.Register(
            "FPS", typeof(byte), typeof(Sprite),
            new PropertyMetadata((byte)24, new PropertyChangedCallback(FPSPropertyChanged)));

        // 将本类型注册为可应用样式的控件（需在 Generic.xaml 中定义 Style）
        FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(
            typeof(Sprite),
            new FrameworkPropertyMetadata(typeof(Sprite)));
    }

    public Sprite()
    {
        StartAnimationCommand = new RelayCommand(StartAnimationCommandExecute);
        StopAnimationCommand = new RelayCommand(StopAnimationCommandExecute);

        Register(this); // 注册自身以接收播放/停止消息

        _timer = new DispatcherTimer
        {
            Interval = TimeSpan.FromMilliseconds(1000.0 / (double)(int)FPS)
        };
        _timer.Tick += Timer_Tick;
        base.Loaded += Sprite_Loaded;
    }

    private void Sprite_Loaded(object sender, RoutedEventArgs e)
    {
        // 若未手动设置帧列表，自动加载 HourGla 资源
        if (SpriteFrames.Count == 0)
        {
            LoadDefaultSprite();
            base.Source = SpriteFrames[0];
        }

        if (AutoRun)
        {
            StartAnimationCommandExecute();
        }
    }

    ~Sprite()
    {
        Dispose();
    }

    /// <summary>释放资源：注销 Messenger、停止定时器、停止动画</summary>
    public void Dispose()
    {
        Unregister(this);
        _timer.Tick -= Timer_Tick;
        StopAnimationCommandExecute();
        GC.SuppressFinalize(this);
    }

    private void StartAnimationCommandExecute()
    {
        if (SpriteFrames.Count > 0)
        {
            base.Source = SpriteFrames[0];
            _loopTime = LoopTime;
            _timer.Start();
        }
    }

    private void StopAnimationCommandExecute()
    {
        _timer.Stop();
    }

    /// <summary>
    /// 定时器 Tick：切换到下一帧，若循环次数耗尽则停止。
    /// </summary>
    private void Timer_Tick(object? sender, EventArgs e)
    {
        // 切换到下一帧（循环下标）
        _index = (_index + 1) % SpriteFrames.Count;

        // 当回到第一帧时，消耗一次循环次数
        if (_index == 0)
        {
            _loopTime--;
        }

        // 若设置了循环次数且已耗尽，停止动画
        if (LoopTime > 0 && _loopTime == 0)
        {
            StopAnimationCommandExecute();
        }

        base.Source = SpriteFrames[_index];
    }

    /// <summary>
    /// 从 WPF 资源字典中加载 HourGla0、HourGla1、... 命名的图片作为动画帧。
    /// 遇到第一个不存在的资源名时停止加载。
    /// </summary>
    private void LoadDefaultSprite()
    {
        if (SpriteFrames.Count > 0)
        {
            SpriteFrames.Clear();
        }

        // 依次尝试 HourGla0, HourGla1, ... 直到资源不存在为止
        for (int i = 0; i < int.MaxValue; i++)
        {
            if (TryFindResource("HourGla" + i) is ImageSource item)
            {
                SpriteFrames.Add(item);
            }
            else
            {
                break;
            }
        }
    }

    /// <summary>
    /// Messenger 消息接收：true=播放，false=停止。
    /// </summary>
    public void Receive(ValueChangedMessage<bool> m)
    {
        if (m.Value)
        {
            StartAnimationCommand.Execute(null);
        }
        else
        {
            StopAnimationCommand.Execute(null);
        }
    }
}

