using System;
using System.Globalization;
using System.Windows;
using System.Windows.Data;

namespace HandyWpfControl.Converters;

/// <summary>
/// bool → Visibility 转换器，支持反向和 Hidden/Collapsed 两种隐藏模式。
/// </summary>
public class BooleanToVisibilityConverter : IValueConverter
{
    /// <summary>若为 true，则对布尔值先取反再决定可见性（true=隐藏，false=显示）</summary>
    public bool Inverted { get; set; }

    /// <summary>若为 true，隐藏时用 Hidden；否则用 Collapsed（默认 Collapsed）</summary>
    public bool UseHidden { get; set; }

    public object? Convert(object? value, Type targetType, object? parameter, CultureInfo culture)
    {
        // 直接以 value 的布尔值决定
        if (value is bool flag)
        {
            bool isVisible = Inverted ? (!flag) : flag;
            return isVisible ? Visibility.Visible
                : (UseHidden ? Visibility.Hidden : Visibility.Collapsed);
        }

        // 若 value 非布尔，尝试从 parameter（绑定参数）读取布尔值
        bool? paramFlag = parameter as bool?;
        if (paramFlag.HasValue)
        {
            bool isVisible = Inverted ? (!paramFlag.Value) : paramFlag.Value;
            return isVisible ? Visibility.Visible
                : (UseHidden ? Visibility.Hidden : Visibility.Collapsed);
        }

        // value 和 parameter 都不是布尔，返回隐藏
        return UseHidden ? Visibility.Hidden : Visibility.Collapsed;
    }

    public object? ConvertBack(object? value, Type targetType, object? parameter, CultureInfo culture)
    {
        if (value is Visibility visibility)
        {
            bool isVisible = visibility == Visibility.Visible;
            return Inverted ? (!isVisible) : isVisible;
        }
        return Inverted; // 默认返回 Inverted 值
    }
}

