using System;
using System.Globalization;
using System.Windows;
using System.Windows.Data;

namespace HandyWpfControl.Converters;

/// <summary>
/// null / 空字符串 → Visibility 转换器。
/// </summary>
public class NullToVisibilityConverter : IValueConverter
{
    /// <summary>若为 true，null/空值 → Visible；非 null → Collapsed（默认 false）</summary>
    public bool NullIsVisible { get; set; }

    /// <summary>隐藏时用 Hidden 而非 Collapsed（默认 false）</summary>
    public bool UseHidden { get; set; }

    public object? Convert(object? value, Type targetType, object? parameter, CultureInfo culture)
    {
        // 判断是否为空：value 为 null 或空字符串
        bool isNull = value == null || (value is string str && string.IsNullOrEmpty(str));

        bool isVisible = NullIsVisible ? isNull : (!isNull);

        return isVisible ? Visibility.Visible
            : (UseHidden ? Visibility.Hidden : Visibility.Collapsed);
    }

    public object? ConvertBack(object? value, Type targetType, object? parameter, CultureInfo culture)
    {
        throw new NotImplementedException();
    }
}

using System.Windows;
using System.Windows.Controls;
using HandyWpfControl.Panel;

namespace HandyWpfControl.ItemsControl;

/// <summary>
/// 内部 ItemsPanel 模板的排列模式枚举，对应 XAML 中命名的 ItemsPanelTemplate 资源。
/// </summary>
public enum ArrangeMode
{
    /// <summary>水平排列（StackPanel 水平方向）</summary>
    StackH,

    /// <summary>垂直排列（StackPanel 垂直方向）</summary>
    StackV,

