using System;
using System.Windows;
using System.Windows.Controls;

namespace HandyWpfControl.Panel;

/// <summary>
/// 自定义面板，支持四种布局模式（Fill / Stack / Horizontal / Vertical）。
/// 继承 System.Windows.Controls.Panel，重写 MeasureOverride 和 ArrangeOverride 实现自定义布局。
/// </summary>
public class BasicPanel : System.Windows.Controls.Panel
{
    public static readonly DependencyProperty LayoutModeProperty;

    /// <summary>
    /// 当前布局模式，变更时触发 InvalidateMeasure 和 InvalidateArrange 重新布局。
    /// </summary>
    public LayoutMode Layout
    {
        get => (LayoutMode)((DependencyObject)this).GetValue(LayoutModeProperty);
        set => ((DependencyObject)this).SetValue(LayoutModeProperty, (object)value);
    }

    private static void LayoutModePropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
    {
        if (d is BasicPanel basicPanel)
        {
            basicPanel.InvalidateMeasure();
            basicPanel.InvalidateArrange();
        }
    }

    static BasicPanel()
    {
        LayoutModeProperty = DependencyProperty.Register(
            "Layout", typeof(LayoutMode), typeof(BasicPanel),
            new PropertyMetadata(LayoutMode.Fill, new PropertyChangedCallback(LayoutModePropertyChanged)));

        FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(
            typeof(BasicPanel),
            new FrameworkPropertyMetadata(typeof(BasicPanel)));
    }

    /// <summary>
    /// 测量阶段：计算所有子元素所需的总尺寸。
    /// Fill 模式直接返回约束尺寸；其余模式逐元素累加。
    /// </summary>
    protected override Size MeasureOverride(Size constraint)
    {
        if (Layout == LayoutMode.Fill)
        {
            return constraint; // Fill 模式：Panel 占满整个可用区域
        }

        Size result = default;
        double consumed = 0.0; // 累计已占用方向上的尺寸

        foreach (UIElement child in base.InternalChildren)
        {
            if (child == null) continue;

            switch (Layout)
            {
                case LayoutMode.Stack:
                    // Stack：取最大宽高
                    child.Measure(constraint);
                    result.Width = Math.Max(result.Width, child.DesiredSize.Width);
                    result.Height = Math.Max(result.Height, child.DesiredSize.Height);
                    break;

                case LayoutMode.Horizontal:
                    // Horizontal：子元素测量时限制宽度为剩余空间
                    child.Measure(new Size(constraint.Width - consumed, constraint.Height));
                    consumed += child.DesiredSize.Width;
                    result.Width = result.Width + child.DesiredSize.Width;
                    result.Height = Math.Max(result.Height, child.DesiredSize.Height);
                    break;

                case LayoutMode.Vertical:
                    // Vertical：子元素测量时限制高度为剩余空间
                    child.Measure(new Size(constraint.Width, constraint.Height - consumed));
                    consumed += child.DesiredSize.Height;
                    result.Width = Math.Max(result.Width, child.DesiredSize.Width);
                    result.Height = result.Height + consumed;
                    break;
            }
        }

        return result;
    }

    /// <summary>
    /// 排列阶段：将所有子元素放置到实际坐标位置。
    /// Fill/Stack 模式占满整个 Panel；Horizontal/Vertical 模式逐个排列。
    /// </summary>
    protected override Size ArrangeOverride(Size arrangeSize)
    {
        double offset = 0.0; // 累计偏移量

        foreach (FrameworkElement child in base.InternalChildren)
        {
            double x = 0.0, y = 0.0;

            switch (Layout)
            {
                case LayoutMode.Fill:
                case LayoutMode.Stack:
                    // Fill/Stack：占满整个区域
                    child.Arrange(new Rect(arrangeSize));
                    break;

                case LayoutMode.Horizontal:
                    // 根据 VerticalAlignment 计算 y 坐标
                    switch (child.VerticalAlignment)
                    {
                        case VerticalAlignment.Bottom:
                            y = arrangeSize.Height - child.DesiredSize.Height;
                            break;
                        case VerticalAlignment.Center:
                            y = (arrangeSize.Height - child.DesiredSize.Height) / 2.0;
                            break;
                        // Top 和 Stretch 默认 y=0
                    }
                    child.Arrange(new Rect(new Point(offset, y), child.DesiredSize));
                    offset += child.DesiredSize.Width;
                    break;

                case LayoutMode.Vertical:
                    // 根据 HorizontalAlignment 计算 x 坐标
                    switch (child.HorizontalAlignment)
                    {
                        case HorizontalAlignment.Right:
                            x = arrangeSize.Width - child.DesiredSize.Width;
                            break;
                        case HorizontalAlignment.Center:
                            x = (arrangeSize.Width - child.DesiredSize.Width) / 2.0;
                            break;
                        // Left 和 Stretch 默认 x=0
                    }
                    child.Arrange(new Rect(new Point(x, offset), child.DesiredSize));
                    offset += child.DesiredSize.Height;
                    break;
            }
        }

        return arrangeSize;
    }
}

