namespace HandyWpfControl.Progress;

/// <summary>
/// 任务进度提示控件，显示异步任务的当前状态文字。
///
/// 行为：
/// - 订阅 TaskStateMachine 的状态广播，根据状态自动切换 Tips 文字和可见性
/// - 订阅字符串消息（TaskMessage），允许外部自定义提示文本
/// - 可见性变化时通过 Messenger 通知 Sprite 控件播放/停止动画
/// - MessengerOn=false 时禁用 Messenger 注册，仅做普通控件使用
/// </summary>
public class TaskProgress : Control, INotifyPropertyChanged, IDisposable,
    IRecipient<ValueChangedMessage<TaskState>>,
    IRecipient<ValueChangedMessage<string>>
{
    public static readonly DependencyProperty TipsProperty;
    public static readonly DependencyProperty MessengerOnProperty;

    /// <summary>各状态对应的默认提示文本</summary>
    private string StartTip { get; set; } = "任务启动，请稍后...";
    private string PreparingTip { get; set; } = "准备中，请稍后...";
    private string ExecutingTip { get; set; } = "执行中，请稍后...";
    private string CompletedTip { get; set; } = "任务：已完成";
    private string CancellingTip { get; set; } = "任务：取消中...";
    private string CancelledTip { get; set; } = "任务：已取消";
    private string ErrorTip { get; set; } = "任务：出现错误";

    /// <summary>是否启用 Messenger 功能（启用后自动订阅状态广播）</summary>
    public bool MessengerOn
    {
        get => (bool)((DependencyObject)this).GetValue(MessengerOnProperty);
        set => ((DependencyObject)this).SetValue(MessengerOnProperty, (object)value);
    }

    /// <summary>当前显示的提示文本（只读属性，供 XAML Binding 使用）</summary>
    public string Tips
    {
        get => (string)((DependencyObject)this).GetValue(TipsProperty);
        private set
        {
            ((DependencyObject)this).SetValue(TipsProperty, (object)value);
            NotifyPropertyChanged("Tips");
        }
    }

    public event PropertyChangedEventHandler? PropertyChanged;

    /// <summary>静态发送：广播自定义提示文本</summary>
    public static void Send(string message)
    {
        MessengerCenter.Send<ValueChangedMessage<string>, string>(new ValueChangedMessage<string>(message));
    }

    private static void Register<TRecipient>(TRecipient recipient)
        where TRecipient : class, IRecipient<ValueChangedMessage<string>>
    {
        MessengerCenter.Register<TRecipient, ValueChangedMessage<string>>(recipient);
    }

    private static void Unregister<TRecipient>(TRecipient recipient)
        where TRecipient : class, IRecipient<ValueChangedMessage<string>>
    {
        MessengerCenter.Unregister<TRecipient, ValueChangedMessage<string>>(recipient);
    }

    private void NotifyPropertyChanged([CallerMemberName] string propertyName = "")
    {
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
    }

    private static void MessengerOnPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
    {
        if (d is TaskProgress taskProgress)
        {
            if ((bool)e.NewValue)
                taskProgress.RegisterMessenger();
            else
                taskProgress.UnregisterMessenger();
        }
    }

    static TaskProgress()
    {
        TipsProperty = DependencyProperty.Register(
            "Tips", typeof(string), typeof(TaskProgress),
            new PropertyMetadata("这里显示信息"));

        MessengerOnProperty = DependencyProperty.Register(
            "MessengerOn", typeof(bool), typeof(TaskProgress),
            new PropertyMetadata(true, new PropertyChangedCallback(MessengerOnPropertyChanged)));

        FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(
            typeof(TaskProgress),
            new FrameworkPropertyMetadata(typeof(TaskProgress)));
    }

    public TaskProgress()
    {
        base.Loaded += TaskProgress_Loaded;
        base.IsVisibleChanged += TaskProgress_IsVisibleChanged;
        if (MessengerOn)
        {
            RegisterMessenger();
        }
    }

    private void TaskProgress_Loaded(object sender, RoutedEventArgs e)
    {
        // 加载时默认隐藏，由状态机控制显示
        base.Visibility = Visibility.Collapsed;
    }

    /// <summary>
    /// 可见性变更回调：通知 Sprite 动画控件播放或停止。
    /// </summary>
    private void TaskProgress_IsVisibleChanged(object sender, DependencyPropertyChangedEventArgs e)
    {
        if (sender is TaskProgress taskProgress)
        {
            Sprite.Send(new ValueChangedMessage<bool>(taskProgress.Visibility == Visibility.Visible));
        }
    }

    ~TaskProgress()
    {
        Dispose();
    }

    public void Dispose()
    {
        UnregisterMessenger();
        GC.SuppressFinalize(this);
    }

    private void RegisterMessenger()
    {
        TaskStateMachine.Register(this); // 订阅任务状态变化
        Register(this);                  // 订阅自定义文本消息
    }

    private void UnregisterMessenger()
    {
        TaskStateMachine.Unregister(this);
        Unregister(this);
    }

    /// <summary>
    /// 接收任务状态变化消息，更新 Tips 文本和可见性。
    /// </summary>
    public void Receive(ValueChangedMessage<TaskState> message)
    {
        switch (message.Value)
        {
            case TaskState.Start:
                base.Visibility = Visibility.Visible;
                Tips = StartTip;
                break;

            case TaskState.Preparing:
            case TaskState.Executing:
                Tips = message.Value switch
                {
                    TaskState.Preparing => PreparingTip,
                    TaskState.Executing => ExecutingTip,
                    _ => "=_=，这段字不应该出现",
                };
                break;

            case TaskState.Completed:
            case TaskState.Idle:
                base.Visibility = Visibility.Collapsed;
                break;

            default: // Cancelling / Cancelled / Error
                Tips = message.Value switch
                {
                    TaskState.Cancelling => CancellingTip,
                    TaskState.Cancelled => CancelledTip,
                    TaskState.Error => ErrorTip,
                    _ => "=_=，这段字不应该出现",
                };
                break;
        }
    }

    /// <summary>
    /// 接收自定义文本消息，直接显示。
    /// </summary>
    public void Receive(ValueChangedMessage<string> m)
    {
        Tips = m.Value;
    }
}

