using System;
using CommunityToolkit.Mvvm.Messaging;
using CommunityToolkit.Mvvm.Messaging.Messages;
using HandyKits.Algorithm;
using HandyMvvm.Messenger;
using Training.Game;
using WinAPI.Win32;

namespace Training.Framework;

/// <summary>
/// 内存扫描器，负责在目标进程中查找指定字节模式的内存地址。
/// 基于 Sunday 快速匹配算法，配合 WinAPI 遍历进程内存区域。
/// </summary>
public class Scanner
{
    private readonly ProcessIO _process;

    /// <summary>关联的进程 IO 操作对象</summary>
    public ProcessIO Game => _process;

    /// <summary>静态发送：广播扫描结果消息</summary>
    protected static void Send(ValueChangedMessage<ScanMessage> message)
    {
        MessengerCenter.Send<ValueChangedMessage<ScanMessage>, ScanMessage>(message);
    }

    /// <summary>静态注册：注册扫描结果接收者</summary>
    public static void Register<TRecipient>(TRecipient recipient)
        where TRecipient : class, IRecipient<ValueChangedMessage<ScanMessage>>
    {
        MessengerCenter.Register<TRecipient, ValueChangedMessage<ScanMessage>>(recipient);
    }

    /// <summary>静态注销：取消接收者订阅</summary>
    public static void Unregister<TRecipient>(TRecipient recipient)
        where TRecipient : class, IRecipient<ValueChangedMessage<ScanMessage>>
    {
        MessengerCenter.Unregister<TRecipient, ValueChangedMessage<ScanMessage>>(recipient);
    }

    public Scanner()
    {
        _process = new ProcessIO();
    }

    /// <summary>
    /// 在 32 位进程中执行字节模式扫描（主模块区域）。
    /// </summary>
    /// <param name="description">进程描述名（用于检测进程是否运行）</param>
    /// <param name="pattern">待匹配的字节模式（由调用方提供）</param>
    /// <param name="checker">地址验证回调（可对匹配地址二次验证）</param>
    /// <returns>ReturnCode：1000=成功，803=模式未找到，801=进程未运行，802=进程已退出</returns>
    public int DoWork32(string description, byte[] pattern, Func<int, bool> checker)
    {
        ProcessState state = _process.CheckByDescription(description);

        int result = state switch
        {
            ProcessState.NotRunning => 801,
            ProcessState.Running => 1000,
            ProcessState.HasExited => 802,
            _ => 0,
        };

        if (state == ProcessState.Running)
        {
            if (Scan32(_process, pattern, checker, out var address))
            {
                Send(new ValueChangedMessage<ScanMessage>(new ScanMessage(_process, address)));
            }
            else
            {
                result = 803;
            }
        }
        else
        {
            Send(new ValueChangedMessage<ScanMessage>(new ScanMessage(null, 0)));
        }

        return result;
    }

    /// <summary>
    /// 在 64 位进程中执行字节模式扫描。
    /// 与 DoWork32 的区别在于调用 Scan64（处理 64 位内存区域结构）。
    /// </summary>
    public int DoWork64(string description, byte[] pattern, Func<int, bool> checker)
    {
        ProcessState state = _process.CheckByDescription(description);

        int result = state switch
        {
            ProcessState.NotRunning => 801,
            ProcessState.Running => 1000,
            ProcessState.HasExited => 802,
            _ => 0,
        };

        if (state == ProcessState.Running)
        {
            if (Scan64(_process, pattern, checker, out var address))
            {
                Send(new ValueChangedMessage<ScanMessage>(new ScanMessage(_process, address)));
            }
            else
            {
                result = 803;
            }
        }
        else
        {
            Send(new ValueChangedMessage<ScanMessage>(new ScanMessage(null, 0)));
        }

        return result;
    }

    /// <summary>
    /// 32 位进程内存扫描核心：对主模块的每个内存区域依次执行 Sunday 匹配。
    /// 匹配成功后调用 checker（若有）进行二次验证，通过则返回地址。
    /// </summary>
    /// <param name="process">进程 IO 对象</param>
    /// <param name="pattern">字节模式</param>
    /// <param name="checker">可选的地址验证回调</param>
    /// <param name="address">输出：找到的地址，失败返回 -1</param>
    public static bool Scan32(ProcessIO process, byte[] pattern, Func<int, bool>? checker, out int address)
    {
        var regions = process.GetMemoryBasicInformation32();

        if (regions != null && regions.Length != 0)
        {
            foreach (MemoryBasicInformation32 region in regions)
            {
                int offset = 0;

                // 以 region.RegionSize 为单位分块读取
                byte[] buffer = new byte[region.RegionSize];

                while (process.ReadProcessMemory(
                    (nint)region.BaseAddress + (nint)offset,
                    buffer))
                {
                    int matchPos = Fundamental.Sunday(buffer, pattern);

                    if (matchPos == -1)
                        break; // 本块无匹配，进入下一 region

                    offset += matchPos;
                    address = (int)region.BaseAddress + offset;

                    // checker 验证（若有）通过则返回
                    if (checker == null || checker(address))
                        return true;

                    // 未通过验证，跳过当前匹配位置继续搜索
                    offset++;
                    buffer = new byte[region.RegionSize - offset];
                }
            }
        }

        address = -1;
        return false;
    }

    /// <summary>
    /// 64 位进程内存扫描核心：对主模块的每个内存区域依次执行 Sunday 匹配。
    /// 与 Scan32 的区别：64 位 region.RegionSize 可能超过 int.MaxValue，超过则跳过。
    /// </summary>
    public static bool Scan64(ProcessIO process, byte[] pattern, Func<int, bool>? checker, out int address)
    {
        var regions = process.GetMemoryBasicInformation64();

        if (regions != null && regions.Length != 0)
        {
            foreach (MemoryBasicInformation64 region in regions)
            {
                // 超过 int.MaxValue 的 region 跳过（无法用 int 索引）
                if (region.RegionSize > int.MaxValue)
                    continue;

                int offset = 0;
                byte[] buffer = new byte[region.RegionSize];

                while (process.ReadProcessMemory(
                    (nint)region.BaseAddress + offset,
                    buffer))
                {
                    int matchPos = Fundamental.Sunday(buffer, pattern);

                    if (matchPos == -1)
                        break;

                    offset += matchPos;
                    address = (int)region.BaseAddress + offset;

                    if (checker == null || checker(address))
                        return true;

                    offset++;
                    buffer = new byte[(long)region.RegionSize - offset];
                }
            }
        }

        address = -1;
        return false;
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Runtime.InteropServices;
using System.Threading;
using System.Threading.Tasks;
using WinAPI.Win32;

namespace Training.Game;

/// <summary>
/// 游戏进程交互器，封装 ReadProcessMemory / WriteProcessMemory 等操作，
/// 提供类型化的内存读写接口，并支持远程函数调用（DLL 注入）。
/// </summary>
public class ProcessIO
{
    private Process? _process;
    // 每个持续写入操作关联一个 CancellationTokenSource，用于停止写入循环
    private readonly Dictionary<int, CancellationTokenSource> _canceller = new Dictionary<int, CancellationTokenSource>();

    /// <summary>关联进程的 PID，无进程时返回 0</summary>
    public int ID
    {
        get => _process?.Id ?? 0;
    }

    /// <summary>关联指定 System.Diagnostics.Process 对象</summary>
    public void SetProcess(Process p)
    {
        _process = p;
    }

    /// <summary>
    /// 获取指定模块名的基址。
    /// 在模块列表中查找 ModuleName 匹配的模块，返回其 BaseAddress。
    /// </summary>
    public int GetBaseAddress(string moduleName)
    {
        return (int)((_process?.Modules.Cast<ProcessModule>()
            .SingleOrDefault(m => m.ModuleName == moduleName)?.BaseAddress ?? IntPtr.Zero))!;
    }

    /// <summary>获取主模块基址</summary>
    public int GetBaseAddress()
    {
        return (int)(_process?.MainModule?.BaseAddress ?? IntPtr.Zero);
    }

    /// <summary>获取主模块的文件版本信息（ProcessModule[0]）</summary>
    public FileVersionInfo? GetFileVersionInfo()
    {
        if (_process == null || _process.HasExited)
            return null;
        return _process?.Modules[0].FileVersionInfo;
    }

    /// <summary>按进程名检测进程状态（精确匹配）</summary>
    public ProcessState CheckByName(string fileName)
    {
        return Check(direct: true, fileName);
    }

    /// <summary>按窗口描述检测进程状态（模糊匹配窗口标题）</summary>
    public ProcessState CheckByDescription(string fileDescription)
    {
        return Check(direct: false, fileDescription);
    }

    /// <summary>
    /// 内部进程检测逻辑：
    /// - direct=true：按进程名精确匹配（GetProcessesByName）
    /// - direct=false：按窗口标题模糊匹配（主窗口不包含"Map"字样，且基址 &lt; int.MaxValue）
    /// </summary>
    private ProcessState Check(bool direct, string file)
    {
        Process? process = _process;
        if (process != null && process.HasExited)
        {
            _process = null;
            return ProcessState.HasExited;
        }

        Process[] candidates = (!direct)
            ? Process.GetProcesses().Where(p =>
                p.MainWindowHandle != IntPtr.Zero
                && p.MainWindowTitle.Contains(file)
                && !p.MainWindowTitle.Contains("Map")
                && p.MainModule?.BaseAddress < int.MaxValue // 过滤64位进程
            ).ToArray()
            : Process.GetProcessesByName(file);

        if (candidates.Length != 0)
        {
            _process = candidates[0];
            return ProcessState.Running;
        }

        return ProcessState.NotRunning;
    }

    /// <summary>
    /// 向目标进程注入并执行一段机器码（ASM）。
    /// 步骤：分配内存 → 写入机器码 → 创建远程线程执行 → 等待线程结束 → 清理
    /// 常用于 DLL 注入（将 LoadLibraryA 地址作为线程函数，DLL 路径作为参数）。
    /// </summary>
    /// <param name="asmCode">机器码字节数组（由调用方构造）</param>
    public bool RemoteCall(byte[] asmCode)
    {
        Process? process = _process;
        if (process != null && process.Id > 0 && !_process!.HasExited)
        {
            // 打开进程（PROCESS_ALL_ACCESS）
            nint hProcess = Kernel32.OpenProcess(2097151, bInheritHandle: false, _process.Id);

            // 在目标进程分配 1024 字节可读写执行内存
            nint remoteAddr = Kernel32.VirtualAllocEx(hProcess, IntPtr.Zero, 1024, 12288, 64); // MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE

            if (Kernel32.WriteProcessMemory(hProcess, remoteAddr, asmCode, asmCode.Length, out var _))
            {
                // 创建远程线程执行机器码
                uint lpThreadId;
                nint hThread = Kernel32.CreateRemoteThread(
                    hProcess, IntPtr.Zero, 0, remoteAddr, IntPtr.Zero, 0, out lpThreadId);

                // 等待线程执行完成
                Kernel32.WaitForSingleObjectEx(hThread, uint.MaxValue, bAlertable: false);
                Kernel32.CloseHandle(hThread);
            }

            Kernel32.CloseHandle(hProcess);
            return true;
        }

        return false;
    }

    // ---- 内存区域查询方法 ----

    /// <summary>获取主模块对应的所有内存区域信息（32位格式）</summary>
    public MemoryBasicInformation32[]? GetExeRegion32()
    {
        Process? process = _process;
        if (process != null && process.Id > 0 && !_process!.HasExited)
        {
            var regions = new List<MemoryBasicInformation32>();
            nint? endAddr = _process.MainModule?.BaseAddress + _process.MainModule?.ModuleMemorySize;

            // PROCESS_QUERY_INFORMATION | PROCESS_VM_READ = 1040
            nint hProcess = Kernel32.OpenProcess(1040, bInheritHandle: false, _process.Id);

            if (hProcess > IntPtr.Zero)
            {
                nint addr = _process.MainModule?.BaseAddress ?? IntPtr.Zero;

                MemoryBasicInformation32 lpBuffer;
                while (Kernel32.VirtualQueryEx(hProcess, addr, out lpBuffer,
                    (nint)Marshal.SizeOf(typeof(MemoryBasicInformation32))) > 0)
                {
                    regions.Add(lpBuffer);
                    addr = IntPtr.Add((nint)lpBuffer.BaseAddress, (int)lpBuffer.RegionSize);

                    if (addr > endAddr)
                        break;
                }
            }

            Kernel32.CloseHandle(hProcess);
            return regions.ToArray();
        }
        return null;
    }

    /// <summary>获取主模块对应的所有内存区域信息（64位格式）</summary>
    public MemoryBasicInformation64[]? GetExeRegion64()
    {
        Process? process = _process;
        if (process != null && process.Id > 0 && !_process!.HasExited)
        {
            var regions = new List<MemoryBasicInformation64>();
            nint? endAddr = _process.MainModule?.BaseAddress + _process.MainModule?.ModuleMemorySize;

            nint hProcess = Kernel32.OpenProcess(1040, bInheritHandle: false, _process.Id);

            if (hProcess > IntPtr.Zero)
            {
                nint addr = _process.MainModule?.BaseAddress ?? IntPtr.Zero;

                MemoryBasicInformation64 lpBuffer;
                while (Kernel32.VirtualQueryEx(hProcess, addr, out lpBuffer,
                    (nint)Marshal.SizeOf(typeof(MemoryBasicInformation64))) > 0)
                {
                    regions.Add(lpBuffer);
                    addr = IntPtr.Add((nint)lpBuffer.BaseAddress, (int)lpBuffer.RegionSize);

                    if (addr > endAddr)
                        break;
                }
            }

            Kernel32.CloseHandle(hProcess);
            return regions.ToArray();
        }
        return null;
    }

    /// <summary>遍历进程全部虚拟地址空间，返回所有内存区域（64位格式）</summary>
    public MemoryBasicInformation64[]? GetMemoryBasicInformation64()
    {
        Process? process = _process;
        if (process != null && process.Id > 0 && !_process!.HasExited)
        {
            var regions = new List<MemoryBasicInformation64>();
            nint hProcess = Kernel32.OpenProcess(1040, bInheritHandle: false, _process.Id);

            if (hProcess > IntPtr.Zero)
            {
                nint addr = _process.MainModule?.BaseAddress ?? IntPtr.Zero;

                MemoryBasicInformation64 lpBuffer;
                while (Kernel32.VirtualQueryEx(hProcess, addr, out lpBuffer,
                    (nint)Marshal.SizeOf(typeof(MemoryBasicInformation64))) > 0)
                {
                    regions.Add(lpBuffer);
                    addr = IntPtr.Add((nint)lpBuffer.BaseAddress, (int)lpBuffer.RegionSize);

                    if (addr == IntPtr.Zero) // 到达地址空间末端
                        break;
                }
            }

            Kernel32.CloseHandle(hProcess);
            return regions.ToArray();
        }
        return null;
    }

    /// <summary>遍历进程全部虚拟地址空间，返回所有内存区域（32位格式）</summary>
    public MemoryBasicInformation32[]? GetMemoryBasicInformation32()
    {
        Process? process = _process;
        if (process != null && process.Id > 0 && !_process!.HasExited)
        {
            var regions = new List<MemoryBasicInformation32>();
            nint hProcess = Kernel32.OpenProcess(1040, bInheritHandle: false, _process.Id);

            if (hProcess > IntPtr.Zero)
            {
                nint addr = IntPtr.Zero;

                MemoryBasicInformation32 lpBuffer;
                while (Kernel32.VirtualQueryEx(hProcess, addr, out lpBuffer,
                    (nint)Marshal.SizeOf(typeof(MemoryBasicInformation32))) > 0)
                {
                    regions.Add(lpBuffer);
                    addr = IntPtr.Add((nint)lpBuffer.BaseAddress, (int)lpBuffer.RegionSize);

                    if (addr == IntPtr.Zero)
                        break;
                }
            }

            Kernel32.CloseHandle(hProcess);
            return regions.ToArray();
        }
        return null;
    }

    // ---- 类型化读取方法 ----

    /// <summary>从指定内存地址读取 1 字节</summary>
    public byte ToByte(nint memoryAddress)
    {
        byte[] buffer = new byte[Marshal.SizeOf(typeof(byte))];
        if (_process != null && !_process.HasExited
            && Kernel32.ReadProcessMemory(_process!.Handle, memoryAddress, buffer, buffer.Length, out var _))
        {
            return buffer[0];
        }
        return 0;
    }

    /// <summary>从指定内存地址读取 2 字节有符号整数（Int16）</summary>
    public short ToInt16(nint memoryAddress)
    {
        byte[] buffer = new byte[Marshal.SizeOf(typeof(short))];
        if (_process != null && !_process.HasExited
            && Kernel32.ReadProcessMemory(_process!.Handle, memoryAddress, buffer, buffer.Length, out var _))
        {
            return BitConverter.ToInt16(buffer, 0);
        }
        return 0;
    }

    /// <summary>从指定内存地址读取 4 字节有符号整数（Int32）</summary>
    public int ToInt32(nint memoryAddress)
    {
        byte[] buffer = new byte[Marshal.SizeOf(typeof(int))];
        if (_process != null && !_process.HasExited
            && Kernel32.ReadProcessMemory(_process!.Handle, memoryAddress, buffer, buffer.Length, out var _))
        {
            return BitConverter.ToInt32(buffer, 0);
        }
        return 0;
    }

    /// <summary>从指定内存地址读取 4 字节单精度浮点数（float）</summary>
    public float ToSingle(nint memoryAddress)
    {
        byte[] buffer = new byte[Marshal.SizeOf(typeof(float))];
        if (_process != null && !_process.HasExited
            && Kernel32.ReadProcessMemory(_process!.Handle, memoryAddress, buffer, buffer.Length, out var _))
        {
            return BitConverter.ToSingle(buffer, 0);
        }
        return 0f;
    }

    /// <summary>直接封装 ReadProcessMemory：将字节数组填入指定内存地址</summary>
    public bool ReadProcessMemory(nint memoryAddress, byte[] lpBuffer)
    {
        if (_process != null && !_process.HasExited)
        {
            return Kernel32.ReadProcessMemory(_process!.Handle, memoryAddress, lpBuffer, lpBuffer.Length, out var _);
        }
        return false;
    }

    /// <summary>直接封装 WriteProcessMemory：将字节数组写入指定内存地址</summary>
    public bool WriteProcessMemory(nint memoryAddress, byte[] lpBuffer)
    {
        if (_process != null && !_process.HasExited)
        {
            return Kernel32.WriteProcessMemory(_process!.Handle, memoryAddress, lpBuffer, lpBuffer.Length, out var _);
        }
        return false;
    }

    /// <summary>
    /// 持续写入：启动一个后台线程，每 100ms 将 lpBuffer 写入目标地址。
    /// 用于实现"无限金币"等内存锁定的作弊功能。
    /// </summary>
    /// <param name="memoryAddress">写入目标地址</param>
    /// <param name="lpBuffer">待写入的数据</param>
    public void WriteProcessMemoryOn(int memoryAddress, byte[] lpBuffer)
    {
        if (_canceller.ContainsKey(memoryAddress))
            return; // 已有持续写入，避免重复启动

        CancellationTokenSource token = new CancellationTokenSource();
        _canceller.Add(memoryAddress, token);

        Task.Run(() =>
        {
            while (!token.IsCancellationRequested)
            {
                WriteProcessMemory(memoryAddress, lpBuffer);
                Thread.Sleep(100);
            }
        }, token.Token);
    }

    /// <summary>停止指定地址的持续写入循环</summary>
    public void WriteProcessMemoryOff(int memoryAddress)
    {
        if (_canceller.TryGetValue(memoryAddress, out CancellationTokenSource? value))
        {
            value.Cancel();
            _canceller.Remove(memoryAddress);
        }
    }

    /// <summary>
    /// 强制写入：先修改内存页面保护属性为可读写可执行（PAGE_READWRITE），
    /// 写入后恢复原始保护属性。用于写入受保护页面（如代码段）。
    /// </summary>
    public bool WriteProcessMemoryEnforced(nint memoryAddress, byte[] lpBuffer)
    {
        bool result = false;
        if (_process != null && !_process.HasExited
            && Kernel32.VirtualProtectEx(_process!.Handle, memoryAddress, lpBuffer.Length, 64,
                out var lpflOldProtect))
        {
            result = Kernel32.WriteProcessMemory(
                _process.Handle, memoryAddress, lpBuffer, lpBuffer.Length, out var lpNumberOfBytesWritten);

            // 恢复原始页面属性
            Kernel32.VirtualProtectEx(
                _process.Handle, memoryAddress, lpBuffer.Length, lpflOldProtect, out lpNumberOfBytesWritten);
        }
        return result;
    }
}

using System;

namespace Training.Game;

/// <summary>
/// 游戏内存中特定属性的地址描述。
/// 使用记录结构（record）定义，包含属性枚举、偏移量、长度三个字段。
/// </summary>
/// <typeparam name="TPropertyEnum">属性枚举类型（如某游戏版本定义的地址偏移枚举）</typeparam>
public readonly struct Address<TPropertyEnum>(TPropertyEnum property, int offset, int length)
    where TPropertyEnum : struct, Enum
{
    /// <summary>属性枚举值，标识此地址对应的数据字段</summary>
    public TPropertyEnum Property { get; } = property;

    /// <summary>相对于基址的字节偏移量</summary>
    public int Offset { get; } = offset;

    /// <summary>数据长度（字节），用于变长数据（如字符串数组）</summary>
    public int Length { get; } = length;
}

namespace Training.Game;

/// <summary>
/// 目标游戏进程的运行状态枚举。
/// </summary>
public enum ProcessState
{
    /// <summary>进程未找到（未启动）</summary>
    NotRunning,

    /// <summary>进程正在运行</summary>
    Running,

    /// <summary>进程已退出</summary>
    HasExited
}

using System;

namespace Training.Framework;

/// <summary>
/// 数据模型的基类，封装 Address（内存地址）和 Checked（选中状态）属性。
/// 继承自 ModelCollection，提供脏数据追踪能力。
/// </summary>
public abstract class Model<TPropertyKey> : ModelCollection<TPropertyKey>
    where TPropertyKey : struct, Enum
{
    private bool _checked;
    private int _address;

    /// <summary>
    /// 此数据模型对应的内存地址（由 Scanner 扫描得到）。
    /// 设置时通过 SetProperty 触发 PropertyChanged 和脏数据记录。
    /// </summary>
    public int Address
    {
        get => _address;
        set => SetProperty(ref _address, value, "Address");
    }

    /// <summary>
    /// UI 层选中状态，用于多选编辑等场景。
    /// 切换 Checked 时会同步其他已选项的 Checked 状态。
    /// </summary>
    public bool Checked
    {
        get => _checked;
        set => SetProperty(ref _checked, value, "Checked");
    }
}

using System;
using System.Collections.Generic;
using System.ComponentModel;
using CommunityToolkit.Mvvm.ComponentModel;

namespace Training.Framework;

/// <summary>
/// 数据模型的容器基类，提供：
/// 1. Index 属性：模型在集合中的序号
/// 2. 脏数据（Dirty Data）追踪：通过 HashSet 记录哪些属性被修改过
///
/// 使用方式：设置 RecordingDirtyData=true 后，属性变更自动记录到 _dirtyData；
/// 保存时调用 GetDirtyData() 获取所有被修改的属性，只保存这些字段。
/// </summary>
public abstract class ModelCollection<TPropertyKey> : ObservableObject
    where TPropertyKey : struct, Enum
{
    private readonly HashSet<TPropertyKey> _dirtyData = new HashSet<TPropertyKey>();

    /// <summary>模型在所属集合中的序号（从 0 开始）</summary>
    public int Index { get; set; }

    /// <summary>
    /// 是否启用脏数据记录。设为 true 后，OnPropertyChanged 会自动记录变更的属性。
    /// 用于批量编辑场景：仅记录实际修改的字段，避免全量写入。
    /// </summary>
    public bool RecordingDirtyData { get; set; }

    protected override void OnPropertyChanged(PropertyChangedEventArgs e)
    {
        if (RecordingDirtyData && !string.IsNullOrEmpty(e.PropertyName))
        {
            AddToDirtyData(e.PropertyName);
        }
        base.OnPropertyChanged(e);
    }

    /// <summary>获取所有被标记为脏数据的属性枚举值</summary>
    public IEnumerable<TPropertyKey> GetDirtyData()
    {
        return _dirtyData;
    }

    /// <summary>清除指定属性的脏标记（保存成功后调用）</summary>
    public void ResetDirtyData(TPropertyKey property)
    {
        _dirtyData.Remove(property);
    }

    /// <summary>清除所有脏标记</summary>
    public void ResetDirtyDataAll()
    {
        _dirtyData.Clear();
    }

    /// <summary>
    /// 根据属性名（字符串）查找对应的枚举值并加入脏数据集合。
    /// 依赖枚举成员名与属性名一致（如枚举值 EMapVersion.MapName 对应属性 "MapName"）。
    /// </summary>
    private void AddToDirtyData(string keyName)
    {
        if (Enum.TryParse<TPropertyKey>(keyName, out var result))
        {
            _dirtyData.Add(result);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using Training.Game;

namespace Training.Framework;

/// <summary>
/// 数据读写服务基类，封装从游戏内存读取数据、写入待变更数据、提交到内存的完整流程。
///
/// 设计模式：
/// - 泛型约束：TPropertyEnum 为属性地址枚举，TModel 为数据模型类型
/// - 读写分离：Read* 系列方法从内存/缓冲区读取，AddToWritingData 系列仅将变更加入队列
/// - 脏数据写入：SaveDataAll 只保存有脏标记的模型；SaveToMemory 执行实际写入
/// - 强制写入：对于只读内存区域（如代码段），使用 WriteProcessMemoryEnforced 先改页面属性
/// </summary>
public abstract class Service<TPropertyEnum, TModel>(ProcessIO process, ICollection<TModel> models)
    where TPropertyEnum : struct, Enum
    where TModel : Model<TPropertyEnum>, new()
{
    protected ICollection<TModel> _models = models;
    protected ProcessIO _process = process;

    /// <summary>数据块基址（如英雄数组的起始地址）</summary>
    protected int _blockAddress;

    /// <summary>每个数据单元的字节大小</summary>
    protected int _blockSize;

    /// <summary>待写入的普通变更（直接 WriteProcessMemory）</summary>
    protected Dictionary<int, byte[]> _writingData = new Dictionary<int, byte[]>();

    /// <summary>待写入的强制变更（需先改页面属性）</summary>
    protected Dictionary<int, byte[]> _writingDataEnforced = new Dictionary<int, byte[]>();

    /// <summary>属性枚举 → (偏移量, 长度) 的地址映射表</summary>
    protected Dictionary<TPropertyEnum, (int Offset, int LengthOrCount)> _addresses = new Dictionary<TPropertyEnum, (int, int)>();

    /// <summary>加载配置文件中的地址映射（子类实现）</summary>
    public abstract void LoadSettings();

    /// <summary>设置数据块的基址和单元大小（子类实现）</summary>
    public abstract void SetBlock(int address, int offset, int size);

    /// <summary>从内存加载单个数据单元（子类实现）</summary>
    public abstract bool LoadData(int index);

    /// <summary>
    /// 根据 Index 获取或创建模型实例。
    /// 若集合中已存在该 Index 的模型，直接返回；否则新建并加入集合。
    /// </summary>
    protected virtual TModel GetModel(int index)
    {
        TModel? val = _models.FirstOrDefault(item => item.Index == index);
        if (val == null)
        {
            val = new TModel { Index = index };
            _models.Add(val);
        }
        return val;
    }

    /// <summary>
    /// 批量加载数据（最多 maxCount 个），遇首个加载失败时停止，
    /// 并删除集合中超出范围的多余模型。
    /// </summary>
    public virtual void LoadDataAll(int maxCount = 255)
    {
        for (int i = 0; i < maxCount; i++)
        {
            if (!LoadData(i))
            {
                i++;
                // 移除 i 之后的所有模型
                for (int j = i; j < _models.Count; j++)
                {
                    _models.Remove(_models.ElementAt(j));
                }
                break;
            }
        }
    }

    /// <summary>重置：清空块信息、地址表和待写入队列</summary>
    public virtual void Reset()
    {
        _blockAddress = 0;
        _blockSize = 0;
        _addresses.Clear();
        _writingData.Clear();
        _writingDataEnforced.Clear();
    }

    /// <summary>保存单个模型到内存（子类实现）</summary>
    public abstract void SaveData(TModel model);

    /// <summary>遍历所有有脏标记的模型，调用 SaveData</summary>
    public virtual void SaveDataAll()
    {
        foreach (TModel item in _models.Where(item => item.GetDirtyData().Any()))
        {
            SaveData(item);
        }
    }

    /// <summary>将所有待写入变更提交到游戏内存</summary>
    public void SaveToMemory()
    {
        foreach (var writingDatum in _writingData)
        {
            _process.WriteProcessMemory(writingDatum.Key, writingDatum.Value);
        }
        _writingData.Clear();

        foreach (var item in _writingDataEnforced)
        {
            _process.WriteProcessMemoryEnforced(item.Key, item.Value);
        }
        _writingDataEnforced.Clear();
    }

    /// <summary>仅提交强制写入队列（不处理普通队列）</summary>
    protected void SaveToMemoryEnforced()
    {
        foreach (var item in _writingDataEnforced)
        {
            _process.WriteProcessMemoryEnforced(item.Key, item.Value);
        }
        _writingDataEnforced.Clear();
    }

    // ---- Read* 系列：从内存/缓冲区读取 ----
    // 规律：
    // - 无 index 参数：从 src[offset] 直接读取单个值
    // - 有 index 参数：从 src[offset + n*index] 读取（第 index 个元素）
    // - UseLength 参数：从 src[offset + length*index] 读取（变长数组）

    protected sbyte ReadToSByte(TPropertyEnum property, byte[] src) { /* 略：查地址表，从 src 读 1 字节 */ return default; }
    protected byte ReadToByte(TPropertyEnum property, byte[] src, int index) { return default; }
    protected byte ReadToByte(TPropertyEnum property, byte[] src) { return default; }
    protected byte ReadToByte(TPropertyEnum property, TModel model) { return default; }
    protected short ReadToInt16(TPropertyEnum property, byte[] src) { return default; }
    protected short ReadToInt16UseLength(TPropertyEnum property, byte[] src, int index) { return default; }
    protected short ReadToInt16(TPropertyEnum property, byte[] src, int index) { return default; }
    protected short ReadToInt16(TPropertyEnum property, TModel model) { return default; }
    protected int ReadToInt32(TPropertyEnum property, byte[] src) { return default; }
    protected int ReadToInt32(TPropertyEnum property, byte[] src, int index) { return default; }
    protected int ReadToInt32UseLength(TPropertyEnum property, byte[] src, int index) { return default; }
    protected int ReadToInt32(TPropertyEnum property, TModel model) { return default; }
    protected long ReadToInt64(TPropertyEnum property, byte[] src) { return default; }
    protected float ReadToSingle(TPropertyEnum property, TModel model) { return default; }
    protected float ReadToSingle(TPropertyEnum property, byte[] src) { return default; }
    protected byte[]? ReadToByteArray(TPropertyEnum property, byte[] src) { return default; }
    protected byte[]? ReadToByteArray(TPropertyEnum property, TModel model) { return default; }
    protected short[]? ReadToInt16Array(TPropertyEnum property, byte[] src) { return default; }
    protected short[]? ReadToInt16Array(TPropertyEnum property, TModel model) { return default; }
    protected int[]? ReadToInt32Array(TPropertyEnum property, byte[] src) { return default; }
    protected int[]? ReadToInt32Array(TPropertyEnum property, TModel model) { return default; }
    protected string? ReadToString(TPropertyEnum property, byte[] src) { return default; }
    protected string? ReadToString(TPropertyEnum property, TModel model) { return default; }

    // ---- AddToWritingData 系列：加入待写入队列 ----

    protected void AddToWritingData(TPropertyEnum property, TModel model, float data) { }
    protected void AddToWritingDataUseLength(TPropertyEnum property, TModel model, int data, int index) { }
    protected void AddToWritingData(TPropertyEnum property, TModel model, int data) { }
    protected void AddToWritingData(TPropertyEnum property, TModel model, long data) { }
    protected void AddToWritingData(TPropertyEnum property, TModel model, int data, int index) { }
    protected void AddToWritingData(TPropertyEnum property, TModel model, short data, int index) { }
    protected void AddToWritingData(TPropertyEnum property, TModel model, short data) { }
    protected void AddToWritingData(TPropertyEnum property, TModel model, byte data) { }
    protected void AddToWritingData(TPropertyEnum property, TModel model, byte data, int index) { }
    protected void AddToWritingData(TPropertyEnum property, TModel model, byte[] data) { }
    protected void AddToWritingDataEnforced(TPropertyEnum property, TModel model, float data) { }
    protected void AddToWritingDataEnforced(TPropertyEnum property, TModel model, int data) { }
    protected void AddToWritingDataEnforced(TPropertyEnum property, TModel model, byte[] data) { }
}

