/// <summary>
/// ViewModel 基类，封装选中模型管理和保存命令。
/// 选中模型时会设置其 Checked=true，并清除其他模型的 Checked 状态。
/// </summary>
public abstract class ViewModel<TPropertyKey, TModel> : ObservableObject
    where TPropertyKey : struct, Enum
    where TModel : Model<TPropertyKey>
{
    private TModel? _checkingModel;

    /// <summary>
    /// 当前正在查看/编辑的模型。
    /// 赋值时自动处理互斥逻辑：先清除旧模型的 Checked，再设置新模型的 Checked。
    /// </summary>
    public TModel? CheckingModel
    {
        get => _checkingModel;
        set
        {
            if (_checkingModel != value)
            {
                if (_checkingModel != null)
                    _checkingModel.Checked = false;

                SetProperty(ref _checkingModel, value, "CheckingModel");

                if (_checkingModel != null)
                    _checkingModel.Checked = true;
            }
        }
    }

    /// <summary>选中模型的命令（可绑定到 ListView 等控件的 SelectedItem）</summary>
    public ICommand CheckCommand { get; private set; }

    public ViewModel()
    {
        CheckCommand = new RelayCommand<TModel>(CheckCommandExecute);
    }

    /// <summary>加载模型数据（子类实现）</summary>
    protected abstract void Load(object m);

    /// <summary>重置 ViewModel 状态（子类实现）</summary>
    protected abstract void Reset();

    /// <summary>保存当前模型到游戏内存（子类实现）</summary>
    public abstract void Save();

    /// <summary>选中命令的执行逻辑（子类实现）</summary>
    protected abstract void CheckCommandExecute(TModel? model);
}

