public abstract class ViewModelRecipient<TPropertyKey, TModel> : ViewModel<TPropertyKey, TModel>,
    IRecipient<ValueChangedMessage<AnalyzeMessage>>
    where TPropertyKey : struct, Enum
    where TModel : Model<TPropertyKey>
{
