    public virtual void ReceiveMessageOff()
    {
        Analyzer<TPropertyKey, TModel>.Unregister(this);
    }

    /// <summary>
    /// 处理收到的分析消息（子类实现）。
    /// 通常在此更新模型数据并刷新 UI。
    /// </summary>
    public abstract void Receive(ValueChangedMessage<AnalyzeMessage> message);
}

