/// <summary>
/// 分析器基类：订阅 Scanner 的扫描结果（ScanMessage），解析出具体数据的地址并广播。
/// 流程：Scanner 找到地址 → Analyzer 解析地址偏移 → AnalyzeMessage 广播给 ViewModel
/// </summary>
public abstract class Analyzer<TPropertyKey, TModel> : ViewModel<TPropertyKey, TModel>,
    IRecipient<ValueChangedMessage<ScanMessage>>
    where TPropertyKey : struct, Enum
    where TModel : Model<TPropertyKey>
{
    /// <summary>静态发送：广播分析结果消息</summary>
    protected static void Send(ValueChangedMessage<AnalyzeMessage> message)
    {
        MessengerCenter.Send<ValueChangedMessage<AnalyzeMessage>, AnalyzeMessage>(message);
    }

    /// <summary>静态注册：注册扫描结果接收者</summary>
    public static void Register<TRecipient>(TRecipient recipient)
        where TRecipient : class, IRecipient<ValueChangedMessage<AnalyzeMessage>>
    {
        MessengerCenter.Register<TRecipient, ValueChangedMessage<AnalyzeMessage>>(recipient);
    }

    /// <summary>静态注销：取消接收者订阅</summary>
    public static void Unregister<TRecipient>(TRecipient recipient)
        where TRecipient : class, IRecipient<ValueChangedMessage<AnalyzeMessage>>
    {
        MessengerCenter.Unregister<TRecipient, ValueChangedMessage<AnalyzeMessage>>(recipient);
    }

    /// <summary>订阅 Scanner 的扫描结果广播</summary>
    public virtual void ReceiveMessageOn()
    {
        Scanner.Register(this);
    }

    /// <summary>取消 Scanner 订阅</summary>
    public virtual void ReceiveMessageOff()
    {
        Scanner.Unregister(this);
    }

    /// <summary>
    /// 处理 Scanner 的扫描结果，解析地址偏移，广播分析消息（子类实现）。
    /// </summary>
    public abstract void Receive(ValueChangedMessage<ScanMessage> message);
}

