/// <summary>
/// 具备 XML 文件持久化能力的 ViewModel 基类。
/// 将当前选中模型的配置保存到 XML 文件，或从 XML 文件恢复。
/// 要求 TModel 实现 ISerializeModel&lt;TModel&gt; 接口。
/// </summary>
public abstract class ViewModelSerialize<TPropertyKey, TModel> : ViewModelRecipient<TPropertyKey, TModel>
    where TPropertyKey : struct, Enum
    where TModel : Model<TPropertyKey>, ISerializeModel<TModel>, new()
{
    protected string? _fileName;
    protected string? _dirRule;

    /// <summary>
    /// 将当前 CheckingModel 的配置写入 XML 文件（覆盖）。
    /// 文件路径 = _dirRule / _fileName。
    /// </summary>
    public virtual void SaveToFile()
    {
        if (_dirRule != null && _fileName != null && base.CheckingModel != null)
        {
            Serializer.CreatePath(_dirRule);
            TModel val = new TModel();
            val.Write(base.CheckingModel);         // 从 CheckingModel 序列化到 val
            Serializer.SaveObjectToXml(val, _dirRule, _fileName);
        }
    }

    /// <summary>
    /// 从 XML 文件加载配置并应用到 CheckingModel。
    /// </summary>
    /// <returns>加载成功返回 true，文件不存在或 CheckingModel 为 null 返回 false</returns>
    public virtual bool LoadFromFile()
    {
        if (_dirRule != null && _fileName != null
            && base.CheckingModel != null
            && File.Exists(Path.Combine(_dirRule, _fileName)))
        {
            // 反序列化到临时对象，再 Read 回 CheckingModel
            Serializer.LoadObjectFromXml<TModel>(_dirRule, _fileName)?.Read(base.CheckingModel);
            return true;
        }
        return false;
    }
}

