using System;
using System.Diagnostics;
using System.IO;
using HandyKits.Tool;

namespace HoMM3;

/// <summary>
/// 游戏版本检测与类型识别工具，提供从 FileVersionInfo 推断 ExeVersion 的逻辑。
/// 根据 ProductName、文件大小、HoTA 配置文件综合判断。
/// </summary>
internal static class Common
{
    /// <summary>
    /// 根据可执行文件的版本信息（ProductName、文件大小）判断游戏版本。
    /// 优先级：ProductName → 文件大小（用于区分 ERA 不同版本）→ HoTA 版本配置文件
    /// </summary>
    /// <param name="info">FileVersionInfo.FromFileName() 获取的版本信息</param>
    /// <returns>对应的 ExeVersion 枚举值</returns>
    internal static ExeVersion GetExeVersion(FileVersionInfo info)
    {
        // 文件大小用于区分 ERA 2.4x 和 3.9x（ProductName 相同）
        long length;
        using (FileStream fileStream = File.OpenRead(info.FileName))
        {
            length = fileStream.Length;
        }

        // HoTA 版本从 HotA_settings.ini 读取"Main Version"字段
        string? hotaversion = null;
        string? productName = info.ProductName;
        if (productName != null && productName.Contains("Horn of The Abyss"))
        {
            string filePath = string.Concat(
                info.FileName.AsSpan(0, info.FileName.LastIndexOf('\\') + 1),
                "HotA_settings.ini");
            IniParser ini = new IniParser();
            ini.Load(filePath);
            hotaversion = ini.GetValue("Version", "Main Version");
        }

        return info.ProductName switch
        {
            "Heroes of Might and Magic® III: In the Wake of Gods" => length switch
            {
                3473408L => ExeVersion.ERA24x,  // ERA 2.4x（约 3.3MB）
                3801088L => ExeVersion.ERA39x,  // ERA 3.9x（约 3.6MB）
                _ => ExeVersion.WOG,
            },

            "Heroes of Might and Magic® III: The Shadow of Death"
                or "Heroes of Might and Magic\xFF\xFE III: The Shadow of Death" // 含 BOM 的变体
                => ExeVersion.SOD,

            "Heroes of Might and Magic® III: Horn of The Abyss" => hotaversion switch
            {
                "1.6.0" or "1.6.1" => ExeVersion.HoTA16,
                "1.7.0" or "1.7.1" or "1.7.2" or "1.7.3" => ExeVersion.HoTA17,
                _ => ExeVersion.HoTA18, // 默认最新版本
            },

            "Heroes(tm) Chronicles" => ExeVersion.CHR,
            _ => ExeVersion.None,
        };
    }
}

namespace HoMM3;

/// <summary>
/// 可执行文件版本枚举，对应 Heroes of Might and Magic III 的各个资料片版本。
/// 值采用位掩码设计，方便组合（如 ERA + HoTA 叠加）。
/// </summary>
public enum ExeVersion
{
    /// <summary>无法识别/未知版本</summary>
    None = 0,

    /// <summary>原版（Restoration of Erathia）</summary>
    ROE = 1,

    /// <summary>深渊号角（Armageddon's Blade）</summary>
    AB = 2,

    /// <summary>死亡阴影（Shadow of Death）</summary>
    SOD = 4,

    /// <summary> Chronicles 战役包</summary>
    CHR = 8,

    /// <summary>WoG（Wake of Gods）资料片</summary>
    WOG = 0x10,

    /// <summary>ERA 2.4x 系列</summary>
    ERA24x = 0x20,

    /// <summary>ERA 2.9x 系列</summary>
    ERA29x = 0x40,

    /// <summary>ERA 3.9x 系列</summary>
    ERA39x = 0x80,

    /// <summary>HoTA 1.6.x</summary>
    HoTA16 = 0x100,

    /// <summary>HoTA 1.7.x</summary>
    HoTA17 = 0x200,

    /// <summary>HoTA 1.8+（最新）</summary>
    HoTA18 = 0x400,

    /// <summary>默认地图玩家数量选项 3</summary>
    Default3 = 0x800,

    /// <summary>默认地图玩家数量选项 4</summary>
    Default4 = 0x1000,

    /// <summary>默认地图玩家数量选项 5</summary>
    Default5 = 0x2000,

    /// <summary>默认地图玩家数量选项 6</summary>
    Default6 = 0x4000,

    /// <summary>默认地图玩家数量选项 7</summary>
    Default7 = 0x8000
}

namespace HoMM3;

/// <summary>
/// 城镇阵营枚举，对应游戏中的 12 个种族。
/// 负值用于表示特殊状态（Neutral/None），正值对应城镇类型 ID。
/// </summary>
public enum Faction : sbyte
{
    /// <summary>未指定/无效</summary>
    None = sbyte.MinValue,

    /// <summary>中立生物（酒馆招募等场景）</summary>
    Neutral = -1,

    /// <summary>城堡（Castle）</summary>
    Castle = 0,

    /// <summary>壁垒（Rampart）</summary>
    Rampart = 1,

    /// <summary>塔楼（Tower）</summary>
    Tower = 2,

    /// <summary>地狱（Inferno）</summary>
    Inferno = 3,

    /// <summary>亡灵（Necropolis）</summary>
    Necropolis = 4,

    /// <summary>地下城（Dungeon's Lair）</summary>
    Dungeon = 5,

    /// <summary>据点（Stronghold）</summary>
    Stronghold = 6,

    /// <summary>堡垒（Fortress）</summary>
    Fortress = 7,

    /// <summary>元素（Conflux）</summary>
    Conflux = 8,

    /// <summary>港湾（Cove）</summary>
    Cove = 9,

