# Add class comment to HoMM3 source files
$src = "D:\GitHub\H3\H3Trainer\src\HoMM3"

# All namespaces and their descriptions
$map = @{
    "HoMM3.Standard" = "标准版（标准游戏数据读写）"
    "HoMM3.Rule"      = "WoG 规则（生物/技能/全局规则修改）"
    "HoMM3.Era"       = "ERA MOD（指挥官/追随者/部队经验）"
    "HoMM3.Setting"  = "版本配置（各资料片的地址偏移/资源映射）"
}

Get-ChildItem $src -Recurse -Include "*.cs" | ForEach-Object {
    $f = $_.FullName
    if ($f -match "\\obj\\" -or $f -match "\\bin\\") { return }
    $content = Get-Content $f -Raw
    $ns = ""
    foreach ($key in $map.Keys) {
        if ($content -match "namespace $key") { $ns = $key; break }
    }
    if ($ns -eq "") { return }
    $desc = $map[$ns]

    # Find the first class declaration after namespace
    if ($content -match '(namespace [^\n]+\n\n)(public|internal) (static |abstract |sealed )?(class|enum|struct) (\w+)') {
        $classDecl = $matches[2] + " " + $matches[4] + " " + $matches[5]
        $className = $matches[5]
        $summary = "$desc - $className"
        $comment = "/// <summary>`n/// $summary`n/// </summary>`n"
        $newContent = $content -replace (
            "(namespace $ns`n\n)(public|internal) (static |abstract |sealed )?(class|enum|struct) ($([regex]::Escape($className)))",
            "`$1$comment`$2 `$3`$4 `$5"
        )
        if ($newContent -ne $content) {
            Set-Content $f -Value $newContent -NoNewline
            Write-Host "OK: $($_.Name)"
        }
    }
}

