﻿using System.Collections.Generic;
using System.Linq;
using HandyKits.Extensions;
using HoMM3.BaseObj;
using HoMM3.Setting;
using HoMM3.Standard;
using Training.Framework;
using Training.Game;

namespace HoMM3.Era;

internal class CommanderService : Service<CommanderProperty, CommanderModel>
{
	public CommanderService(ProcessIO process, ICollection<CommanderModel> models)
		: base(process, models)
	{
	}

	public override void LoadSettings()
	{
		_addresses.AddRange<CommanderProperty, (int, int)>(SetEra.CommanderAddress);
	}

	public override bool LoadData(int index)
	{
		if (_blockAddress > 0)
		{
			byte[] array = new byte[_blockSize];
			int num = _blockAddress + index * _blockSize;
			if (_process.ReadProcessMemory(num, array))
			{
				CommanderModel model = GetModel(index);
				model.RecordingDirtyData = false;
				model.Address = num;
				model.Condition = (CommanderCondition)ReadToByte(CommanderProperty.Condition, array);
				model.Alive = ReadToByte(CommanderProperty.Alive, array) == 0;
				model.Class = (CommanderClass)ReadToByte(CommanderProperty.Class, array);
				model.Hero = ReadToByte(CommanderProperty.Hero, array);
				model.Attack = ReadToInt32(CommanderProperty.Attack, array);
				model.Defense = ReadToInt32(CommanderProperty.Defense, array);
				model.HP = ReadToInt32(CommanderProperty.HP, array);
				model.MaxDamage = ReadToInt32(CommanderProperty.MaxDamage, array);
				model.Power = ReadToInt32(CommanderProperty.Power, array);
				model.Speed = ReadToInt32(CommanderProperty.Speed, array);
				model.Resistance = ReadToInt32(CommanderProperty.Resistance, array);
				model.Name = ReadToString(CommanderProperty.Name, array);
				model.Exp = ReadToInt32(CommanderProperty.Exp, array);
				model.Level = ReadToInt32(CommanderProperty.Level, array) + 1;
				for (byte b = 0; b < 6; b++)
				{
var commanderSkillModel= model.Skill.ElementAtOrDefault(b);
					if (commanderSkillModel == null)
					{
						commanderSkillModel = new CommanderSkillModel
						{
							Index = b,
							ID = b
						};
						model.Skill.Add(commanderSkillModel);
					}
					commanderSkillModel.RecordingDirtyData = false;
					commanderSkillModel.CommanderSkill = (CommanderSkillLevel)ReadToInt32(CommanderProperty.CommanderSkill, array, b);
					commanderSkillModel.RecordingDirtyData = true;
				}
				Artifact[] array2 = HeroViewModel.Artifacts.Where((Artifact item) => item.Slot == ArtifactSlot.Commander).ToArray();
				for (int num2 = 0; num2 < array2.Length; num2++)
				{
var commanderGearModel= model.Gear.ElementAtOrDefault(num2);
					if (commanderGearModel == null)
					{
						commanderGearModel = new CommanderGearModel
						{
							Index = num2
						};
						model.Gear.Add(commanderGearModel);
						commanderGearModel.RecordingDirtyData = true;
						commanderGearModel.Gear = (short)array2.ElementAt(num2).ID;
					}
					for (int num3 = 0; num3 < array2.Length; num3++)
					{
						short num4 = ReadToInt16UseLength(CommanderProperty.Gear, array, num3);
						if (num4 == 0)
						{
							if (commanderGearModel.GearOrder > 0)
							{
								commanderGearModel.RecordingDirtyData = false;
								commanderGearModel.GearExp = 0;
								commanderGearModel.GearOrder = 0;
								commanderGearModel.RecordingDirtyData = true;
							}
							break;
						}
						if (num4 == commanderGearModel.Gear)
						{
							commanderGearModel.RecordingDirtyData = false;
							commanderGearModel.GearOrder = num3 + 1;
							commanderGearModel.GearExp = ReadToInt16UseLength(CommanderProperty.GearExp, array, num3);
							commanderGearModel.RecordingDirtyData = true;
							break;
						}
					}
				}
				int num5 = ReadToInt32(CommanderProperty.Ability, array);
				for (int num6 = 0; num6 < SetEra.ECommanderAbility.Count; num6++)
				{
var commanderAbilityModel= model.Ability.ElementAtOrDefault(num6);
					if (commanderAbilityModel == null)
					{
						commanderAbilityModel = new CommanderAbilityModel
						{
							Index = num6,
							Item = SetEra.ECommanderAbility.ElementAt(num6).Key
						};
						model.Ability.Add(commanderAbilityModel);
					}
					commanderAbilityModel.RecordingDirtyData = false;
					commanderAbilityModel.Activated = ((uint)commanderAbilityModel.Item & (uint)num5) == (uint)commanderAbilityModel.Item;
					commanderAbilityModel.RecordingDirtyData = true;
				}
				model.RecordingDirtyData = true;
				return true;
			}
		}
		return false;
	}

	public override void SaveData(CommanderModel model)
	{
		if (_blockAddress <= 0)
		{
			return;
		}
		foreach (CommanderProperty dirtyDatum in model.GetDirtyData())
		{
			switch (dirtyDatum)
			{
			case CommanderProperty.Condition:
				AddToWritingData(CommanderProperty.Condition, model, (byte)model.Condition);
				break;
			case CommanderProperty.Alive:
				AddToWritingData(CommanderProperty.Alive, model, (!model.Alive) ? ((byte)1) : ((byte)0));
				break;
			case CommanderProperty.Class:
				AddToWritingData(CommanderProperty.Class, model, (byte)model.Class);
				break;
			case CommanderProperty.Hero:
				AddToWritingData(CommanderProperty.Hero, model, model.Hero);
				break;
			case CommanderProperty.Attack:
				AddToWritingData(CommanderProperty.Attack, model, model.Attack);
				break;
			case CommanderProperty.Defense:
				AddToWritingData(CommanderProperty.Defense, model, model.Defense);
				break;
			case CommanderProperty.HP:
				AddToWritingData(CommanderProperty.HP, model, model.HP);
				break;
			case CommanderProperty.MaxDamage:
				AddToWritingData(CommanderProperty.MaxDamage, model, model.MaxDamage);
				break;
			case CommanderProperty.Power:
				AddToWritingData(CommanderProperty.Power, model, model.Power);
				break;
			case CommanderProperty.Speed:
				AddToWritingData(CommanderProperty.Speed, model, model.Speed);
				break;
			case CommanderProperty.Resistance:
				AddToWritingData(CommanderProperty.Resistance, model, model.Resistance);
				break;
			case CommanderProperty.Exp:
				AddToWritingData(CommanderProperty.Exp, model, model.Exp);
				break;
			case CommanderProperty.Level:
				AddToWritingData(CommanderProperty.Level, model, model.Level - 1);
				break;
			}
		}
		foreach (CommanderSkillModel item in model.Skill.Where((CommanderSkillModel item) => item.GetDirtyData().Any()))
		{
			foreach (CommanderProperty dirtyDatum2 in item.GetDirtyData())
			{
				if (dirtyDatum2 == CommanderProperty.CommanderSkill)
				{
					AddToWritingData(CommanderProperty.CommanderSkill, model, (int)item.CommanderSkill, item.Index);
