namespace HoMM3.Era;

public class CommanderViewModel : ViewModelRecipient<CommanderProperty, CommanderModel>
{
	private CommanderService? _service;

	private bool _activated;

	public ObservableCollection<CommanderModel> Models { get; } = new ObservableCollection<CommanderModel>();

	public bool Activated
	{
		get
		{
			return _activated;
		}
		set
		{
			SetProperty(ref _activated, value, "Activated");
		}
	}

	public ICommand CommanderGearCommand { get; set; }

	public CommanderViewModel()
	{
		CommanderGearCommand = new RelayCommand<CommanderGearModel>(CommanderGearCommandExecute);
	}

	public override void Receive(ValueChangedMessage<AnalyzeMessage> message)
	{
		if (message.Value.Address > 0)
		{
			Array.ForEach(Models.ToArray(), delegate(CommanderModel item)
			{
				item.ResetDirtyDataAll();
			});
			Array.ForEach(Models.ToArray(), delegate(CommanderModel item)
			{
				Array.ForEach(item.Skill.ToArray(), delegate(CommanderSkillModel commanderSkillModel)
				{
					commanderSkillModel.ResetDirtyDataAll();
				});
			});
			Array.ForEach(Models.ToArray(), delegate(CommanderModel item)
			{
				Array.ForEach(item.Gear.ToArray(), delegate(CommanderGearModel commanderGearModel)
				{
					commanderGearModel.ResetDirtyDataAll();
				});
			});
			Array.ForEach(Models.ToArray(), delegate(CommanderModel item)
			{
				Array.ForEach(item.Ability.ToArray(), delegate(CommanderAbilityModel commanderAbilityModel)
				{
					commanderAbilityModel.ResetDirtyDataAll();
				});
			});
			Load(message);
		}
		else
		{
			Reset();
		}
	}

	public override void Save()
	{
		if (Activated)
		{
			_service?.SaveDataAll();
			_service?.SaveToMemory();
		}
	}

	protected override void CheckCommandExecute(CommanderModel? model)
	{
		base.CheckingModel = model;
	}

	protected override async void Load(object m)
	{
		if (!(m is ValueChangedMessage<AnalyzeMessage> valueChangedMessage))
		{
			return;
		}
var process= valueChangedMessage.Value.Process;
		if (process == null)
		{
			return;
		}
		Activated = (bool)valueChangedMessage.Value.Others[2];
		if (Activated)
		{
			int maxCount = await HeroViewModel.RequestHeroCount(new AsyncRequestMessage<int>());
			if (_service == null)
			{
				_service = new CommanderService(process, Models);
			}
			_service.SetBlock(42344640, 0, 296);
			_service.LoadSettings();
			_service.LoadDataAll(maxCount);
		}
	}

	protected override void Reset()
	{
		base.CheckingModel = null;
		_service?.Reset();
		Models.Clear();
	}

	private void CommanderGearCommandExecute(CommanderGearModel? gear)
	{
		if (base.CheckingModel == null || gear == null)
		{
			return;
		}
		if (gear.GearOrder == 0)
		{
			gear.GearOrder = (byte)(base.CheckingModel.Gear.Max((CommanderGearModel item) => item.GearOrder) + 1);
			return;
		}
		Array.ForEach(base.CheckingModel.Gear.Where((CommanderGearModel item) => item.GearOrder > gear.GearOrder).ToArray(), delegate(CommanderGearModel item)
		{
			item.GearOrder--;
		});
		gear.GearOrder = 0;
		gear.GearExp = 0;
	}
}

