	private HitTestResultBehavior DoHitTest(HitTestResult result)

	{

		if (result is PointHitTestResult pointHitTestResult && result.VisualHit is DrawingVisual { Parent: var parent } drawingVisual)
		{
			var host = parent as MapVisualHost;

			if (host != null)

			{

				bool flag = false;

				Point pointHit = pointHitTestResult.PointHit;

				int num = (int)Math.Floor(pointHit.X / (double)host.CellSize);

				pointHit = pointHitTestResult.PointHit;

				int num2 = (int)Math.Floor(pointHit.Y / (double)host.CellSize);

				int z = ((!(host.Name == "OnGround")) ? 1 : 0);

				Rect contentBounds = drawingVisual.ContentBounds;

				int num3 = (int)Math.Floor(contentBounds.Width / (double)host.CellSize);

				contentBounds = drawingVisual.ContentBounds;

				int num4 = (int)Math.Floor(contentBounds.Height / (double)host.CellSize);

				contentBounds = drawingVisual.ContentBounds;

				int x = (int)Math.Round(contentBounds.X / (double)host.CellSize) + (num3 - 1) / 2;

				contentBounds = drawingVisual.ContentBounds;

				int y = (int)Math.Round(contentBounds.Y / (double)host.CellSize) + num4 - 1;

				if (_sandbable.ViewArea)

				{

					SandTableModel? checkingModel = _sandbable.CheckingModel;

					if (checkingModel != null && checkingModel.ViewEnabled)

					{

						_sandbable.ViewArea = false;

						_sandbable.OpenArea(num, num2, z, (byte)Player.SelectedValue, (int)Radius.Value);

						goto IL_0469;

					}

				}

				if (num3 == 1 && num4 == 1)

				{

					var heroModel = _hero.Models.FirstOrDefault((HeroModel item) => item.LocationX == x && item.LocationY == y && item.LocationZ == z);

					if (heroModel != null)

					{

						_hero.CheckCommand.Execute(heroModel);

						if (TabPage.CurrentIndex == 1)

						{

							ScrollHero();

						}

						else

						{

							TabPage.CurrentIndex = 1;

						}

					}

					else

					{

						flag = true;

					}

				}

				else if (num3 == 5 && num4 == 3)

				{

					_town.CheckCommand.Execute(_town.Models.FirstOrDefault((TownModel item) => item.LocationX == x && item.LocationY == y && item.LocationZ == z));

					if (TabPage.CurrentIndex == 2)

					{

						ScrollTown();

					}

					else

					{

						TabPage.CurrentIndex = 2;

					}

				}

				else if (num3 == 3 && num4 == 2)

				{

					_mine.CheckCommand.Execute(_mine.Models.FirstOrDefault((MineModel item) => item.LocationX == x && item.LocationY == y && item.LocationZ == z));

					if (TabPage.CurrentIndex == 3)

					{

						ScrollMine();

					}

					else

					{

						TabPage.CurrentIndex = 3;

					}

				}

				else if (num3 == 2 && num4 == 2)

				{

					_dwelling.CheckCommand.Execute(_dwelling.Models.FirstOrDefault((DwellingModel item) => item.LocationX == x && item.LocationY == y && item.LocationZ == z));

					if (TabPage.CurrentIndex == 4)

					{

						ScrollDwelling();

					}

					else

					{

						TabPage.CurrentIndex = 4;

					}

				}

				else

				{

					flag = true;

				}

				if (_sandbable.DimensionDoor && flag && _hero.CheckingModel != null)

				{

					if (_hero.CheckingModel.LocationZ == 0)

					{

						var drawingVisual2 = OnGround.Children.Cast<DrawingVisual>().FirstOrDefault(delegate(DrawingVisual item)

						{

							Rect contentBounds2 = item.ContentBounds;

							if (Math.Abs(contentBounds2.X) == (double)(_hero.CheckingModel.LocationX * host.CellSize))

							{

								contentBounds2 = item.ContentBounds;

								return Math.Abs(contentBounds2.Y) == (double)(_hero.CheckingModel.LocationY * host.CellSize);

							}

							return false;

						});

						if (drawingVisual2 != null)

						{

							OnGround.Children.Remove(drawingVisual2);

						}

					}

					else

					{

						var drawingVisual3 = UnderGround.Children.Cast<DrawingVisual>().FirstOrDefault(delegate(DrawingVisual item)

						{

							Rect contentBounds2 = item.ContentBounds;

							if (Math.Abs(contentBounds2.X) == (double)(_hero.CheckingModel.LocationX * host.CellSize))

							{

								contentBounds2 = item.ContentBounds;

								return Math.Abs(contentBounds2.Y) == (double)(_hero.CheckingModel.LocationY * host.CellSize);

							}

							return false;

						});

						if (drawingVisual3 != null)

						{

							UnderGround.Children.Remove(drawingVisual3);

						}

					}

					_hero.CheckingModel.LocationX = (short)num;

					_hero.CheckingModel.LocationY = (short)num2;

					_hero.CheckingModel.LocationZ = (short)z;

					var visual = host.CreateHero(_hero.CheckingModel, highlight: false);

					host.Children.Add(visual);

				}

			}

		}

		goto IL_0469;

		IL_0469:

		_sandbable.DimensionDoor = false;

		return HitTestResultBehavior.Stop;

	}

