namespace HoMMsTrainer;

public partial class TrainerWindow : Window
{
	private const int expireTime = 90000;

	private readonly byte[] SCAN_PATTERN = new byte[8] { 0, 1, 2, 3, 4, 5, 6, 7 };

	private readonly TaskStateMachine stateMachine;

	private readonly Hero heroUI;

	private readonly Intro introUI;

	private readonly Town townUI;

	private readonly Scanner scanner;

	private readonly MapViewModel map;

	private readonly PlayerViewModel player;

	private readonly HeroViewModel hero;

	private readonly CommanderViewModel commander;

	private readonly FollowerViewModel follower;

	private readonly HeroTroopViewModel troop;

	private readonly TownViewModel town;

	private readonly MineViewModel mine;

	private readonly DwellingViewModel dwelling;

	private readonly SandTableViewModel sandTable;

	private readonly CreatureViewModel creature;

	private readonly FeatsViewModel feats;

	private readonly GlobalViewModel global;

	private readonly SecondaryViewModel secondary;

	public bool IsSandTableOpened { get; private set; }

	public TrainerWindow()
	{
		InitializeComponent();
		stateMachine = new TaskStateMachine();
		scanner = new Scanner();
		map = new MapViewModel();
		map.ReceiveMessageOn();
		player = new PlayerViewModel();
		player.ReceiveMessageOn();
		hero = new HeroViewModel();
		hero.ReceiveMessageOn();
		town = new TownViewModel();
		town.ReceiveMessageOn();
		commander = new CommanderViewModel();
		commander.ReceiveMessageOn();
		follower = new FollowerViewModel();
		follower.ReceiveMessageOn();
		troop = new HeroTroopViewModel();
		troop.ReceiveMessageOn();
		sandTable = new SandTableViewModel();
		sandTable.ReceiveMessageOn();
		creature = new CreatureViewModel();
		creature.ReceiveMessageOn();
		feats = new FeatsViewModel();
		feats.ReceiveMessageOn();
		global = new GlobalViewModel();
		global.ReceiveMessageOn();
		secondary = new SecondaryViewModel();
		secondary.ReceiveMessageOn();
		mine = new MineViewModel();
		mine.ReceiveMessageOn();
		dwelling = new DwellingViewModel();
		dwelling.ReceiveMessageOn();
		MapView.DataContext = map;
		PlayerView.DataContext = player;
		TavernView.DataContext = player;
		HeroView.DataContext = hero;
		TownView.DataContext = town;
		ResourceView.DataContext = player;
		introUI = new Intro();
		heroUI = new Hero(hero, commander, follower, troop);
		townUI = new Town(town);
		Detail.Navigate(introUI);
	}

	private int ScanWorking()
	{
		int result = 0;
		((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
		{
			if (Environment.Is64BitOperatingSystem)
			{
				result = scanner.DoWork64("Heroes", SCAN_PATTERN, CheckAddress);
			}
			else
			{
				result = scanner.DoWork32("Heroes", SCAN_PATTERN, CheckAddress);
			}
		});
		return result;
	}

	private void ScanComplete(int result)
	{
		((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
		{
			TaskProgress.Send(result switch
			{
				801 => "没有检测到游戏运行，请运行英雄无敌3系列游戏后重试。", 
				802 => "游戏已退出，请运行英雄无敌3系列游戏后重试。", 
				803 => "未搜索到游戏数据内存地址，修改器功能无法使用。", 
				1000 => "检索游戏及内存数据成功...准备数据", 
				_ => "非预期信息", 
			});
			Scan.IsEnabled = true;
			if (result == 1000)
			{
				Rule.IsEnabled = true;
				Save.IsEnabled = true;
				Sand.IsEnabled = true;
				map.CheckCommand.Execute(map.Models[0]);
				player.CheckCommand.Execute(player.Models.FirstOrDefault((PlayerModel item) => (int)item.Sort < 10));
				if ((Detail.Content is Intro || Detail.Content is Hero) && hero.Heroes.Count > 0)
				{
					hero.CheckCommand.Execute(hero.Heroes.ElementAtOrDefault(0));
					commander.CheckCommand.Execute(commander.Models.FirstOrDefault((CommanderModel item) => item.Hero == hero.CheckingModel?.ID));
					follower.CheckCommand.Execute(follower.Models.FirstOrDefault((FollowerModel item) => item.Hero == hero.CheckingModel?.ID));
					troop.CheckCommand.Execute(troop.Models.FirstOrDefault((HeroTroopModel item) => item.Index == hero.CheckingModel?.ID));
					Detail.Navigate(heroUI);
				}
				else if (Detail.Content is Town && town.Towns.Count > 0)
				{
					town.CheckCommand.Execute(town.Towns.ElementAtOrDefault(0));
					townUI.RefreshStructure();
					Detail.Navigate(townUI);
				}
			}
			else
			{
				Rule.IsEnabled = false;
				Save.IsEnabled = false;
				Sand.IsEnabled = false;
				Detail.Navigate(introUI);
			}
		});
	}

	private void ScanCancel()
	{
		((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
		{
			TaskProgress.Send("执行超时，请重试");
			Scan.IsEnabled = true;
		});
	}

	private void ScanError(Exception ex)
	{
		((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
		{
			TaskProgress.Send("发生异常：" + ex.Message);
		});
	}

	private bool CheckAddress(int address)
	{
		byte[] array = new byte[2880];
		if (scanner.Game.ReadProcessMemory(address + 5168, array) && (SCAN_PATTERN[0] ^ array[0]) + (SCAN_PATTERN[1] ^ array[360]) + (SCAN_PATTERN[2] ^ array[720]) + (SCAN_PATTERN[3] ^ array[1080]) + (SCAN_PATTERN[4] ^ array[1440]) + (SCAN_PATTERN[5] ^ array[1800]) + (SCAN_PATTERN[6] ^ array[2160]) + (SCAN_PATTERN[7] ^ array[2520]) == 0)
		{
			return true;
		}
		return false;
	}

	private void SaveWorking()
	{
		map.Save();
		player.Save();
		hero.Save();
		commander.Save();
		follower.Save();
		troop.Save();
		town.Save();
		mine.Save();
		dwelling.Save();
	}

	private void SaveComplete()
	{
		((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
		{
			TaskProgress.Send("保存数据完成");
		});
	}

	private async void Scan_Click(object sender, RoutedEventArgs e)
	{
		Scan.IsEnabled = false;
		if (stateMachine.Reset())
		{
			await stateMachine.Start(90000, ScanWorking, ScanComplete, ScanCancel, ScanError);
		}
		((CollectionViewSource)base.Resources["Tavern1"]).View.Refresh();
		((CollectionViewSource)base.Resources["Tavern2"]).View.Refresh();
	}

	private void Rule_Click(object sender, RoutedEventArgs e)
	{
		RuleSetting ruleSetting = new RuleSetting(global, creature, secondary, feats);
		ruleSetting.Show();
		WindowExtension.SetToCenter(this, ruleSetting);
	}

	private async void Save_Click(object sender, RoutedEventArgs e)
	{
		if (stateMachine.Reset())
		{
			await stateMachine.Start(90000, SaveWorking, SaveComplete);
		}
	}

	private void Hero_Click(object sender, RoutedEventArgs e)
	{
		var checkingModel = town.CheckingModel;
		if (checkingModel != null)
		{
			checkingModel.Checked = false;
		}
		town.CheckCommand.Execute(null);
		if (sender is Button { DataContext: HeroModel dataContext } && hero.CheckingModel != dataContext)
		{
			hero.CheckCommand.Execute(dataContext);
			commander.CheckCommand.Execute(commander.Models.FirstOrDefault((CommanderModel item) => item.Hero == hero.CheckingModel?.ID));
			follower.CheckCommand.Execute(follower.Models.FirstOrDefault((FollowerModel item) => item.Hero == hero.CheckingModel?.ID));
			troop.CheckCommand.Execute(troop.Models.FirstOrDefault((HeroTroopModel item) => item.Index == hero.CheckingModel?.ID));
		}
		Detail.Navigate(heroUI);
	}

	private void Town_Click(object sender, RoutedEventArgs e)
	{
		var checkingModel = hero.CheckingModel;
		if (checkingModel != null)
		{
			var checkingModel2 = commander.CheckingModel;
			if (checkingModel2 != null)
			{
				var checkingModel3 = follower.CheckingModel;
				if (checkingModel3 != null)
				{
					var checkingModel4 = troop.CheckingModel;
					if (checkingModel4 != null)
					{
						checkingModel.Checked = false;
						checkingModel2.Checked = false;
						checkingModel3.Checked = false;
						checkingModel4.Checked = false;
					}
				}
			}
		}
		hero.CheckCommand.Execute(null);
		commander.CheckCommand.Execute(null);
		follower.CheckCommand.Execute(null);
		troop.CheckCommand.Execute(null);
		if (sender is Button { DataContext: TownModel dataContext } && town.CheckingModel != dataContext)
		{
			town.CheckCommand.Execute(dataContext);
		}
		Detail.Navigate(townUI);
	}

	private void Player_Click(object sender, RoutedEventArgs e)
	{
		if (!(sender is Button { DataContext: var dataContext }))
		{
			return;
		}
		var gamer = dataContext as PlayerModel;
		if (gamer == null)
		{
			return;
		}
		if (Detail.Content is Town)
		{
			town.CheckCommand.Execute(town.Models.FirstOrDefault((TownModel item) => item.Flag == gamer.Flag));
			return;
		}
		hero.CheckCommand.Execute(hero.Models.FirstOrDefault((HeroModel item) => item.Flag == gamer.Flag));
		commander.CheckCommand.Execute(commander.Models.FirstOrDefault((CommanderModel item) => item.Hero == hero.CheckingModel?.ID));
		follower.CheckCommand.Execute(follower.Models.FirstOrDefault((FollowerModel item) => item.Hero == hero.CheckingModel?.ID));
		troop.CheckCommand.Execute(troop.Models.FirstOrDefault((HeroTroopModel item) => item.Index == hero.CheckingModel?.ID));
	}

	private void SandTable_Click(object sender, RoutedEventArgs e)
	{
		if (this.sandTable != null && !IsSandTableOpened)
		{
			SandTable sandTable = new SandTable(this.sandTable, player, hero, town, mine, dwelling);
			IsSandTableOpened = true;
			sandTable.Closed += delegate
			{
				IsSandTableOpened = false;
			};
			WindowExtension.SetToCenter(this, sandTable);
			sandTable.Show();
		}
	}

	private void Tavern_Filter(object sender, FilterEventArgs e)
	{
		if (e.Item is HeroModel heroModel)
		{
			e.Accepted = heroModel.Flag == PlayerFlag.Gray;
		}
	}

	private void Window_Activated(object sender, EventArgs e)
	{
		if (AutoLoad.IsChecked == true && Save.IsEnabled)
		{
			Scan.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));
		}
	}
}

﻿using System;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Threading;

namespace HoMMsTrainer;

public partial class App : Application
{
	protected override void OnStartup(StartupEventArgs e)
	{
		base.OnStartup(e);
		Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);
		base.DispatcherUnhandledException += App_DispatcherUnhandledException;
		TaskScheduler.UnobservedTaskException += delegate(object? sender, UnobservedTaskExceptionEventArgs e2)
		{
			LogExceptionToFile(e2.Exception);
			e2.SetObserved();
		};

		try
		{
			MainWindow = new TrainerWindow();
			MainWindow.Show();
		}
		catch (Exception ex)
		{
			LogExceptionToFile(ex);
			MessageBox.Show("启动窗口失败: " + ex.Message + "\n\n" + ex.StackTrace, "错误", MessageBoxButton.OK, MessageBoxImage.Error);
			Shutdown(1);
		}
	}

	private void App_DispatcherUnhandledException(object sender, DispatcherUnhandledExceptionEventArgs e)
	{
		LogExceptionToFile(e.Exception);
		MessageBox.Show("发生了一个非预期的错误，程序将关闭，详细错误信息请查阅Error日志。", "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
		e.Handled = true;
		Shutdown();
	}

	private static void LogExceptionToFile(Exception ex)
	{
		try
		{
			string text = Path.Combine(Environment.CurrentDirectory, "Error");
			if (!Directory.Exists(text))
			{
				Directory.CreateDirectory(text);
			}
			using StreamWriter streamWriter = new StreamWriter(Path.Combine(text, $"Error_{DateTime.Now:yyyyMMdd_HHmmss}.log"), append: true);
			streamWriter.WriteLine($"Time: {DateTime.Now}");
			streamWriter.WriteLine("Message: " + ex.Message);
			streamWriter.WriteLine("StackTrace: " + ex.StackTrace);
			if (ex.InnerException != null)
			{
				streamWriter.WriteLine("Inner Exception:");
				LogExceptionToFile(ex.InnerException);
			}
		}
		catch (Exception ex2)
		{
			Console.WriteLine("Failed to log exception: " + ex2.Message);
		}
	}
}

