using System;
using System.CodeDom.Compiler;
using System.ComponentModel;
using System.Diagnostics;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Data;
using System.Windows.Input;
using System.Windows.Markup;
using System.Windows.Media;
using HoMM3.Standard;
using HoMMsTrainer.Host;
using Panuon.WPF;
using Panuon.WPF.UI;

namespace HoMMsTrainer.Pop;

/// <summary>
/// 沙盘（地图查看器）弹窗，用于可视化显示地图网格、英雄位置、城镇位置、矿区归属和住宅信息。
/// 支持缩略图导航、地上/地下层切换、英雄传送（DimensionDoor）和视野范围显示。
/// </summary>
public partial class SandTable : Window
{
	private readonly SandTableViewModel _sandbable;
	private readonly PlayerViewModel _player;
	private readonly HeroViewModel _hero;
	private readonly TownViewModel _town;
	private readonly MineViewModel _mine;
	private readonly DwellingViewModel _dwelling;

	public SandTable(SandTableViewModel sandtable, PlayerViewModel player, HeroViewModel hero, TownViewModel town, MineViewModel mine, DwellingViewModel dwelling)
	{
		InitializeComponent();

		_sandbable = sandtable;
		// 沙盘加载时默认选中第一张地图（地图选择器中）
		_sandbable.CheckCommand.Execute(_sandbable.Models.FirstOrDefault());

		_player = player;
		_hero = hero;
		_town = town;
		_mine = mine;
		_dwelling = dwelling;

		// 将各 ViewModel 绑定到对应的 DataContext，使 UI 自动刷新
		MapMain.DataContext = _sandbable;
		MapThumb.DataContext = _sandbable;
		MapLegend.DataContext = _sandbable;
		AreaView.DataContext = _sandbable;
		MapFunc.DataContext = _player;
		HeroView.DataContext = _hero;
		TownView.DataContext = _town;
		MineView.DataContext = _mine;
		DwellingView.DataContext = _dwelling;

		// 只有双层地图（地上+地下）才允许切换视图按钮
		ViewGround.IsEnabled = sandtable.DoubleLayer;
		ViewUnderGround.IsEnabled = sandtable.DoubleLayer;
	}

	private void Window_MouseRightButtonUp(object sender, MouseButtonEventArgs e)
	{
		// 右键抬起，暂未使用（可扩展为取消选中等操作）
	}

	private void Grid_PreviewMouseWheel(object sender, MouseWheelEventArgs e)
	{
		// 抑制鼠标滚轮在缩略图画布上的默认滚动行为（防止意外触发页面滚动）
		e.Handled = true;
	}

	/// <summary>
	/// 缩略图画布拖拽事件。通过拖拽缩略图上的红色方框，同步滚动主视图。
	/// </summary>
	private void MapThumbArea_DragDelta(object sender, DragDeltaEventArgs e)
	{
		if (sender is Thumb thumb)
		{
			// 计算拖拽后方框左上角的新位置，并夹取在 [0, 缩略图尺寸 - 方框尺寸] 范围内
			double num = Canvas.GetLeft(thumb) + e.HorizontalChange;
			double num2 = Canvas.GetTop(thumb) + e.VerticalChange;
			double num3 = 252.0 - thumb.Width;  // 水平可拖动范围
			double num4 = 252.0 - thumb.Height; // 垂直可拖动范围

			if (num < 0.0)
				num = 0.0;
			else if (num > num3)
				num = num3;

			if (num2 < 0.0)
				num2 = 0.0;
			else if (num2 > num4)
				num2 = num4;

			Canvas.SetLeft(thumb, num);
			Canvas.SetTop(thumb, num2);

			// 根据拖动量与地图缩放比例，同步滚动主视图
			MapView.ScrollToHorizontalOffset(MapView.HorizontalOffset + e.HorizontalChange * _sandbable.MapScale);
			MapView.ScrollToVerticalOffset(MapView.ScrollVerticalOffset + e.VerticalChange * _sandbable.MapScale);
		}
	}

	/// <summary>
	/// 切换到地上层视图：隐藏地上按钮，显示地下按钮，切换地上/地下层地图层的可见性。
	/// </summary>
	private void ViewGround_Click(object sender, RoutedEventArgs e)
	{
		ViewGround.Visibility = Visibility.Collapsed;
		UnderGround.Visibility = Visibility.Collapsed;
		UnderGroundThumb.Visibility = Visibility.Collapsed;
		ViewUnderGround.Visibility = Visibility.Visible;
		OnGround.Visibility = Visibility.Visible;
		OnGroundThumb.Visibility = Visibility.Visible;
	}

	/// <summary>
	/// 切换到地下层视图：隐藏地下按钮，显示地上按钮，切换地上/地下层地图层的可见性。
	/// </summary>
	private void ViewUnderGround_Click(object sender, RoutedEventArgs e)
	{
		ViewUnderGround.Visibility = Visibility.Collapsed;
		OnGround.Visibility = Visibility.Collapsed;
		OnGroundThumb.Visibility = Visibility.Collapsed;
		ViewGround.Visibility = Visibility.Visible;
		UnderGround.Visibility = Visibility.Visible;
		UnderGroundThumb.Visibility = Visibility.Visible;
	}

	/// <summary>
	/// 点击圣杯按钮：将视图切换到圣杯所在层，并将缩略图定位到圣杯坐标。
	/// </summary>
	private void Grail_Click(object sender, RoutedEventArgs e)
	{
		var checkingMap = _sandbable.CheckingMap;
		if (checkingMap != null && checkingMap.GrailZ > -1)
		{
			// 根据圣杯 Z 坐标（0=地上，1=地下）触发对应层的切换按钮
			if (checkingMap.GrailZ == 0)
				ViewGround.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));
			else
				ViewUnderGround.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));

			// 将缩略图方框中心对齐到圣杯位置
			SetMapView(new Point((double)checkingMap.GrailX * _sandbable.ThumbCellSize, (double)checkingMap.GrailY * _sandbable.ThumbCellSize));
		}
	}

	/// <summary>
	/// 将缩略图方框中心对准指定世界坐标点，同时同步主视图的滚动位置。
	/// </summary>
	/// <param name="p">目标点在缩略图坐标系中的位置。</param>
	private void SetMapView(Point p)
	{
		// 缩略图方框的半宽半高，用于计算中心偏移
		double num = MapThumbArea.Width / 2.0;
		double num2 = MapThumbArea.Height / 2.0;
		// 缩略图方框可移动的范围边界（考虑方框本身尺寸）
		double num3 = MapThumb.Width - num;
		double num4 = MapThumb.Height - num2;

		// 计算方框左上角位置：如果目标点靠左/上则取0，靠右/下则取边界值，否则居中对齐
		double num5 = (p.X < num) ? 0.0 : ((!(p.X > num3)) ? (p.X - MapThumbArea.Width / 2.0) : (num3 - num));
		double num6 = (p.Y < num2) ? 0.0 : ((!(p.Y > num4)) ? (p.Y - MapThumbArea.Height / 2.0) : (num4 - num2));

		Canvas.SetLeft(MapThumbArea, num5);
		Canvas.SetTop(MapThumbArea, num6);
		MapView.ScrollToHorizontalOffset(num5 * _sandbable.MapScale);
		MapView.ScrollToVerticalOffset(num6 * _sandbable.MapScale);
	}

