	/// <summary>
	/// 页面首次加载时：自动选中地图上的第一个英雄、城镇、矿区、住宅，以及第一个英雄在沙盘上的位置。
	/// </summary>
	private void TabPage_Loaded(object sender, RoutedEventArgs e)
	{
		// 依次自动选中各列表的第一项
		if (Heroes.Items.Count > 0)
			_hero.CheckCommand.Execute(_hero.HeroesOnMap.ElementAtOrDefault(0));
		if (Towns.Items.Count > 0)
			_town.CheckCommand.Execute(_town.Models.ElementAtOrDefault(0));
		if (Mines.Items.Count > 0)
