	/// <summary>
	/// 在主地图上左键单击：执行命中测试，识别点击的是哪种地图元素并执行相应操作。
	/// </summary>
	private void Map_MouseLeftButtonDown(object sender, MouseButtonEventArgs e)
	{
		if (sender is MapVisualHost reference)
		{
			Point position = e.GetPosition((UIElement)sender);
			// 使用 WPF HitTest 找到被点击的 DrawingVisual
			VisualTreeHelper.HitTest(reference, null, DoHitTest, new PointHitTestParameters(position));
		}
	}

	/// <summary>
	/// 命中测试回调：判断被点击元素的尺寸（宽高格数），识别出英雄（1×1）、城镇（5×3）、矿区（3×2）、住宅（2×2），
	/// 触发对应选中操作。如果开启了英雄传送（DimensionDoor），则将英雄移动到点击位置。
	/// </summary>
	private HitTestResultBehavior DoHitTest(HitTestResult result)
	{
		if (result is PointHitTestResult pointHitTestResult && result.VisualHit is DrawingVisual { Parent: var parent } drawingVisual)
		{
			var host = parent as MapVisualHost;

			if (host != null)
			{
				bool flag = false; // 是否点击了空白区域（无地图元素）

				// 将点击的像素坐标转换为地图格坐标（基于主视图格子大小）
				Point pointHit = pointHitTestResult.PointHit;
				int num = (int)Math.Floor(pointHit.X / (double)host.CellSize);
				pointHit = pointHitTestResult.PointHit;
				int num2 = (int)Math.Floor(pointHit.Y / (double)host.CellSize);

				// 根据当前渲染层确定 Z 坐标：OnGround 层 Z=0，UnderGround 层 Z=1
				int z = (!(host.Name == "OnGround")) ? 1 : 0;

				// 从被点击 DrawingVisual 的内容边界计算其地图尺寸（用于判断元素类型）
				Rect contentBounds = drawingVisual.ContentBounds;
				int num3 = (int)Math.Floor(contentBounds.Width / (double)host.CellSize); // 宽度格数
				contentBounds = drawingVisual.ContentBounds;
				int num4 = (int)Math.Floor(contentBounds.Height / (double)host.CellSize); // 高度格数

				// 计算元素的地图坐标中心点
				contentBounds = drawingVisual.ContentBounds;
				int x = (int)Math.Round(contentBounds.X / (double)host.CellSize) + (num3 - 1) / 2;
				contentBounds = drawingVisual.ContentBounds;
				int y = (int)Math.Round(contentBounds.Y / (double)host.CellSize) + num4 - 1;

				// 视野范围模式：点击空白格时以选中英雄为中心显示视野范围
				if (_sandbable.ViewArea)
				{
					SandTableModel? checkingModel = _sandbable.CheckingModel;
					if (checkingModel != null && checkingModel.ViewEnabled)
					{
						_sandbable.ViewArea = false;
						_sandbable.OpenArea(num, num2, z, (byte)Player.SelectedValue, (int)Radius.Value);
						goto IL_0469;
					}
				}

				// 根据尺寸判断元素类型：
				// 1×1 → 英雄
				if (num3 == 1 && num4 == 1)
				{
					var heroModel = _hero.Models.FirstOrDefault((HeroModel item) => item.LocationX == x && item.LocationY == y && item.LocationZ == z);
					if (heroModel != null)
					{
						_hero.CheckCommand.Execute(heroModel);
						if (TabPage.CurrentIndex == 1)
							ScrollHero();
						else
							TabPage.CurrentIndex = 1;
					}
					else
						flag = true;
				}
				// 5×3 → 城镇（城镇占用5格宽、3格高）
				else if (num3 == 5 && num4 == 3)
				{
					_town.CheckCommand.Execute(_town.Models.FirstOrDefault((TownModel item) => item.LocationX == x && item.LocationY == y && item.LocationZ == z));
					if (TabPage.CurrentIndex == 2)
						ScrollTown();
					else
						TabPage.CurrentIndex = 2;
				}
				// 3×2 → 矿区
				else if (num3 == 3 && num4 == 2)
				{
					_mine.CheckCommand.Execute(_mine.Models.FirstOrDefault((MineModel item) => item.LocationX == x && item.LocationY == y && item.LocationZ == z));
					if (TabPage.CurrentIndex == 3)
						ScrollMine();
					else
						TabPage.CurrentIndex = 3;
				}
				// 2×2 → 住宅
				else if (num3 == 2 && num4 == 2)
				{
					_dwelling.CheckCommand.Execute(_dwelling.Models.FirstOrDefault((DwellingModel item) => item.LocationX == x && item.LocationY == y && item.LocationZ == z));
					if (TabPage.CurrentIndex == 4)
						ScrollDwelling();
					else
						TabPage.CurrentIndex = 4;
				}
				else
					flag = true;

				// 英雄传送模式：点击空白格时，将当前英雄移动到该格
				if (_sandbable.DimensionDoor && flag && _hero.CheckingModel != null)
				{
					// 从当前层地图上移除英雄的旧图标
					if (_hero.CheckingModel.LocationZ == 0)
					{
						var drawingVisual2 = OnGround.Children.Cast<DrawingVisual>().FirstOrDefault(delegate (DrawingVisual item)
						{
							Rect contentBounds2 = item.ContentBounds;
							if (Math.Abs(contentBounds2.X) == (double)(_hero.CheckingModel.LocationX * host.CellSize))
							{
								contentBounds2 = item.ContentBounds;
								return Math.Abs(contentBounds2.Y) == (double)(_hero.CheckingModel.LocationY * host.CellSize);
							}
							return false;
						});
						if (drawingVisual2 != null)
							OnGround.Children.Remove(drawingVisual2);
					}
					else
					{
						var drawingVisual3 = UnderGround.Children.Cast<DrawingVisual>().FirstOrDefault(delegate (DrawingVisual item)
						{
							Rect contentBounds2 = item.ContentBounds;
							if (Math.Abs(contentBounds2.X) == (double)(_hero.CheckingModel.LocationX * host.CellSize))
							{
								contentBounds2 = item.ContentBounds;
								return Math.Abs(contentBounds2.Y) == (double)(_hero.CheckingModel.LocationY * host.CellSize);
							}
							return false;
						});
						if (drawingVisual3 != null)
							UnderGround.Children.Remove(drawingVisual3);
					}

					// 更新英雄坐标数据
					_hero.CheckingModel.LocationX = (short)num;
					_hero.CheckingModel.LocationY = (short)num2;
					_hero.CheckingModel.LocationZ = (short)z;

					// 在新位置重新绘制英雄图标
					var visual = host.CreateHero(_hero.CheckingModel, highlight: false);
					host.Children.Add(visual);
				}
			}
		}

		IL_0469:
		// 每次命中测试后重置传送模式标志
		_sandbable.DimensionDoor = false;
		return HitTestResultBehavior.Stop;
	}

	/// <summary>
	/// 将侧边英雄列表滚动到当前选中英雄位置，使其始终可见。
	/// </summary>
	private void ScrollHero()
	{
		int num = Heroes.Items.IndexOf(_hero.CheckingModel);
		if (num > -1)
		{
			object itemAt = Heroes.Items.GetItemAt(num);
			Heroes.ScrollIntoView(itemAt);
		}
	}

	/// <summary>
	/// 将侧边城镇列表滚动到当前选中城镇位置，使其始终可见。
	/// </summary>
	private void ScrollTown()
	{
		int num = Towns.Items.IndexOf(_town.CheckingModel);
		if (num > -1)
		{
			object itemAt = Towns.Items.GetItemAt(num);
			Towns.ScrollIntoView(itemAt);
		}
	}

	/// <summary>
	/// 将侧边矿区列表滚动到当前选中矿区位置，使其始终可见。
	/// </summary>
	private void ScrollMine()
	{
		int num = Mines.Items.IndexOf(_mine.CheckingModel);
		if (num > -1)
		{
			object itemAt = Mines.Items.GetItemAt(num);
			Mines.ScrollIntoView(itemAt);
		}
	}

	/// <summary>
	/// 将侧边住宅列表滚动到当前选中住宅位置，使其始终可见。
	/// </summary>
	private void ScrollDwelling()
	{
		int num = Dwellings.Items.IndexOf(_dwelling.CheckingModel);
		if (num > -1)
		{
			object itemAt = Dwellings.Items.GetItemAt(num);
			Dwellings.ScrollIntoView(itemAt);
		}
	}

	/// <summary>
	/// 英雄传送按钮：切换 DimensionDoor 模式。开启后，在地图空白处左键单击可将当前英雄传送到该位置。
	/// </summary>
	private void DimensionDoor_Click(object sender, RoutedEventArgs e)
	{
		_sandbable.DimensionDoor = !_sandbable.DimensionDoor;
	}

	/// <summary>
	/// 矿区列表过滤器：只显示资源类矿区（锯木场到金矿），排除树脂/金矿石等非资源矿区。
	/// </summary>
	private void MinesOnMap_Filter(object sender, FilterEventArgs e)
	{
		if (e.Item is MineModel mineModel)
			e.Accepted = mineModel.Sort >= MineSort.Sawmill && mineModel.Sort <= MineSort.GoldMine;
	}

	/// <summary>
	/// 视野范围按钮：切换 ViewArea 模式，开启后在地图空白处单击可以当前玩家视角显示视野范围。
	/// </summary>
	private void View_Click(object sender, RoutedEventArgs e)
	{
		_sandbable.ViewArea = !_sandbable.ViewArea;
	}

	/// <summary>
	/// 玩家选择变更后：如果当前选中的是"无"（索引0），强制切换到第一个真实玩家（索引1），
	/// 防止按无玩家筛选导致地图空白。
	/// </summary>
	private void Player_SelectionChanged(object sender, SelectionChangedEventArgs e)
	{
		if (Player.SelectedIndex == 0)
			Player.SelectedIndex = 1;
	}
}

