using System;
using System.Collections;
using System.Globalization;
using System.Linq;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Effects;
using HoMM3.BaseObj;
using HoMM3.Setting;
using HoMM3.Standard;

namespace HoMMsTrainer.Host;

/// <summary>
/// 地图可视化宿主（WPF 自定义 FrameworkElement），负责绘制沙盘地图网格、英雄、城镇、矿区、住宅和圣杯位置。
/// 支持主视图（大格）和缩略图（小格）两种渲染模式。
/// </summary>
public class MapVisualHost : FrameworkElement
{
	// ===== Dependency Properties =====

	/// <summary>是否为地下层视图（影响英雄筛选的 Z 坐标判断）。</summary>
	public static readonly DependencyProperty IsUndergroundProperty = DependencyProperty.Register("IsUnderground", typeof(bool), typeof(MapVisualHost), new PropertyMetadata(new PropertyChangedCallback(OnViewUndergroundChanged)));

	/// <summary>是否为主视图（true=主视图使用 CellSize 大格，false=缩略图使用 ThumbCellSize 小格）。</summary>
	public static readonly DependencyProperty IsMainProperty = DependencyProperty.Register("IsMain", typeof(bool), typeof(MapVisualHost), new PropertyMetadata(new PropertyChangedCallback(OnIsMainChanged)));

	/// <summary>地图尺寸（Small/Medium/Large/ExtraLarge），决定网格行/列格数。</summary>
	public static readonly DependencyProperty SizeProperty = DependencyProperty.Register("Size", typeof(MapSize), typeof(MapVisualHost), new PropertyMetadata(new PropertyChangedCallback(OnSizeChanged)));

	/// <summary>主视图单格像素大小（默认32），用于计算 DrawingVisual 位置和尺寸。</summary>
	public static readonly DependencyProperty CellSizeProperty = DependencyProperty.Register("CellSize", typeof(int), typeof(MapVisualHost), new PropertyMetadata((object)32, new PropertyChangedCallback(OnCellSizeChanged)));

	/// <summary>缩略图单格像素大小（通常远小于 CellSize），用于计算缩略图 DrawingVisual 位置。</summary>
	public static readonly DependencyProperty ThumbCellSizeProperty = DependencyProperty.Register("ThumbCellSize", typeof(double), typeof(MapVisualHost), new PropertyMetadata(new PropertyChangedCallback(OnThumbCellSizeChanged)));

	/// <summary>地图上所有英雄的集合，用于在对应层绘制英雄图标。</summary>
	public static readonly DependencyProperty HeroesProperty = DependencyProperty.Register("Heroes", typeof(IEnumerable), typeof(MapVisualHost), new PropertyMetadata(new PropertyChangedCallback(OnHeroesChanged)));

	/// <summary>地图上所有城镇的集合，用于在对应层绘制城镇色块。</summary>
	public static readonly DependencyProperty TownsProperty = DependencyProperty.Register("Towns", typeof(IEnumerable), typeof(MapVisualHost), new PropertyMetadata(new PropertyChangedCallback(OnTownsChanged)));

	/// <summary>地图上所有矿区的集合，用于在对应层绘制矿区色块。</summary>
	public static readonly DependencyProperty MinesProperty = DependencyProperty.Register("Mines", typeof(IEnumerable), typeof(MapVisualHost), new PropertyMetadata(new PropertyChangedCallback(OnMinesChanged)));

	/// <summary>地图上所有住宅的集合，用于在对应层绘制住宅色块。</summary>
	public static readonly DependencyProperty DwellingsProperty = DependencyProperty.Register("Dwellings", typeof(IEnumerable), typeof(MapVisualHost), new PropertyMetadata(new PropertyChangedCallback(OnDwellingsChanged)));

	/// <summary>地图整体数据（包含圣杯坐标等全局信息）。</summary>
	public static readonly DependencyProperty MapProperty = DependencyProperty.Register("Map", typeof(MapModel), typeof(MapVisualHost), new PropertyMetadata(new PropertyChangedCallback(OnMapChanged)));

	/// <summary>是否在地图上显示英雄图标。</summary>
	public static readonly DependencyProperty ShowHeroProperty = DependencyProperty.Register("ShowHero", typeof(bool), typeof(MapVisualHost), new PropertyMetadata((object)true, new PropertyChangedCallback(OnShowHeroChanged)));

	/// <summary>是否在地图上显示城镇色块。</summary>
	public static readonly DependencyProperty ShowTownProperty = DependencyProperty.Register("ShowTown", typeof(bool), typeof(MapVisualHost), new PropertyMetadata((object)true, new PropertyChangedCallback(OnShowTownChanged)));

	/// <summary>是否在地图上显示矿区色块。</summary>
	public static readonly DependencyProperty ShowMineProperty = DependencyProperty.Register("ShowMine", typeof(bool), typeof(MapVisualHost), new PropertyMetadata((object)true, new PropertyChangedCallback(OnShowMineChanged)));

	/// <summary>是否在地图上显示住宅色块。</summary>
	public static readonly DependencyProperty ShowDwellingProperty = DependencyProperty.Register("ShowDwelling", typeof(bool), typeof(MapVisualHost), new PropertyMetadata((object)true, new PropertyChangedCallback(OnShowDwellingChanged)));

	// ===== 内部 DrawingVisual 缓存 =====

	private readonly VisualCollection children;   // WPF 可视化树子元素集合
	private DrawingVisual? grid;                  // 网格背景 DrawingVisual
	private DrawingVisual? hero;                  // 英雄图标 DrawingVisual（仅缓存第一个，多英雄直接用 children）
	private DrawingVisual? town;                  // 城镇色块 DrawingVisual
	private DrawingVisual? mine;                  // 矿区色块 DrawingVisual
	private DrawingVisual? dwelling;              // 住宅色块 DrawingVisual
	private DrawingVisual? grail;                 // 圣杯 X 形标记 DrawingVisual

	// ===== CLR 属性包装器 =====

	public bool IsUnderground { get => (bool)((DependencyObject)this).GetValue(IsUndergroundProperty); set => ((DependencyObject)this).SetValue(IsUndergroundProperty, value); }
	public bool IsMain { get => (bool)((DependencyObject)this).GetValue(IsMainProperty); set => ((DependencyObject)this).SetValue(IsMainProperty, value); }
	public MapSize Size { get => (MapSize)((DependencyObject)this).GetValue(SizeProperty); set => ((DependencyObject)this).SetValue(SizeProperty, value); }
	public int CellSize { get => (int)((DependencyObject)this).GetValue(CellSizeProperty); set => ((DependencyObject)this).SetValue(CellSizeProperty, value); }
	public double ThumbCellSize { get => (double)((DependencyObject)this).GetValue(ThumbCellSizeProperty); set => ((DependencyObject)this).SetValue(ThumbCellSizeProperty, value); }
	public IEnumerable Heroes { get => (IEnumerable)((DependencyObject)this).GetValue(HeroesProperty); set => ((DependencyObject)this).SetValue(HeroesProperty, value); }
	public IEnumerable Towns { get => (IEnumerable)((DependencyObject)this).GetValue(TownsProperty); set => ((DependencyObject)this).SetValue(TownsProperty, value); }
	public IEnumerable Mines { get => (IEnumerable)((DependencyObject)this).GetValue(MinesProperty); set => ((DependencyObject)this).SetValue(MinesProperty, value); }
	public IEnumerable Dwellings { get => (IEnumerable)((DependencyObject)this).GetValue(DwellingsProperty); set => ((DependencyObject)this).SetValue(DwellingsProperty, value); }
	public MapModel Map { get => (MapModel)((DependencyObject)this).GetValue(MapProperty); set => ((DependencyObject)this).SetValue(MapProperty, value); }
	public bool ShowHero { get => (bool)((DependencyObject)this).GetValue(ShowHeroProperty); set => ((DependencyObject)this).SetValue(ShowHeroProperty, value); }
	public bool ShowTown { get => (bool)((DependencyObject)this).GetValue(ShowTownProperty); set => ((DependencyObject)this).SetValue(ShowTownProperty, value); }
	public bool ShowMine { get => (bool)((DependencyObject)this).GetValue(ShowMineProperty); set => ((DependencyObject)this).SetValue(ShowMineProperty, value); }
	public bool ShowDwelling { get => (bool)((DependencyObject)this).GetValue(ShowDwellingProperty); set => ((DependencyObject)this).SetValue(ShowDwellingProperty, value); }

	// ===== 内部属性（供 MapVisualHostExtensions 扩展方法使用） =====

	internal VisualCollection Children => children;
	internal DrawingVisual? Grid { get => grid; set => grid = value; }
	internal DrawingVisual? Hero { get => hero; set => hero = value; }
	internal DrawingVisual? Town { get => town; set => town = value; }
	internal DrawingVisual? Mine { get => mine; set => mine = value; }
	internal DrawingVisual? Dwelling { get => dwelling; set => dwelling = value; }
	internal DrawingVisual? Grail { get => grail; set => grail = value; }

	protected override int VisualChildrenCount => children.Count;

	public MapVisualHost()
	{
		children = new VisualCollection(this);
	}

	protected override Visual GetVisualChild(int index)
	{
		if (index < 0 || index >= children.Count)
			throw new ArgumentOutOfRangeException("index");
		return children[index];
	}

	// ===== DependencyProperty 变更回调 =====

	private static void OnViewUndergroundChanged(DependencyObject d, DependencyPropertyChangedEventArgs e) { }
	private static void OnIsMainChanged(DependencyObject d, DependencyPropertyChangedEventArgs e) { }

	/// <summary>地图尺寸变更时：清除旧网格并重绘新尺寸网格。</summary>
	private static void OnSizeChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
	{
		if (d is MapVisualHost host)
		{
			host.ClearGrid();
			host.FillGrid();
		}
	}

	private static void OnCellSizeChanged(DependencyObject d, DependencyPropertyChangedEventArgs e) { }
	private static void OnThumbCellSizeChanged(DependencyObject d, DependencyPropertyChangedEventArgs e) { }

	/// <summary>英雄列表变更时（且允许显示时）：重新填充英雄图标。</summary>
	private static void OnHeroesChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
	{
		if (d is MapVisualHost { ShowTown: not false } mapVisualHost)
			mapVisualHost.FillHero();
	}

	/// <summary>城镇列表变更时（且允许显示时）：重新填充城镇色块。</summary>
	private static void OnTownsChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
	{
		if (d is MapVisualHost { ShowTown: not false } mapVisualHost)
			mapVisualHost.FillTown();
	}

	/// <summary>矿区列表变更时（且允许显示时）：重新填充矿区色块。</summary>
	private static void OnMinesChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
	{
		if (d is MapVisualHost { ShowTown: not false } mapVisualHost)
			mapVisualHost.FillMine();
	}

	/// <summary>住宅列表变更时（且允许显示时）：重新填充住宅色块。</summary>
	private static void OnDwellingsChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
	{
		if (d is MapVisualHost { ShowTown: not false } mapVisualHost)
			mapVisualHost.FillDwelling();
	}

	/// <summary>地图数据变更时（圣杯坐标等）：重新绘制圣杯标记。</summary>
	private static void OnMapChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
	{
		if (d is MapVisualHost host)
			host.FillGrail();
	}

	/// <summary>英雄显示开关变更时：显示则填充，隐藏则清除。</summary>
	private static void OnShowHeroChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
	{
		if (d is MapVisualHost host)
		{
			if (e.NewValue.Equals(true))
				host.FillHero();
			else
				host.ClearHero();
		}
	}

	/// <summary>城镇显示开关变更时：显示则填充，隐藏则清除。</summary>
	private static void OnShowTownChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
	{
		if (d is MapVisualHost host)
		{
			if (e.NewValue.Equals(true))
				host.FillTown();
			else
				host.ClearTown();
		}
	}

	/// <summary>矿区显示开关变更时：显示则填充，隐藏则清除。</summary>
	private static void OnShowMineChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
	{
		if (d is MapVisualHost host)
		{
			if (e.NewValue.Equals(true))
				host.FillMine();
			else
				host.ClearMine();
		}
	}

	/// <summary>住宅显示开关变更时：显示则填充，隐藏则清除。</summary>
	private static void OnShowDwellingChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
	{
		if (d is MapVisualHost host)
		{
			if (e.NewValue.Equals(true))
				host.FillDwelling();
			else
				host.ClearDwelling();
		}
	}

	// ===== DrawingVisual 创建方法 =====

	/// <summary>
	/// 创建地图网格背景 DrawingVisual。
	/// 主视图（isThumb=false）会绘制浅灰色网格线；缩略图仅绘制透明背景框。
	/// </summary>
	/// <param name="isThumb">是否为缩略图模式（使用 ThumbCellSize 而非 CellSize，且不画网格线）。</param>
	internal DrawingVisual CreateGrid(bool isThumb)
	{
		byte size = (byte)Size;                              // 地图边长格数（S/M/L/XL 对应 36/72/108/144）
		double num = isThumb ? ThumbCellSize : (double)CellSize; // 当前模式单格像素大小

		DrawingVisual drawingVisual = new DrawingVisual();
		using DrawingContext drawingContext = drawingVisual.RenderOpen();

		// 绘制透明背景（设定 DrawingVisual 的内容尺寸边界）
		SolidColorBrush transparent = Brushes.Transparent;
		Rect rectangle = new Rect(0.0, 0.0, (double)(int)size * num, (double)(int)size * num);
		drawingContext.DrawRectangle(transparent, null, rectangle);

		// 仅主视图绘制网格线（缩略图不需要格线，保持简洁）
		if (!isThumb)
		{
			for (int i = 0; i <= size; i++)
			{
				// 水平线
				drawingContext.DrawLine(new Pen(Brushes.LightGray, 0.5), new Point(0.0, (double)i * num), new Point((double)(int)size * num, (double)i * num));
				// 垂直线
				drawingContext.DrawLine(new Pen(Brushes.LightGray, 0.5), new Point((double)i * num, 0.0), new Point((double)i * num, (double)(int)size * num));
			}
		}

		drawingContext.Close();
		return drawingVisual;
	}

	/// <summary>
	/// 创建英雄图标 DrawingVisual（带高亮发光效果）。
	/// 从资源字典查找对应玩家旗帜的图标（"VwSymH"+旗帜字节值），绘制到地图坐标位置。
	/// </summary>
	internal DrawingVisual? CreateHero(HeroModel hero, bool highlight)
	{
		if (FindResource("VwSymH" + (byte)hero.Flag) is ImageSource icon)
			return CreateMapSign(icon, hero.LocationX, hero.LocationY, highlight);
		return null;
	}

	/// <summary>
	/// 创建英雄图标 DrawingVisual（无高亮，用于缩略图）。
	/// </summary>
	internal DrawingVisual? CreateHero(HeroModel hero)
	{
		if (FindResource("VwSymH" + (byte)hero.Flag) is ImageSource icon)
			return CreateMapSign(icon, hero.LocationX, hero.LocationY);
		return null;
	}

	/// <summary>
	/// 创建城镇色块 DrawingVisual。城镇在地图上占用 5×3 格，以玩家旗帜颜色绘制三层叠加矩形：
	/// - 第3行（Y-2）：3格宽（顶部旗帜）
	/// - 第2行（Y-1）：5格宽（主体）
	/// - 第1行（Y）  ：5格宽（底部）
	/// 主视图模式下在顶部显示城镇所属阵营名称文字。
	/// </summary>
	/// <param name="town">城镇数据模型。</param>
	/// <param name="isThumb">是否为缩略图（缩略图不显示文字，节省空间）。</param>
	internal DrawingVisual? CreateTown(TownModel town, bool isThumb)
	{
		// 从资源字典查找玩家对应的纯色画刷（城镇底色）
		if (FindResource(town.Flag.ToString()) is SolidColorBrush brush)
		{
			double num = isThumb ? ThumbCellSize : (double)CellSize;

			DrawingVisual drawingVisual = new DrawingVisual();
			using DrawingContext drawingContext = drawingVisual.RenderOpen();

			// 计算城镇区域左上角（相对于 DrawingVisual 坐标系）
			double num2 = (double)(town.LocationX - 1) * num;   // 城镇区域左上 X
			double num3 = (double)(town.LocationY - 2) * num;   // 城镇区域左上 Y

			// 第一层：顶部旗帜（3格宽 × 1格高），位置偏左 1 格
			Pen pen = new Pen(brush, 1.0);
			Rect rectangle = default(Rect);
			rectangle.X = num2;
			rectangle.Y = num3;
			rectangle.Height = num;
			rectangle.Width = 3.0 * num;
			drawingContext.DrawRectangle(brush, pen, rectangle);

			// 第二层：中间行（5格宽 × 1格高），向左扩展 1 格
			Pen pen2 = new Pen(brush, 1.0);
			rectangle = default(Rect);
			rectangle.X = (double)(town.LocationX - 2) * num;
			rectangle.Y = (double)(town.LocationY - 1) * num;
			rectangle.Height = num;
			rectangle.Width = 5.0 * num;
			drawingContext.DrawRectangle(brush, pen2, rectangle);

			// 第三层：底部行（5格宽 × 1格高）
			Pen pen3 = new Pen(brush, 1.0);
			rectangle = default(Rect);
			rectangle.X = (double)(town.LocationX - 2) * num;
			rectangle.Y = (double)town.LocationY * num;
			rectangle.Height = num;
			rectangle.Width = 5.0 * num;
			drawingContext.DrawRectangle(brush, pen3, rectangle);

			// 主视图模式下显示阵营名称文字
			if (!isThumb)
			{
				FormattedText formattedText = CreateFormattedText(town.FactionName ?? "未知");
				drawingContext.DrawText(formattedText, new Point((3.0 * num - formattedText.Width) / 2.0 + num2, num3));
			}

			drawingContext.Close();
			return drawingVisual;
		}
		return null;
	}

	/// <summary>
	/// 创建矿区色块 DrawingVisual。矿区在地图上占用 3×2 格，
	/// 以所有者玩家旗帜颜色绘制矩形，主视图模式下显示矿区类型名称。
	/// </summary>
	/// <param name="mine">矿区数据模型。</param>
	/// <param name="isThumb">是否为缩略图（缩略图不显示文字）。</param>
	internal DrawingVisual? CreateMine(MineModel mine, bool isThumb)
	{
		if (FindResource(mine.Flag.ToString()) is SolidColorBrush brush)
		{
			double num = isThumb ? ThumbCellSize : (double)CellSize;

			DrawingVisual drawingVisual = new DrawingVisual();
			using DrawingContext drawingContext = drawingVisual.RenderOpen();

			// 计算矿区矩形区域（起点 X/Y 减 1 使其居中于格点）
			double num2 = (double)(mine.LocationX - 1) * num;
			double num3 = (double)(mine.LocationY - 1) * num;

			Pen pen = new Pen(brush, 1.0);
			Rect rectangle = default(Rect);
			rectangle.X = num2;
			rectangle.Y = num3;
			rectangle.Height = num * 2.0;
			rectangle.Width = 3.0 * num;
			drawingContext.DrawRectangle(brush, pen, rectangle);

			// 主视图显示矿区类型名（木头/矿石/水银/水晶/宝石/金矿）
			if (!isThumb)
			{
				string? text = null;
				if (SetRoe.EMineSort.TryGetValue(mine.Sort, out var value))
					text = value;
				if (text == null)
					text = "未知";

				FormattedText formattedText = CreateFormattedText(text);
				drawingContext.DrawText(formattedText, new Point((3.0 * num - formattedText.Width) / 2.0 + num2, num3));
			}

			drawingContext.Close();
			return drawingVisual;
		}
		return null;
	}

	/// <summary>
	/// 创建住宅色块 DrawingVisual。住宅在地图上占用 2×2 格，
	/// 以所有者玩家旗帜颜色绘制矩形，主视图模式下显示对应怪物名称。
	/// </summary>
	/// <param name="dwelling">住宅数据模型。</param>
	/// <param name="isThumb">是否为缩略图（缩略图不显示文字）。</param>
	internal DrawingVisual? CreateDwelling(DwellingModel dwelling, bool isThumb)
	{
		if (FindResource(dwelling.Flag.ToString()) is SolidColorBrush brush)
		{
			double num = isThumb ? ThumbCellSize : (double)CellSize;

			DrawingVisual drawingVisual = new DrawingVisual();
			using DrawingContext drawingContext = drawingVisual.RenderOpen();

			// 住宅区域左上角（Y 减 1 使顶部对齐，X 直接用格坐标）
			double num2 = (double)(int)dwelling.LocationX * num;
			double num3 = (double)(dwelling.LocationY - 1) * num;

			Pen pen = new Pen(brush, 1.0);
			Rect rectangle = default(Rect);
			rectangle.X = num2;
			rectangle.Y = num3;
			rectangle.Height = num * 2.0;
			rectangle.Width = 2.0 * num;
			drawingContext.DrawRectangle(brush, pen, rectangle);

			// 主视图显示对应怪物名称（从 HeroViewModel.Creatures 中按 ID 查找）
			if (!isThumb)
			{
				FormattedText formattedText = CreateFormattedText(HeroViewModel.Creatures.FirstOrDefault((Creature item) => item.ID == dwelling.Creature)?.Name ?? "缺省");
				drawingContext.DrawText(formattedText, new Point((2.0 * num - formattedText.Width) / 2.0 + num2, num3));
			}

			drawingContext.Close();
			return drawingVisual;
		}
		return null;
	}

	/// <summary>
	/// 创建圣杯标记 DrawingVisual。以资源字典 "Grail" 画刷颜色绘制 X 形对角线，
	/// 覆盖圣杯所在的那一格（1×1 格大小），表示地图上圣杯的位置。
	/// </summary>
	/// <param name="map">地图数据模型（从中读取 GrailX/GrailY）。</param>
	/// <param name="isThumb">是否为缩略图。</param>
	internal DrawingVisual? CreateGrail(MapModel map, bool isThumb)
	{
		if (FindResource("Grail") is SolidColorBrush brush)
		{
			double num = isThumb ? ThumbCellSize : (double)CellSize;

			DrawingVisual drawingVisual = new DrawingVisual();
			using DrawingContext drawingContext = drawingVisual.RenderOpen();

			// 计算圣杯格的四角坐标
			Point point = new Point((double)map.GrailX * num, (double)map.GrailY * num);                              // 左上
			Point point2 = new Point((double)(map.GrailX + 1) * num, (double)(map.GrailY + 1) * num);                 // 右下
			Point point3 = new Point((double)map.GrailX * num, (double)(map.GrailY + 1) * num);                       // 左下
			Point point4 = new Point((double)(map.GrailX + 1) * num, (double)map.GrailY * num);                       // 右上

			// 画 X 形：左上→右下 和 左下→右上 两条粗线
			Pen pen = new Pen(brush, 5.0);
			drawingContext.DrawLine(pen, point, point2);
			drawingContext.DrawLine(pen, point3, point4);

			drawingContext.Close();
			return drawingVisual;
		}
		return null;
	}

	/// <summary>
	/// 创建带图标的地图标记（主视图模式）。将英雄图标绘制到指定格坐标，
	/// 如果 highlight=true 则添加金色发光阴影效果。
	/// </summary>
	/// <param name="icon">英雄图标 ImageSource。</param>
	/// <param name="x">地图格坐标 X。</param>
	/// <param name="y">地图格坐标 Y。</param>
	/// <param name="highlight">是否添加高亮（金色阴影）。</param>
	private DrawingVisual CreateMapSign(ImageSource icon, int x, int y, bool highlight)
	{
		DrawingVisual drawingVisual = new DrawingVisual();
		using DrawingContext drawingContext = drawingVisual.RenderOpen();

		Rect rectangle = default(Rect);
		rectangle.X = x * CellSize;
		rectangle.Y = y * CellSize;
		rectangle.Height = CellSize;
		rectangle.Width = CellSize;

		drawingContext.DrawImage(icon, rectangle);

		// 高亮模式：添加金色投影效果（金色描边光晕）
		if (highlight)
		{
			DropShadowEffect effect = new DropShadowEffect
			{
				Color = Colors.Goldenrod,
				BlurRadius = 12.0,
				Direction = 0.0,
				ShadowDepth = 0.0,
				RenderingBias = RenderingBias.Quality
			};
			drawingVisual.Effect = effect;
		}

		drawingContext.Close();
		return drawingVisual;
	}

	/// <summary>
	/// 创建带图标的地图标记（缩略图模式）。将英雄图标绘制到指定格坐标，
	/// 使用 ThumbCellSize（比 CellSize 小得多）以适应缩略图画布尺寸。
	/// </summary>
	/// <param name="icon">英雄图标 ImageSource。</param>
	/// <param name="x">地图格坐标 X。</param>
	/// <param name="y">地图格坐标 Y。</param>
	private DrawingVisual CreateMapSign(ImageSource icon, int x, int y)
	{
		DrawingVisual drawingVisual = new DrawingVisual();
		using DrawingContext drawingContext = drawingVisual.RenderOpen();

		Rect rectangle = default(Rect);
		rectangle.X = (double)x * ThumbCellSize;
		rectangle.Y = (double)y * ThumbCellSize;
		rectangle.Height = ThumbCellSize;
		rectangle.Width = ThumbCellSize;

		drawingContext.DrawImage(icon, rectangle);
		drawingContext.Close();
		return drawingVisual;
	}

	/// <summary>
	/// 创建单行格式化文本（用于在地图元素上绘制标签文字）。
	/// 字体 Arial 12pt，白色，用于在彩色背景上保持可读性。
	/// </summary>
	private static FormattedText CreateFormattedText(string text)
	{
		return new FormattedText(text, CultureInfo.CurrentCulture, FlowDirection.LeftToRight, new Typeface("Arial"), 12.0, Brushes.White, 1.0);
	}
}

