using System.Linq;
using HoMM3.Standard;

namespace HoMMsTrainer.Host;

/// <summary>
/// MapVisualHost 的扩展方法，提供填充/清空网格、英雄、城镇、矿区、住宅、圣杯的快捷操作。
/// </summary>
internal static class MapVisualHostExtensions
{
	/// <summary>
	/// 如果网格 DrawingVisual 已存在于子元素集合中，从子元素集合中移除它。
	/// </summary>
	internal static void ClearGrid(this MapVisualHost host)
	{
		if (host.Children.IndexOf(host.Grid) > -1)
			host.Children.Remove(host.Grid);
	}

	/// <summary>
	/// 如果网格 DrawingVisual 尚未添加到子元素集合，则创建并插入到索引 0（网格层）。
	/// 根据 IsMain 属性决定使用主视图格子大小还是缩略图格子大小。
	/// </summary>
	internal static void FillGrid(this MapVisualHost host)
	{
		if (host.Children.IndexOf(host.Grid) == -1)
		{
			host.Grid = host.IsMain ? host.CreateGrid(isThumb: false) : host.CreateGrid(isThumb: true);
			host.Children.Insert(0, host.Grid);
		}
	}

	/// <summary>
	/// 从子元素集合中移除当前层（地上/地下）的所有英雄 DrawingVisual。
	/// 从 Hero 缓存索引开始连续移除，数量等于当前层英雄数量。
	/// </summary>
	internal static void ClearHero(this MapVisualHost host)
	{
		int num = host.Children.IndexOf(host.Hero);
		if (num > 0)
		{
			// 筛选当前层（Z 坐标匹配）的英雄数量
			HeroModel[] array = (from HeroModel item in host.Heroes
								 where (int)item.LocationZ == (host.IsUnderground ? 1 : 0)
								 select item).ToArray();
			host.Children.RemoveRange(num, array.Length);
		}
	}

	/// <summary>
	/// 如果英雄 DrawingVisual 尚未添加，则为当前层所有英雄创建 DrawingVisual 并添加到子元素集合。
	/// 第一个英雄缓存到 host.Hero，后续英雄直接追加到 children（因为英雄数量可变）。
	/// </summary>
	internal static void FillHero(this MapVisualHost host)
	{
		if (host.Children.IndexOf(host.Hero) != -1)
			return;

		// 筛选当前层英雄
		HeroModel[] array = (from HeroModel item in host.Heroes
							 where (int)item.LocationZ == (host.IsUnderground ? 1 : 0)
							 select item).ToArray();

		var heroModel = array.ElementAtOrDefault(0);
		if (heroModel != null)
		{
			// 第一个英雄缓存到 host.Hero
			host.Hero = host.IsMain ? host.CreateHero(heroModel, highlight: false) : host.CreateHero(heroModel);
			host.Children.Add(host.Hero);

			// 其余英雄追加（不缓存，仅追加到 children）
			for (int num = 1; num < array.Length; num++)
				host.Children.Add(host.IsMain ? host.CreateHero(array.ElementAt(num), highlight: false) : host.CreateHero(array.ElementAt(num)));
		}
	}

	/// <summary>
	/// 从子元素集合中移除当前层的所有城镇 DrawingVisual。
	/// </summary>
	internal static void ClearTown(this MapVisualHost host)
	{
		int num = host.Children.IndexOf(host.Town);
		if (num > 0)
		{
			TownModel[] array = (from TownModel item in host.Towns
								 where (int)item.LocationZ == (host.IsUnderground ? 1 : 0)
								 select item).ToArray();
			host.Children.RemoveRange(num, array.Length);
		}
	}

	/// <summary>
	/// 如果城镇 DrawingVisual 尚未添加，则为当前层所有城镇创建 DrawingVisual 并插入到索引 1（网格之后）。
	/// 第一个城镇缓存到 host.Town，其余追加到其后续位置。
	/// </summary>
	internal static void FillTown(this MapVisualHost host)
	{
		if (host.Children.IndexOf(host.Town) != -1)
			return;

		var array = (from TownModel item in host.Towns
					 where (int)item.LocationZ == (host.IsUnderground ? 1 : 0)
					 select item).ToArray();

		var townModel = array.ElementAtOrDefault(0);
		if (townModel != null)
		{
			host.Town = host.IsMain ? host.CreateTown(townModel, isThumb: false) : host.CreateTown(townModel, isThumb: true);
			host.Children.Insert(1, host.Town);

			for (int num = 1; num < array.Length; num++)
				host.Children.Insert(1 + num, host.IsMain ? host.CreateTown(array.ElementAt(num), isThumb: false) : host.CreateTown(array.ElementAt(num), isThumb: true));
		}
	}

	/// <summary>
	/// 从子元素集合中移除当前层的所有矿区 DrawingVisual。
	/// </summary>
	internal static void ClearMine(this MapVisualHost host)
	{
		int num = host.Children.IndexOf(host.Mine);
		if (num > 0)
		{
			MineModel[] array = (from MineModel item in host.Mines
								 where (uint)item.LocationZ == (host.IsUnderground ? 1u : 0u)
								 select item).ToArray();
			host.Children.RemoveRange(num, array.Length);
		}
	}

	/// <summary>
	/// 如果矿区 DrawingVisual 尚未添加，则为当前层所有矿区创建 DrawingVisual 并插入到索引 1。
	/// </summary>
	internal static void FillMine(this MapVisualHost host)
	{
		if (host.Children.IndexOf(host.Mine) != -1)
			return;

		var array = (from MineModel item in host.Mines
					 where (uint)item.LocationZ == (host.IsUnderground ? 1u : 0u)
					 select item).ToArray();

		var mineModel = array.ElementAtOrDefault(0);
		if (mineModel != null)
		{
			host.Mine = host.IsMain ? host.CreateMine(mineModel, isThumb: false) : host.CreateMine(mineModel, isThumb: true);
			host.Children.Insert(1, host.Mine);

			for (int num = 1; num < array.Length; num++)
				host.Children.Insert(1 + num, host.IsMain ? host.CreateMine(array.ElementAt(num), isThumb: false) : host.CreateMine(array.ElementAt(num), isThumb: true));
		}
	}

	/// <summary>
	/// 从子元素集合中移除当前层的所有住宅 DrawingVisual。
	/// </summary>
	internal static void ClearDwelling(this MapVisualHost host)
	{
		int num = host.Children.IndexOf(host.Dwelling);
		if (num > 0)
		{
			DwellingModel[] array = (from DwellingModel item in host.Dwellings
									 where (uint)item.LocationZ == (host.IsUnderground ? 1u : 0u)
									 select item).ToArray();
			host.Children.RemoveRange(num, array.Length);
		}
	}

	/// <summary>
	/// 如果住宅 DrawingVisual 尚未添加，则为当前层所有住宅创建 DrawingVisual 并插入到索引 1。
	/// </summary>
	internal static void FillDwelling(this MapVisualHost host)
	{
		if (host.Children.IndexOf(host.Dwelling) != -1)
			return;

		var array = (from DwellingModel item in host.Dwellings
					 where (uint)item.LocationZ == (host.IsUnderground ? 1u : 0u)
					 select item).ToArray();

		var dwellingModel = array.ElementAtOrDefault(0);
		if (dwellingModel != null)
		{
			host.Dwelling = host.IsMain ? host.CreateDwelling(dwellingModel, isThumb: false) : host.CreateDwelling(dwellingModel, isThumb: true);
			host.Children.Insert(1, host.Dwelling);

			for (int num = 1; num < array.Length; num++)
				host.Children.Insert(1 + num, host.IsMain ? host.CreateDwelling(array.ElementAt(num), isThumb: false) : host.CreateDwelling(array.ElementAt(num), isThumb: true));
		}
	}

	/// <summary>
	/// 如果圣杯存在于当前层（Z 坐标匹配）且尚未添加，则创建圣杯 DrawingVisual 并插入到索引 1。
	/// </summary>
	internal static void FillGrail(this MapVisualHost host)
	{
		// 只有圣杯 Z 坐标与当前层匹配时才绘制（0=地上，1=地下）
		if ((int)host.Map.GrailZ == (host.IsUnderground ? 1 : 0) && host.Children.IndexOf(host.Grail) == -1)
		{
			host.Grail = host.IsMain ? host.CreateGrail(host.Map, isThumb: false) : host.CreateGrail(host.Map, isThumb: true);
			host.Children.Insert(1, host.Grail);
		}
	}
