/// <summary>
/// 数据读写服务基类，封装从游戏内存读取数据、写入待变更数据、提交到内存的完整流程。
///
/// 设计模式：
/// - 泛型约束：TPropertyEnum 为属性地址枚举，TModel 为数据模型类型
/// - 读写分离：Read* 系列方法从内存/缓冲区读取，AddToWritingData 系列仅将变更加入队列
/// - 脏数据写入：SaveDataAll 只保存有脏标记的模型；SaveToMemory 执行实际写入
/// - 强制写入：对于只读内存区域（如代码段），使用 WriteProcessMemoryEnforced 先改页面属性
/// </summary>
public abstract class Service<TPropertyEnum, TModel>(ProcessIO process, ICollection<TModel> models)
    where TPropertyEnum : struct, Enum
    where TModel : Model<TPropertyEnum>, new()
{
    protected ICollection<TModel> _models = models;
    protected ProcessIO _process = process;

    /// <summary>数据块基址（如英雄数组的起始地址）</summary>
    protected int _blockAddress;

    /// <summary>每个数据单元的字节大小</summary>
    protected int _blockSize;

    /// <summary>待写入的普通变更（直接 WriteProcessMemory）</summary>
    protected Dictionary<int, byte[]> _writingData = new Dictionary<int, byte[]>();

    /// <summary>待写入的强制变更（需先改页面属性）</summary>
    protected Dictionary<int, byte[]> _writingDataEnforced = new Dictionary<int, byte[]>();

    /// <summary>属性枚举 → (偏移量, 长度) 的地址映射表</summary>
    protected Dictionary<TPropertyEnum, (int Offset, int LengthOrCount)> _addresses = new Dictionary<TPropertyEnum, (int, int)>();

    /// <summary>加载配置文件中的地址映射（子类实现）</summary>
    public abstract void LoadSettings();

    /// <summary>设置数据块的基址和单元大小（子类实现）</summary>
    public abstract void SetBlock(int address, int offset, int size);

    /// <summary>从内存加载单个数据单元（子类实现）</summary>
    public abstract bool LoadData(int index);

    /// <summary>
    /// 根据 Index 获取或创建模型实例。

[515 more lines in file. Use offset=51 to continue.]

    /// 若集合中已存在该 Index 的模型，直接返回；否则新建并加入集合。
    /// </summary>
    protected virtual TModel GetModel(int index)
    {
        TModel? val = _models.FirstOrDefault(item => item.Index == index);
        if (val == null)
        {
            val = new TModel { Index = index };
            _models.Add(val);
        }
        return val;
    }

    /// <summary>
    /// 批量加载数据（最多 maxCount 个），遇首个加载失败时停止，
    /// 并删除集合中超出范围的多余模型。
    /// </summary>
    public virtual void LoadDataAll(int maxCount = 255)
    {
        for (int i = 0; i < maxCount; i++)
        {
            if (!LoadData(i))
            {
                i++;
                for (int j = i; j < _models.Count; j++)
                {
                    _models.Remove(_models.ElementAt(j));
                }
                break;
            }
        }
    }

    /// <summary>重置：清空块信息、地址表和待写入队列</summary>
    public virtual void Reset()
    {
        _blockAddress = 0;
        _blockSize = 0;
        _addresses.Clear();
        _writingData.Clear();
        _writingDataEnforced.Clear();
    }

    /// <summary>保存单个模型到内存（子类实现）</summary>
    public abstract void SaveData(TModel model);

    /// <summary>遍历所有有脏标记的模型，调用 SaveData</summary>
    public virtual void SaveDataAll()
    {
        foreach (TModel item in _models.Where(item => item.GetDirtyData().Any()))
        {
            SaveData(item);
        }
    }

    /// <summary>将所有待写入变更提交到游戏内存</summary>
    public void SaveToMemory()
    {
        foreach (var writingDatum in _writingData)
        {
            _process.WriteProcessMemory(writingDatum.Key, writingDatum.Value);
        }
        _writingData.Clear();

        foreach (var item in _writingDataEnforced)
        {
            _process.WriteProcessMemoryEnforced(item.Key, item.Value);
        }
        _writingDataEnforced.Clear();
    }

    /// <summary>仅提交强制写入队列（不处理普通队列）</summary>
    protected void SaveToMemoryEnforced()
    {
        foreach (var item in _writingDataEnforced)
