    # 匹配方法定义行
    escaped = re.escape(method_pattern)
    pattern = rf'^(	+)((?:internal|public|private|protected)\s+(?:static\s+)?(?:async\s+)?(?:void|int|T|Task<[^>]+>|ICommand|(?:MintPlayer\.[^.]+\.)?ObservableCollection<[^>]+>)\s+{escaped})'
    m = re.search(pattern, c, re.MULTILINE)
    if not m:
        # 尝试更宽松的匹配
        pattern2 = rf'^(	+)((?:internal|public|private|protected)\s+.+?{re.escape(method_pattern)})'
        m = re.search(pattern2, c, re.MULTILINE)

    if m:
        pos = m.start()
        new_doc = f"
{doc}
"
        c = c[:pos] + new_doc + c[pos:]
        count += 1
        print(f"  + {method_pattern[:30]}")
    else:
        print(f"  ? {method_pattern[:30]} (not matched)")

