/// <summary>
/// 内存扫描器，负责在目标进程中查找指定字节模式的内存地址。
/// 基于 Sunday 快速匹配算法，配合 WinAPI 遍历进程内存区域。
/// </summary>
public class Scanner
{
    private readonly ProcessIO _process;

