        // 扫描前几个 dword，寻找连续 x,y,w,h，其中 w=298 且 h=cfg.window_height。
        for (int base = 0; base <= 5; ++base) {
            int old_y = sp[base + 1];
            int w = sp[base + 2];
            int hgt = sp[base + 3];
            if (w == 298 && hgt == cfg.window_height) {
                int new_y = ClampCreatureDlgY(old_y);
                if (new_y != old_y) {
                    sp[base + 1] = new_y;
